export default [{"id":111,"question":"ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","title":"حكم زواج المتعة والطلاق فيه","answer":"الجواب: زواج المتعة لا يجوز، وهو باطل، وهو أن يتزوَّجها مدةً معلومةً، يعني: يتفقون على أن يتزوَّجها سنةً ثم يُفارقها، أو شهرًا، أو شهرين.\nوكان مباحًا في أول الإسلام، ثم نهى عنه النبيُّ ﷺ ونُسِخَ وقال: إنَّ الله حرَّمه إلى يوم القيامة.\nوإذا تزوَّج متعةً يُطلِّق؛ لأن فيه خلافًا بين أهل العلم، فإذا تزوَّجها متعةً طلَّقها طلقةً واحدةً؛ حلًّا للمشكل، وإزالةً لهذا النكاح المُشتبه، طلقة واحدة فقط.","link":"https://binbaz.org.sa/fatwas/3548/حكم-زواج-المتعة-والطلاق-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0095.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":531,"question":"بالنسبة لنكاح الشغار هل يبطل؟","title":"هل يبطل نكاح الشغار بعد عقده؟","answer":"الجواب: باطل؛ يُفَرّق بينهما، ويُجَدّد إذا كانت راضية.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6362/هل-يبطل-نكاح-الشغار-بعد-عقده","audio":"https://files.zadapps.info/binbaz.org.sa/maram097 - 02 - .mp3","categories":["الأنكحة المحرمة"]},{"id":543,"question":"ضابط الفرق بين نكاح المتعة والنكاح بنية الطلاق؟","title":"الفرق بين نكاح المتعة والنكاح بنية الطلاق","answer":"الجواب: المتعة أن يشترطا جميعًا أن المدة شهرين ثلاثة سنة سنتين، ثم تنتهي بانفصال، كإيجار البيت.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6374/الفرق-بين-نكاح-المتعة-والنكاح-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/maram109 - 04 - .mp3","categories":["الأنكحة المحرمة"]},{"id":546,"question":"هل يُشترط عدم الإضمار في نكاح التحليل بالنسبة للمرأة أو الرجل؟","title":"حكم النية في نكاح التحليل","answer":"الجواب: نيته أو مقصده عدم التحليل ولو ما بَيَّن للناس.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6377/حكم-النية-في-نكاح-التحليل","audio":"https://files.zadapps.info/binbaz.org.sa/maram112 - 04 - .mp3","categories":["الأنكحة المحرمة"]},{"id":547,"question":"بطلان العقد يقتضي الزنا؟","title":"هل بطلان عقد النكاح يقتضي الزنا؟","answer":"الجواب: يكون زانيًا في المعنى، ويستحق أن يؤدّب إذا عرف هذا؛ لأنه قد يجهل الأحكام الشرعية فيستحق أن يؤدّب.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6378/هل-بطلان-عقد-النكاح-يقتضي-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/maram113 - 04 - .mp3","categories":["الأنكحة المحرمة"]},{"id":548,"question":"إذا أنكر الزوج الثاني الوطء: القول قول مَن؟","title":"مَن يُعتبر قوله إذا أنكر الزوج الثاني الوطء؟","answer":"الجواب: القول قولُه، ما تُصَدَّق هي، هو الذي يُصَدَّق، الزوج الشرعي الثاني، إذا قال: وَطِئْت؛ فهو يُصَدَّق، أما هي ما تُصَدَّق؛ لأنها متهمة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6379/من-يعتبر-قوله-اذا-انكر-الزوج-الثاني-الوطء","audio":"https://files.zadapps.info/binbaz.org.sa/maram114 - 02 - .mp3","categories":["الأنكحة المحرمة"]},{"id":726,"question":"ورد كثيرٌ من الأسئلة يشكو فيها النِّساء من ترك أزواجهن للصلاة، فما حكم ذلك؟ وهل تبقى معه؟ جزاكم الله خيرًا.","title":"حكم الزواج بمن لا يصلي والبقاء معه","answer":"الجواب: سمعتم أنَّ الصلاة عمود الإسلام، مَن حفظها حفظ دينه، ومَن ضيَّعها فهو لما سواها أضيع، وسمعتم أنَّ تركها كفرٌ أكبر في أصح قولي العلماء وإن لم يجحد وجوبها، أما إن جحد وجوبها أو استهزأ بها كفر عند جميع المسلمين -نسأل الله العافية.\nفالذي لا يُصلي لا تبقى معه زوجته، بل يجب أن تُفارقه وتذهب إلى أهلها، وهي أولى بأولادها، وأحق بأولادها منه، حتى يتوب الله عليه، فإذا تاب توبةً صادقةً معلومةً وأحبّ الرجوع إليها فلا بأس.\nوهكذا إذا كان يُصلي وهي لا تُصلي يُفارقها أيضًا حتى تتوب إلى الله توبةً صادقةً؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، وما جاء في معنى ذلك من الآيات والأحاديث.","link":"https://binbaz.org.sa/fatwas/20587/حكم-الزواج-بمن-لا-يصلي-والبقاء-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0540فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الأنكحة المحرمة"]},{"id":807,"question":"يقول هذا السائل: هل يجوز زواج البدل بالمهر، حيث يدفع كلُّ واحدٍ منهم أربعين ألفًا بشرط الرضا بينهما؟","title":"هل يجوز زواج البدل بالمهر؟","answer":"الجواب: البدل لا يجوز، وهو الشِّغار، ولو دفعوا مهرًا، ولو تراضوا عليه، ما دام كل واحدٍ شرط في النكاح المرأة الأخرى: زوجني بنتك، وأُزوجك بنتي، هذا لا يجوز، النبي نهى عن هذا عليه الصلاة والسلام، فالشغار أن يقول: زوجني بنتك، وأُزوجك بنتي، أو: زوجني أختك، وأُزوجك أختي. هذا هو الشغار، وفساده كثير، وشرُّه عظيم، وهو وسيلة إلى إكراه النساء، وظلم النساء، ووسيلة إلى وجود النزاع الكثير بين الأسرتين، كلما زعلت هذه زعلت هذه، وكلما جرى شيءٌ بين هذا وزوجته جرى بين الأخرى كذلك وزوجها، فالحاصل أنه منكرٌ ونكاحٌ فاسدٌ لا يجوز.","link":"https://binbaz.org.sa/fatwas/20838/هل-يجوز-زواج-البدل-بالمهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0635هل يجوز زواج البدل؟ابن باز فتاوى المحاضرات.mp3","categories":["الأنكحة المحرمة"]},{"id":813,"question":"مَن وقع في زواج الشِّغار فما هو الواجب عليه؟","title":"ماذا يجب على مَن وقع في زواج الشِّغار؟","answer":"الجواب: تقدَّم أن الواجب عليه أن يُجدد النكاح إذا كانت له رغبة ولها رغبة، إذا كان كلٌّ منهما له رغبة في الآخر يُجدد النكاح بدون شرط المرأة الأخرى، يُجدده بعقدٍ جديدٍ ليس فيه شرطُ المرأة الثانية، إذا كانت ترغبه زوجته يُجدد.","link":"https://binbaz.org.sa/fatwas/20844/ماذا-يجب-على-من-وقع-في-زواج-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0640من قوع في زواج الشغار ما واجب عليه؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأنكحة المحرمة"]},{"id":877,"question":"سمعتُ بأنَّ سماحتكم قد أجاز زواج المُتعة، فهل هذا صحيح؟","title":"حكم الزواج بنية الطلاق وتمييزه عن المتعة","answer":"الجواب: ليس بصحيحٍ، هذا باطلٌ، وإنما صدرت فتوى مني ومن اللجنة الدائمة بأنَّ الإنسان إذا تزوج وفي نيَّته الطلاق لا بأس عليه، وليس هذا من المتعة، هذا بينه وبين الله، إذا تزوج ونيّته أن يُطلِّق إذا فرغ من دراسته، أو من تجارته، أو من كونه سفيرًا، أو ما أشبه ذلك لا يضرُّه، هذا هو الصواب الذي عليه جمهور أهل العلم، حكاه الموفق في \"المغني\" عن جمهور أهل العلم، ولم يذكر خلافه إلا الأوزاعي.\nأما المتعة: فهي أن يتفق على مدةٍ معلومةٍ مع وليها أو معها: على شهرٍ، على شهرين، على سنةٍ، هذه المتعة، يتَّفقا على شيءٍ معلومٍ شرطًا بينهما.","link":"https://binbaz.org.sa/fatwas/20924/حكم-الزواج-بنية-الطلاق-وتمييزه-عن-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0719ما حكم الزواج بنية الطلاق؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة"]},{"id":940,"question":"هل يجوز للمسلم أن يحضر حفلات الزواج إذا كان يقوم على الشِّغار –أي: البدل؟ وهل يجوز له أن يأكل من تلك الوليمة؟","title":"حكم حضور وليمة زواج يقوم على الشِّغار","answer":"الجواب: إذا كان النكاح شغارًا ما يجوز له حضوره، ولا المشاركة، بل يُنكر ذلك، وينهى عنه؛ لأن نكاح الشِّغار لا يجوز.\nنكاح الشغار أن يقول: زوجني وأُزوجك، ويشترطان الزواج، هذا يُزوج هذا بنته، أو أخته، أو يُزوج ولده، أو أخاه، يُقال له: نكاح الشِّغار، وهي المساواة والمشارطة، كل واحدٍ يشرط على الآخر أن يُزوجه، أو يُزوج ولده، أو يُزوج أخاه، ويتعاقدان على ذلك، هذا يقال له: نكاح الشِّغار، وهو باطلٌ لا يجوز على الصحيح مطلقًا، ولو سُمي فيه مهر، فإذا عرفتَ ذلك أنه شغار فلا تحضره، بل أنكر عليهم، قل: يا إخواني، هذا لا يجوز، ولا يحلّ لكم ذلك، ولا تحضرهم، ولا تحضر الوليمة أيضًا؛ لأن حضور الوليمة نوعٌ من إقراره.","link":"https://binbaz.org.sa/fatwas/20973/حكم-حضور-وليمة-زواج-يقوم-على-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0769هل يجوز للمسلم أن يحضر حفلات الزواج إذا كان يقوم على الشغار أي البدل؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأنكحة المحرمة"]},{"id":1470,"question":"طلَّق امرأته وأتت بأبناء من زوجٍ غيره، وأحد الأبناء هؤلاء بنت، يقول: هل يجوز لي الآن أن أتزوج بنتَ زوجتي السابقة؟","title":"حكم الزواج ببنت المُطَلَّقة من زوج آخر","answer":"الجواب:\nما دام قد دخل بها فهي مَحْرَمٌ له.\nس: مَن هو المحرم؟\nج: مَحْرَم لزوجها السابق، إذا جاءت من الزوج الجديد تكون محارم للزوج السابق إذا كان قد دخل بها، قد وطئها يعني.\nس: وهي تغطي عنه الزوجة المطلقة؟\nج: نعم، بانت منه إذا كان طلاقًا بائنًا أو رجعيًّا، وخرجت من العدة صارت أجنبيةً، والله يقول: وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ [النساء:23]، والدخول: الوطء.\nس: يعني لا تقف الآية عند الربيبة الموجودة؟\nج: لا، ما هو بلزوم، الأولاد الذين كانوا قبله والذين جاءوا بعده كلهم محارم إذا كانوا بناتًا، فِي حُجُورِكُمْ هذا وصف أغلبي، ما هو بلازم، ولهذا قال بعده: فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ، ولم يقل: فإن لم يكونوا في حجوركم فلا جناح عليكم. فالحجور وصفٌ أغلبيٌّ، ما هو بلازمٍ، وقال النبيُّ ﷺ لأم حبيبة: لا تعرضنَّ عليَّ بناتكن ولا أخواتكن لأم سلمة.","link":"https://binbaz.org.sa/fatwas/21568/حكم-الزواج-ببنت-المطلقة-من-زوج-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الزواج ببنت مطلقته من زوج آخر.mp3","categories":["الأنكحة المحرمة"]},{"id":2169,"question":"والسؤال الثالث يقول: حصل بيني وبين قريبٍ لي شغار، وطبعًا العقد باطل، والآن طلَّق أحدُنا، ويريد الآخر الاستمرار على زوجته؟","title":"حكم شخصين تزوجا بالشغار ثم طَلَّق أحدهما","answer":"الجواب:\nيُجدد العقد بدون شرط الشّغار، مع التوبة مما مضى.","link":"https://binbaz.org.sa/fatwas/22290/حكم-شخصين-تزوجا-بالشغار-ثم-طلق-احدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الطلاق في زواج الشغار.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":5113,"question":"هنا السائلة تقول: ولدي يريد الزواج من فتاة أنا أرضعت أختها، هل يصح ذلك؟","title":"هل يجوز الزواج بفتاة رضعت أختها من أم الزوج؟","answer":"الجواب: نعم إذا تزوج التي ما أرضعت، أما أختها التي أرضعتها تكون أختًا له إذا  كان رضاعًا تامًّا خمس مرات أو أكثر في الحولين، إذا كان الرضاع خمس مرات أو أكثر في الحولين تصير أختًا له، أما أختها التي ما رضعت فلا بأس له أن يتزوج التي ما أرضعتها.","link":"https://binbaz.org.sa/fatwas/30021/هل-يجوز-الزواج-بفتاة-رضعت-اختها-من-ام-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 41.mp3","categories":["الأنكحة المحرمة"]},{"id":5154,"question":"هذا السائل يقول: ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","title":"ما حكم زواج المتعة؟ وما حكم الطلاق فيه؟","answer":"الجواب: زواج المتعة لا يجوز، وهو باطل، وهو أن يتزوَّجها مدةً معلومةً، يعني: يتفقون على أن يتزوَّجها سنةً ثم يُفارقها، أو شهرًا، أو شهرين. وكان مباحًا في أول الإسلام، ثم نهى عنه النبيُّ ﷺ ونُسِخَ وقال: إنَّ الله حرَّمه إلى يوم القيامة. وإذا تزوَّج متعةً يُطلِّق؛ لأن فيه خلافًا بين أهل العلم، فإذا تزوَّجها متعةً طلَّقها طلقةً واحدةً؛ حلًّا للمشكل، وإزالةً لهذا النكاح المُشتبه، طلقة واحدة فقط. ونكاح المتعة هو المؤقت، يتزوجها سنة سنتين شهر شهرين، يسمى نكاح متعة، فهو باطل.","link":"https://binbaz.org.sa/fatwas/30072/ما-حكم-زواج-المتعة-وما-حكم-الطلاق-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 95.mp3","categories":["الأنكحة المحرمة","الطلاق"]},{"id":5229,"question":"سائل يقول: أفيدونا وفَّقكم الله، هل صحيح ما نقلته بعضُ الصحف المحلية والعربية عن فتواكم بجواز زواج المُتعة؟","title":"هل صح ما نُسب للشيخ ابن باز من إجازة زواج المتعة؟","answer":"الجواب: هذا باطلٌ، لا أصلَ لهذا، هذه فتوى الرافضة، هم الذين يُجيزون المتعة، جمعٌ من الرافضة، ليسوا كلهم، بل جمعٌ من الرافضة، والذي صدر منا -اللجنة الدائمة، وأنا واحدٌ منهم، وأنا رئيسهم- أنه لا مانع من أن يتزوج وبنيته الطلاق، هكذا قال صاحبُ \"المُغني\" عن أكثر أهل العلم، ذكره الموفقُ ابن قُدامة في \"المغني\" عن أكثر العلماء؛ أنَّ مَن تزوَّج وفي نيته أنه يُطلق لا يضرُّه ذلك، من دون مشارطة بينه وبين أهل المرأة، ولا بينه وبين المرأة، ولا وليها، ولا يعلم بذلك إلا الله. تزوَّج مثلًا في بلادٍ سافر إليها للدراسة أو لأسبابٍ أخرى أو لأي سببٍ، وفي نيته أنه يُطلق إذا غادر البلد، أو إذا حصل له كذا وكذا، أو لأي سببٍ بنيته وقلبه، بينه وبين الله أنه سيُطلق في المُستقبل، هذا قاله الجمهور. وذهب بعضُ أهل العلم إلى أنَّ هذه النية لا تجوز، ذكروه عن الأوزاعي رحمه الله إمام أهل الشام، وألحقها بالمتعة. وأما الجمهور فيقولون: لا تُلحق بالمتعة؛ لأنها شيءٌ بينه وبين ربِّه، والطلاق مباحٌ له، متى شاء طلَّق، ولو ما نوى هذا الذي صدر. لكن أهل الهوى أو الجهل أو الأغراض الفاسدة إذا سمعوا مثل هذه الفتوى وأشباهها حملوها على أسوأ المحامل، أو ألحقوا بها ما ليس منها.","link":"https://binbaz.org.sa/fatwas/30173/هل-صح-ما-نسب-للشيخ-ابن-باز-من-اجازة-زواج-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 275.mp3","categories":["الأنكحة المحرمة"]},{"id":5242,"question":"بعض المسلمين يُسافرون للدراسة وغيرها إلى الخارج، فهل يجوز أن يتزوج بنية الطلاق؟ وما الفرق بينه وبين زواج المُتعة؟ أرجو توضيح الأمر في هذا وفَّقكم الله.","title":"هل يجوز أن يتزوج بنية الطلاق؟","answer":"الجواب: السفر إلى الخارج فيه خطرٌ عظيمٌ، وفيه بلاءٌ كثيرٌ، فلا يجوز السفر إلى الخارج إلا بشروطٍ مهمةٍ؛ لأنَّ السفر إلى الخارج يُعرِّضه للكفر بالله، ويُعرضه للمعاصي: لشرب الخمور، لتعاطي الزنا، وغير هذا من الشُّرور، ولهذا نصَّ العلماء على تحريم السفر إلى بلاد الكفار؛ عملًا بقول النبي ﷺ: أنا برئٌ من كل مسلمٍ يُقيم بين المشركين، فالإقامة بينهم خطيرةٌ جدًّا، لا للدراسة، ولا لغيرها. فهؤلاء المسافرون من طلبة الثانوي أو المتوسط أو في العالي -الدراسة الجامعية- على خطرٍ عظيمٍ، والواجب على الدولة أن تُؤَمِّن لهم الدراسة في الداخل، وليس لها أن تسمح لهم بالسفر إلى الخارج؛ لما فيه من الخطر العظيم. وقد نشأ عن هذا شرٌّ كثيرٌ: من الردة، والتساهل بالمعاصي، والزنا، والفواحش، وشرب الخمور، كما هو معلومٌ عند مَن سبر أحوالهم. فالواجب منعهم من ذلك، وألا يُسافر إلا الرجال المعروفون بالدِّين والإيمان والعلم والفضل، إذا كان للدعوة إلى الله، أو للتَّخصص في أمورٍ تحتاجها الدولة الإسلامية، والمسافر معروفٌ بالعلم والفضل والإيمان والاستقامة، حتى يدعو إلى الله وينفع الناس هناك، ويتعلم ما تحتاجه منه الدولة، أما هؤلاء الشُّبان الذين يُسافرون فهذا غلطٌ عظيمٌ، ومنكرٌ عظيمٌ، وشرٌّ عظيمٌ، نسأل الله أن يُوفِّق الدولة لمنع ذلك والقضاء عليه. أما الزواج بنية الطلاق: فهذا فيه خلافٌ بين العلماء: منهم مَن كره ذلك، كالأوزاعي رحمه الله وجماعة، وقالوا: إنه يُشبه المتعة، فليس له أن يتزوج بنية الطلاق. وذهب الجمهور -وهم الأكثرون كما قال الموفق ابن قُدامة في \"المغني\"- إلى أنه يجوز إذا كان بينه وبين ربِّه سرًّا، ليس بشرطٍ، كأن يُسافر إلى بلدٍ للدراسة أو لأعمالٍ هناك، ويخشى على نفسه، فيتزوج وبنيته أنه إذا سافر -إذا رجع إلى بلاده- طلَّقها؛ فلا بأس بذلك إذا كان بينه وبين ربِّه، من دون مُشارطةٍ ولا علمٍ ولا اطِّلاعٍ من الولي ولا الزوجة ولا غير ذلك، بل بينه وبين الله، فجمهور أهل العلم يقولون: لا بأس بذلك، وليس من المتعة في شيءٍ؛ لأنه بينه وبين الله، ليس فيه مشارطةٌ. أما المتعة: فهي التي تكون فيها المشارطة على شهرٍ أو شهرين، أو سنة أو سنتين، بينه وبين أهل الزوجة، أو بينه وبين الزوجة، هذه يُقال لها: المتعة، وهي محرَّمة بالإجماع، ولم يتساهل فيها إلا الرافضة، هي محرَّمة بالإجماع. وكان ابن عباسٍ قد توقف فيها، ثم رجع، كان يقول: إنها مثل الميتة للضَّرورة، ولكنه رجع عن ذلك. أما أن يتزوج في بلادٍ سافر إليها للدراسة، أو لكونه سفيرًا، أو لأسبابٍ أخرى، لمسوِّغ شرعيٍّ: سافر واحتاج إلى الزواج خوفًا على نفسه؛ فلا بأس أن يتزوج بنية الطلاق إذا أراد أن يرجع، وترك هذه النية أوْلى، فكونه يتزوج بنية الرغبة أو المصلحة أوْلى وأفضل؛ خروجًا من الخلاف، ولكن لو نواه فيما بينه وبين الله، وليس بشرطٍ بينه وبين أهل الزوجة، ولا بين الزوجة وبينه، فهذا ليس بمتعةٍ؛ لأنه نيَّة بينه وبين الله، والإنسان له أن يُطَلِّق متى شاء، ما هو ممنوع من الطلاق، ولو ما نوى.","link":"https://binbaz.org.sa/fatwas/30653/هل-يجوز-ان-يتزوج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 516.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج"]},{"id":5690,"question":"الشغار معروف أنه حرام، ولكن فيه اثنين وقعوا فيه، وجاء لهم عيال الآن بعد خمس سنوات، أو سبع سنوات، فماذا عليهم؟","title":"كيفية التخلص من زواج الشغار","answer":"الجواب:  يجددوا النكاح، ولا عليهم شيء، يجددوا النكاح مع التوبة والاستغفار، إذا كانت الزوجة ترغب في زوجها يجددوا النكاح بدون شرط الأخرى، يعقد عقدًا جديدًا بدون شرط المرأة الأخرى، كل واحد مع التوبة والاستغفار، والتي ما تبيه يطلقها طلقة واحدة. السؤال: لازم من التجديد بارك الله فيك؟ الجواب: كل واحد يجدد النكاح بدون الشرط القبيح، بدون شرط المرأة الثانية.","link":"https://binbaz.org.sa/fatwas/995/كيفية-التخلص-من-زواج-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_24.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5694,"question":"الشغار معروف أنه حرام، ولكن فيه اثنين وقعوا فيه، وجاء لهم عيال الآن بعد خمس سنوات، أو سبع سنوات، فماذا عليهم؟","title":"كيفية التخلص من زواج الشغار","answer":"الجواب:  يجددوا النكاح، ولا عليهم شيء، يجددوا النكاح مع التوبة والاستغفار، إذا كانت الزوجة ترغب في زوجها يجددوا النكاح بدون شرط الأخرى، يعقد عقدًا جديدًا بدون شرط المرأة الأخرى، كل واحد مع التوبة والاستغفار، والتي ما تبيه يطلقها طلقة واحدة. السؤال: لازم من التجديد بارك الله فيك؟ الجواب: كل واحد يجدد النكاح بدون الشرط القبيح، بدون شرط المرأة الثانية.","link":"https://binbaz.org.sa/fatwas/995/كيفية-التخلص-من-زواج-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_24.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5789,"question":"ما حكم الإسلام في عمل المرأة في التعليم، والطب، والتمريض؟ وكيف يمكن التوفيق بين ذلك، وبين قول الله : وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]؟","title":"حكم عمل المرأة في التعليم والطب وغير ذلك","answer":"الجواب: المرأة لها أعمال، والرجل له أعمال، يشتركان في بعض، وينفرد كل واحد عن بعض، فالمرأة تعمل الأعمال المناسبة لها: كتدريس النساء، وإدارة مدارس النساء، وتمريض النساء، وتطبيب النساء، ونحو ذلك من الأعمال التي تكون في ميدان النساء، وما تدعو الحاجة إلى أن تعمل في حاجة الرجل، كأن تمرضه إذا دعت الحاجة إلى ذلك مع الحجاب، ومع العفة، والبعد عن الخلوة، ونحو ذلك، كما جرى للنساء مع النبي ﷺ في بعض الغزوات، كنا يسقين المرضى الماء، ويداوين الجرحى، ويكن مع المسلمين في المعسكرات للمصلحة مع الحجاب، ومع الستر، ومع العفة، ومع النزاهة، والبعد عن أنواع الريب.  فإذا كانت المرأة في هذا المقام، مقام الحجاب، والصيانة، والعفة، واحتيج إليها في طب الرجل عند عدم من يطبه من الرجال فلا بأس أن تسقيه الدواء، ولا بأس أن تعمل الدواء عند الحاجة، وإلا فميدانها هو ميدان النساء في الطب، والتعليم، والتمريض، وغير ذلك. والرجل ميدانه ميدان الرجال في الطب، والتعليم وغير ذلك، هذا هو المشروع، وهو الطريق المعروف، وهو الطريق المسلوك، وإذا دعت الحاجة إلى أن يقوم هذا بهذا أن يطب الرجل المرأة، وتطب المرأة الرجل عند الحاجة؛ فلا بأس، مع مراعاة الحجاب، ومراعاة عدم الخلوة، كما هو معلوم، كما جاءت به السنة عن رسول الله، عليه الصلاة والسلام.  ولا يخالف هذا قوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب: 33] فالآية لها معنيان: أحدهما: أن المعنى الزمن بيوتكن، ولا تخرجن إلا لحاجة، لمصلحة، وهذا هو الواقع فإن المرأة أفضل لها بيتها إلا من حاجة، إن خرجت لمصلحة تصلي في الجماعة مع حجاب وستر، كن يخرجن في عهد النبي ﷺ كن يخرجن إلى الصلاة مع النبي ﷺ، كذلك كن يخرجن لعيادة المريض في قضاء حاجة من الحاجات؛ لشراء حاجة من السوق تحتاج إليها، وما أشبه ذلك. فإذا كان الخروج لحاجة، ومصلحة فلا بأس، إنما المطلوب هو مكثها في البيت عند عدم الحاجة للخروج. المعنى الثاني: أنها من الوقار، والحشمة، وأن المعنى يعني الْزمن الحشمة، والزمن الوقار، ولا تكن متبذلات، ولا متساهلات، والمعنى الأول هو المشهور، وهو بمعنى اللبث، بمعنى الوقار في البيت، فلا منافاة بين هذا وهذا.","link":"https://binbaz.org.sa/fatwas/1111/حكم-عمل-المراة-في-التعليم-والطب-وغير-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_117.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5885,"question":"إذا كان هناك نصراني قد تزوج من مسلمة، وأنجب أطفالًا، ما حكم أطفالهم في الشرع؟","title":"حكم زواج النصراني بالمسلمة وحكم أولادهما","answer":"الجواب: زواج النصراني من المسلمة زواج باطل، الله -جل وعلا- يقول: وَلَا تُنْكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221] فلا يجوز نكاح الكافر من المسلمة، والله يقول: لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10].  فإذا تزوجها؛ فالنكاح باطل، والأولاد زنا، أولاد زنا يلحقون بأمهم، ولا يلحقون به، ينسبون إلى أمهم، اللهم إلا إن كانوا جهالًا، ما عرفوا الإسلام، فهذا له شأن، النكاح باطل، والأولاد ينسبون إليه لأجل جهله، إن كان جاهلًا، وهي جاهلة، فالنكاح يكون باطلًا، ولكن ينسب الأولاد إلى أبيهم بسبب الجهل؛ لأنه وطء شبهة.  أما إذا كان يعرف حكم الإسلام، وهي تعرف حكم الإسلام، يعرفون حكم الله، ولكن تساهلوا، ولم يبالوا بحكم الله؛ فيكون الأولاد ولد زنا، ينسبون لأمهم، ولا ينسبون لأبيهم، ويؤدب هو، ويقام عليه الحد الشرعي بوطئه المرأة المسلمة بغير حق، وهذا هو الواجب عند القدرة عليه، ومن دولة الإسلام. السؤال: وإذا أسلم؟ الجواب: يفرق بينهما، وإذا أسلم بعد ذلك يكون بعد ذلك بنكاح جديد، يتزوج من جديد إذا أسلم، وهداه الله، يتزوجها من جديد.","link":"https://binbaz.org.sa/fatwas/1213/حكم-زواج-النصراني-بالمسلمة-وحكم-اولادهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_210.mp3","categories":["الأنكحة المحرمة","قضايا المرأة"]},{"id":5947,"question":"ما رأيكم فيمن يرى أن حجاب المرأة المسلمة، وتسترها يكون سببًا في الشوق إلى رؤيتها، وأنها إذا كشفت وجهها، وذراعيها يكون سببًا في عدم الشوق إلى التطلع، أو النظر إليها؟","title":"الرد على القائل: إن الحجاب دافع للتطلع والافتتان بالمرأة","answer":"الجواب: هذا من دسائس أعداء الله، وهذا من مكائد الشيطان، يقول لهم أعداء الله، ويقول لهم الفجرة من النساء: لو تكشفت، لو أنها كشفت وجهها، وذراعيها؛ صار ما عدى لها قيمة، ولا أهمية، ولا ينظر الناس إليها، وإذا تحجبت؛ فتن الناس بها، هذا من مكائد الشيطان بعد قد يقولون لها: لو أنها مشت عارية؛ لكان أحسن، هذا النتيجة، نسأل الله العافية. الحاصل: أن هذا من مكائد الشيطان، ومن مكائد أعداء الله، والله جعل الحجاب مانعًا للشر؛ قال  في كتابه العظيم، وهو أصدق القائلين: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هكذا يقول ربنا  يقول: إن الحجاب أطهر لقلوبنا، وقلوب النساء جميعًا؛ فدل ذلك على أن عدم الحجاب أخبث للقلوب، ليس أطهر للقلوب، وأنه ينجسها.","link":"https://binbaz.org.sa/fatwas/1317/الرد-على-القاىل-ان-الحجاب-دافع-للتطلع-والافتتان-بالمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_286.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6019,"question":"هل صوت المرأة عورة، مع ذكر الدليل؟","title":"حكم صوت المرأة","answer":"الجواب:  صوت المرأة ليس بعورة، النبي ﷺ سمع كلام النساء، وسمعه الصحابة، وكن يسألن النبي ﷺ والصحابة يسمعون، وقد طلبن من النبي ﷺ مجلسًا لهن، فجمعهن في محل، وجاء إليهن، فصوتهن ليس بعورة، فلها أن تسأل الرجال عن أحكام الدين، وعما أشكل عليها، ولها أن تخاصم من يدعي عليها، أو تدعي عليه.  لكن عليها ألا يكون صوتها فيه خضوع، وترقيق، بل هو صوت معتاد لا .. ولا ترقيق، بل بين ذلك، والله -جل وعلا- نهى نساء النبي ﷺ أن يخضعن بالقول فيطمع الذي في قلبه مرض، فلا يجوز لها أن تخضع بالقول حال كلامها، وخصومتها، فيكون قولها، وكلامها بالطريقة المعتادة التي ليس فيها ما يوهم أنها تريد شيئًا، أو أنها تُشهر في نفسها، فليكن الصوت معتادًا الذي ليس فيه تكسر، وليس فيه ترخيم، وليس فيه ما يدعو الرجال من خضوعها بقولها، ولكن صوتًا معتادًا بسؤالها، وكلامها، وخصومتها، وردها الخصومة إلى غير ذلك، الصوت المعتاد الذي لا يطمع فيها أصحاب المرض.","link":"https://binbaz.org.sa/fatwas/1383/حكم-صوت-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_339.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6027,"question":"هل صوت المرأة عورة، مع ذكر الدليل؟","title":"حكم صوت المرأة","answer":"الجواب:  صوت المرأة ليس بعورة، النبي ﷺ سمع كلام النساء، وسمعه الصحابة، وكن يسألن النبي ﷺ والصحابة يسمعون، وقد طلبن من النبي ﷺ مجلسًا لهن، فجمعهن في محل، وجاء إليهن، فصوتهن ليس بعورة، فلها أن تسأل الرجال عن أحكام الدين، وعما أشكل عليها، ولها أن تخاصم من يدعي عليها، أو تدعي عليه.  لكن عليها ألا يكون صوتها فيه خضوع، وترقيق، بل هو صوت معتاد لا .. ولا ترقيق، بل بين ذلك، والله -جل وعلا- نهى نساء النبي ﷺ أن يخضعن بالقول فيطمع الذي في قلبه مرض، فلا يجوز لها أن تخضع بالقول حال كلامها، وخصومتها، فيكون قولها، وكلامها بالطريقة المعتادة التي ليس فيها ما يوهم أنها تريد شيئًا، أو أنها تُشهر في نفسها، فليكن الصوت معتادًا الذي ليس فيه تكسر، وليس فيه ترخيم، وليس فيه ما يدعو الرجال من خضوعها بقولها، ولكن صوتًا معتادًا بسؤالها، وكلامها، وخصومتها، وردها الخصومة إلى غير ذلك، الصوت المعتاد الذي لا يطمع فيها أصحاب المرض.","link":"https://binbaz.org.sa/fatwas/1383/حكم-صوت-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_339.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6100,"question":"من نوى التوقيت في الزواج هل يكون ذلك متعة؟","title":"من نوى التوقيت في الزواج هل يكون ذلك متعة؟","answer":"الجواب: التوقيت محل نظر، النية محل نظر إذا كان ليس بشرط، ولم يتفقا على شرط، فقد اختلف العلماء في ذلك، والأولى والأصح أنه لا يكون متعة، فلو تزوجها في الغربة، ونيته أنه إذا أراد الرجوع؛ طلقها، فالصحيح أن هذا لا حرج فيه؛ لأنه قد يعدل عن نيته، وقد يرغب بها، وينقلها ما دام لا مشارطة بينهما، وأنها في نيته أنه لا ينتقل بها إلى بلاده، فلا يضر هذا، ليس بشرط، وليس من المتعة على الصحيح. وذهب بعض أهل العلم إلى أنه يكون متعة إذا كان في نيته ذلك، ولكن الأرجح، والأقرب، والأظهر أنه ليس بمتعة، والناس يحتاجون إلى هذا، قد يكون في بلد غربة، أمريكا، أو إنجلترا، أو غير ذلك، ويخشى على نفسه الفتنة، فيسهل الله له زوجة مناسبة، فيتزوج، ونيته أنه متى أراد العودة طلقها؛ لأنها قد لا تناسب بلاده، أو لأسباب أخرى، فهذا لا يمنع من صحة النكاح، وهذه النية قد تنقلب، قد تنفسخ، قد يرغب فيها، وينقلها؛ فلا يضره هذه النية لعدم المشارطة.","link":"https://binbaz.org.sa/fatwas/1515/من-نوى-التوقيت-في-الزواج-هل-يكون-ذلك-متعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_445.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6102,"question":"هل يجب على المرأة الخروج إلى حاجتها إلى السوق بدون محرم؟ وهل يجوز للسائق الذي انتشر في هذه الآونة الأخيرة أن يصطحب النساء بدون محرم؟","title":"ضوابط وأحكام خروج المرأة","answer":"الجواب: خروج المرأة فيه تفصيل، إن كانت تخرج لحاجتها متسترة تعتني بنفسها؛ فلا بأس بخروجها، كان النساء يخرجن في عهد النبي ﷺ وعهد الصحابة لحاجاتهن، فإذا خرجت مع العناية، والستر، والحجاب؛ فلا حرج.  ولكن ينبغي مهما كان أن تقل الخروج، والحذر من عواقبه الوخيمة، وينبغي لأولياء المرأة مهما أمكن أن يقضوا حاجاتها، زوجها، وأخوها، وأبوها، ينبغي أن يقضوا حاجاتها، ولاسيما في هذا العصر الذي كثر فيه الشر، والفساد، وتعرض النساء للفساد، فينبغي في مثل هذا أن تقل الخروج، والحذر من شره، وينبغي للأولياء أن يقضوا حاجات المرأة؛ حتى يكفوهن مؤنة الخروج مهما أمكن، ولا يحتاج خروجها إلى محرم؛ لأنه ما هو بسفر، المحرم للسفر.","link":"https://binbaz.org.sa/fatwas/1517/ضوابط-واحكام-خروج-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_447.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6171,"question":"إذا كان عند بعض الإخوان فتاة فتقدمت منها، فقال: إنه يريد أن يتزوج منا كما زوجناه، فهل هذا شغار، أو جائز؟","title":"حقيقة الشغار وحكمه","answer":"الجواب: هذا شغار، تقدمت إلى زيد، وقال: نعم، أزوجك لكن بشرط أن تزوجني أختك، أو بنتك، لا، النبي نهى عن الشغار، وقال: الشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي فهذا هو الشغار، وهو نكاح البدن، فلا يجوز، فهذا يفضي إلى ظلم النساء، وإلى فتن، وإلى شرور كثيرة، ويفضي إلى إسقاط المهور .... بالفروج إلى غير ذلك.  وقد صحت عن النبي ﷺ أحاديث تنهى عن نكاح الشغار، ولو كان فيه مهر، وقد قال بعض العلماء: إذا كان فيه مهر كامل، مهر العادة؛ كفاه، وجاز، ولكنه قول مرجوح. والصواب: أنه لا يجوز، ولو كان فيه مئات الألوف، ما يجوز ما دام فيه هذا الشرط، وقد ثبت عن معاوية  أنه بلغه أن فلانًا وفلاًنا تزوجا نكاح الشغار، وقد سميا مهرًا، فكتب إلى أمير المدينة أن يبطل النكاح، وقال: هذا هو الشغار الذي نهى عنه النبي، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1626/حقيقة-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_517.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6229,"question":"لو قال أبدلك؟","title":"حكم نكاح الشغار البدل","answer":"الجواب: أما نكاح البدل فلا يجوز، إذا كان في نكاح بدل، إذا كان النكاح الذي فيه بدل ما يجوز؛ لأن هذا هو نكاح الشغار، الشغار لا يجوز كونه يقول: زوجني، وأزوجك إذا كان أبوك فعل ذلك، هذا لا يجوز، عليك أن تفارقها إن كان شغارًا، زوجني، وأزوجك، تعطيه بنتك، أو أختك، ويعطيك بنته، أو أخته هذا الشغار المنهي عنه، لا يجوز، ولو فيه مال على الصحيح، ولو بذل فيه مال.  فالواجب: أن تفارقها، وإذا كنت ترغب فيها، وترغب هي فيك؛ فلا بدّ من تجديد النكاح، نكاح جديد بدون شرط المرأة الأخرى، تتفق مع وليها على سبيل النكاح من دون شرط المرأة الأخرى، ويصح العقد حينئذ، وتسلم من شر الأول، والأولاد لاحقون بك لأجل الشبهة، الأولاد في العقد الأول لاحقون بك من أجل الشبهة، وهم أولادك، ولكن لا تبقى معها بعقد الشغار، بل لا بدّ من تجديد العقد، إذا كانت ترغب فيك، وأنت ترغب فيها، تجدد العقد بنكاح شرعي جديد، بولي، وشاهدين على الوجه الشرعي من دون شرط المرأة الأخرى.","link":"https://binbaz.org.sa/fatwas/1752/حكم-نكاح-الشغار-البدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_591.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6234,"question":"لو قال أبدلك؟","title":"حكم نكاح الشغار البدل","answer":"الجواب: أما نكاح البدل فلا يجوز، إذا كان في نكاح بدل، إذا كان النكاح الذي فيه بدل ما يجوز؛ لأن هذا هو نكاح الشغار، الشغار لا يجوز كونه يقول: زوجني، وأزوجك إذا كان أبوك فعل ذلك، هذا لا يجوز، عليك أن تفارقها إن كان شغارًا، زوجني، وأزوجك، تعطيه بنتك، أو أختك، ويعطيك بنته، أو أخته هذا الشغار المنهي عنه، لا يجوز، ولو فيه مال على الصحيح، ولو بذل فيه مال.  فالواجب: أن تفارقها، وإذا كنت ترغب فيها، وترغب هي فيك؛ فلا بدّ من تجديد النكاح، نكاح جديد بدون شرط المرأة الأخرى، تتفق مع وليها على سبيل النكاح من دون شرط المرأة الأخرى، ويصح العقد حينئذ، وتسلم من شر الأول، والأولاد لاحقون بك لأجل الشبهة، الأولاد في العقد الأول لاحقون بك من أجل الشبهة، وهم أولادك، ولكن لا تبقى معها بعقد الشغار، بل لا بدّ من تجديد العقد، إذا كانت ترغب فيك، وأنت ترغب فيها، تجدد العقد بنكاح شرعي جديد، بولي، وشاهدين على الوجه الشرعي من دون شرط المرأة الأخرى.","link":"https://binbaz.org.sa/fatwas/1752/حكم-نكاح-الشغار-البدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_591.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6236,"question":"إذا كان أخت زوجتي الأرملة عندي، ولستُ محرمًا لها، فهل يجوز لي أن أسافر بها مع أهلي في مكان بعيد مثل الطائف مثلًا؟","title":"حكم سفر الرجل بأخت زوجته مع وجود زوجته","answer":"الجواب: إذا كان ليس لها والي غيرك؛ فهي مع أهلك، كالخادمة التي ليس لها والي تكون مع أهلك، تسافر معهم، وليس هناك محرم للضرورة، أما إذا كان لها محرم؛ تكن معه.","link":"https://binbaz.org.sa/fatwas/1739/حكم-سفر-الرجل-باخت-زوجته-مع-وجود-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_582.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6247,"question":"إذا كان أخت زوجتي الأرملة عندي، ولستُ محرمًا لها، فهل يجوز لي أن أسافر بها مع أهلي في مكان بعيد مثل الطائف مثلًا؟","title":"حكم سفر الرجل بأخت زوجته مع وجود زوجته","answer":"الجواب: إذا كان ليس لها والي غيرك؛ فهي مع أهلك، كالخادمة التي ليس لها والي تكون مع أهلك، تسافر معهم، وليس هناك محرم للضرورة، أما إذا كان لها محرم؛ تكن معه.","link":"https://binbaz.org.sa/fatwas/1739/حكم-سفر-الرجل-باخت-زوجته-مع-وجود-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_582.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6405,"question":"ما حكم زواج الشغار مع دفع المهر لكل من المتشاغرين، ولكن مع شرط أنه يزوج كل منهما الآخر، وإذا امتنع طرف منهما؛ فسوف يمتنع الطرف الآخر؟","title":"ما حكم زواج الشغار مع دفع المهر؟","answer":"الجواب: نكاح الشغار هو الذي يسميه الناس البدل، ما يجوز باطل، النبي ﷺ نهى عنه في أحاديث، وقال: الشغار أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار المعروف عند الكثير من الناس بالبدل، نكاح البدل، وهو لا يجوز، نهى عن النبي ﷺ لما فيه من النزاع، والخصومات، واشتراط المرأة مهراً لامرأة أخرى. فالمهر عندهم لا قيمة له، وإنما المقصود المرأة بالمرأة، فالمهر لا يحل ذلك، هذا هو الصواب، وفي خلاف بين أهل العلم، بعض أهل العلم قال: مهرها المعتاد يكفي، ولكنه قول غير صحيح، ومخالف للأحاديث الصحيحة، فليس المقصود عدم المهر، المقصود شرط هذه مهراً لهذه، وهذا يفضي إلى إجبار النساء، وظلم النساء، ويفضي إلى النزاع الطويل، وكلما حصل بين هذا وزوجته شيء، حصل بين الآخر كذلك، كل واحدة مربوطة بالأخرى؛ فيحصل من الفساد، والشر ما لا يخفى على أحد، والنبي ﷺ نهى عن الشغار، ولم يقل إلا إذا كان معه مهر، أو إذا كان بمهر. وأما ما يروى في حديث ابن عمر (وليس بينهما مهر) فهذا من كلام أحد الرواة، وليس من كلام النبي ﷺ، بل هو من كلام نافع الذي هو الراوي عن ابن عمر، وإنما الذي قاله النبي ﷺ ما تقدم، وهو قوله: أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الذي جاء في الحديث عن أبي هريرة في صحيح مسلم، وثبت في حديث معاوية  أنه رفع إليه أن شخصين من قريش في المدينة تزوجا نكاح شغار، وكانا قد سميا مهرًا بينهما، فكتب معاوية  إلى أمير المدينة، وأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي ﷺ ولم يتلفت إلى ما ذكروا من المهر؛ لأنه غير مقصود، المقصود المرأة بالمرأة، هذا هو مقصود الشغار.","link":"https://binbaz.org.sa/fatwas/2113/ما-حكم-زواج-الشغار-مع-دفع-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_765.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6413,"question":"ما حكم زواج الشغار مع دفع المهر لكل من المتشاغرين، ولكن مع شرط أنه يزوج كل منهما الآخر، وإذا امتنع طرف منهما؛ فسوف يمتنع الطرف الآخر؟","title":"ما حكم زواج الشغار مع دفع المهر؟","answer":"الجواب: نكاح الشغار هو الذي يسميه الناس البدل، ما يجوز باطل، النبي ﷺ نهى عنه في أحاديث، وقال: الشغار أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار المعروف عند الكثير من الناس بالبدل، نكاح البدل، وهو لا يجوز، نهى عن النبي ﷺ لما فيه من النزاع، والخصومات، واشتراط المرأة مهراً لامرأة أخرى. فالمهر عندهم لا قيمة له، وإنما المقصود المرأة بالمرأة، فالمهر لا يحل ذلك، هذا هو الصواب، وفي خلاف بين أهل العلم، بعض أهل العلم قال: مهرها المعتاد يكفي، ولكنه قول غير صحيح، ومخالف للأحاديث الصحيحة، فليس المقصود عدم المهر، المقصود شرط هذه مهراً لهذه، وهذا يفضي إلى إجبار النساء، وظلم النساء، ويفضي إلى النزاع الطويل، وكلما حصل بين هذا وزوجته شيء، حصل بين الآخر كذلك، كل واحدة مربوطة بالأخرى؛ فيحصل من الفساد، والشر ما لا يخفى على أحد، والنبي ﷺ نهى عن الشغار، ولم يقل إلا إذا كان معه مهر، أو إذا كان بمهر. وأما ما يروى في حديث ابن عمر (وليس بينهما مهر) فهذا من كلام أحد الرواة، وليس من كلام النبي ﷺ، بل هو من كلام نافع الذي هو الراوي عن ابن عمر، وإنما الذي قاله النبي ﷺ ما تقدم، وهو قوله: أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الذي جاء في الحديث عن أبي هريرة في صحيح مسلم، وثبت في حديث معاوية  أنه رفع إليه أن شخصين من قريش في المدينة تزوجا نكاح شغار، وكانا قد سميا مهرًا بينهما، فكتب معاوية  إلى أمير المدينة، وأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي ﷺ ولم يتلفت إلى ما ذكروا من المهر؛ لأنه غير مقصود، المقصود المرأة بالمرأة، هذا هو مقصود الشغار.","link":"https://binbaz.org.sa/fatwas/2113/ما-حكم-زواج-الشغار-مع-دفع-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_765.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6502,"question":"ما حكم رجل زنى بامرأة، وتزوجها، وأنجبا أولادًا، وقد أتموا جميعًا هو وزوجته، وأولاده فريضة الحج، هل جريمة الزنا رفعت عنهما بقضاء فريضة الحج؟ وما هو وضع الأولاد، هل يعتبر الأولاد زنا، علمًا بأن الإنجاب تم بعد إتمام الزواج، أي لم يحدث حمل قبل الزواج؟","title":"حكم من زنى بامرأة ثم تزوج بها","answer":"الجواب: من تاب تاب الله عليه، ولو قبل الحج، إذا تابا تابا الله عليهما، ولو قبل الحج، ما هو بشرط الحج، التوبة تكفي، إذا تاب، وندم على ما فعل فالله -جل وعلا- يتوب على من تاب، فالتوبة تَجُبُّ ما قبلها، والإسلام يجب ما قبله، والحج زيادة خير، نسأل الله لهم الهداية. السؤال: هل يصح الزواج بالزانية؟ الجواب: يصح الزواج بها إذا تابت، لا بد من أن توعظ، وتذكر، فإذا تابت، وأظهرت التوبة؛ فلا بأس ...","link":"https://binbaz.org.sa/fatwas/2267/حكم-من-زنى-بامراة-ثم-تزوج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_890.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج","قضايا المرأة"]},{"id":6524,"question":"ما حكم رجل زنى بامرأة، وتزوجها، وأنجبا أولادًا، وقد أتموا جميعًا هو وزوجته، وأولاده فريضة الحج، هل جريمة الزنا رفعت عنهما بقضاء فريضة الحج؟ وما هو وضع الأولاد، هل يعتبر الأولاد زنا، علمًا بأن الإنجاب تم بعد إتمام الزواج، أي لم يحدث حمل قبل الزواج؟","title":"حكم من زنى بامرأة ثم تزوج بها","answer":"الجواب: من تاب تاب الله عليه، ولو قبل الحج، إذا تابا تابا الله عليهما، ولو قبل الحج، ما هو بشرط الحج، التوبة تكفي، إذا تاب، وندم على ما فعل فالله -جل وعلا- يتوب على من تاب، فالتوبة تَجُبُّ ما قبلها، والإسلام يجب ما قبله، والحج زيادة خير، نسأل الله لهم الهداية. السؤال: هل يصح الزواج بالزانية؟ الجواب: يصح الزواج بها إذا تابت، لا بد من أن توعظ، وتذكر، فإذا تابت، وأظهرت التوبة؛ فلا بأس ...","link":"https://binbaz.org.sa/fatwas/2267/حكم-من-زنى-بامراة-ثم-تزوج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_890.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج","قضايا المرأة"]},{"id":6527,"question":"هل يدخل سفر المرأة من بلدها وحدها إلى زوجها في بلد عمله، والسفر حوالي أربع ساعات بالطائرة، هل يدخل ذلك تحت النهي عن سفر المرأة بغير محرم؟","title":"حكم سفر المرأة في الطائرة بدون محرم","answer":"الجواب: نعم يدخل السفر بالطائرة، أو بالقطار، أو بالسيارة كله داخل، النبي ﷺ قال: لا تسافر المرأة إلا مع ذي محرم الرسول ﷺ ما هو يخبر عن نفسه، عن شرع الله، الرسول يخبر عن شرع الله، والله يعلم ما يكون في آخر الزمان من الطائرات، والقطارات، والسيارات، وغير ذلك، يعلم كل شيء  والشرع عام، الله شرع لنا شرائع إلى يوم القيامة، ما هي خاصة بوقت النبي ﷺ بل هي عامة في وقته، وبعد وقته إلى يومنا هذا، وإلى ما بعد ذلك إلى يوم القيامة، شرع مستمر، فليس شرعًا خاصًا بيوم دون يوم، أو سنة دون سنة، أو دولة دون دولة، هو شرع لجمع، فليس للمرأة أن تسافر إلا مع ذي محرم سواء كان سفرها بالطائرات، أو بالسيارات، أو بالقطارات، أو بغير ذلك. السؤال: معها ولد صار عمره سبع سنين محرم لها؟ الجواب: ليس محرمها، المحرم البالغ الرجل البالغ الذي خمسة عشر سنة، فأكثر. السؤال: كثير من النساء يستقبلهن أزواجهن وأهلهم في المطارات، يجوز هذا؟ الجواب: ما هو بدليل، هذا ما يجوز، هذا غلط، تساهل. السؤال: والمضيفات اللاتي يسافرن في الطائرة دائماً؟ الجواب: المضيفات، وغير المضيفات. السؤال: المضيفات اللاتي يشتغلن في الطائرة؟ الجواب: الحكم واحد، الحكم واحد. السؤال: .. صحبة نساء؟ الجواب: ولو بصحبة نساء، ما عليه دليل، حتى الحج ما يجوز، حتى الحج ليس لها حج إلا إذا كان معها محرم، وإلا فهي معذورة حتى يكون لها محرم في الحج، وفي غير الحج، هذا الصواب من أقوال العلماء.","link":"https://binbaz.org.sa/fatwas/2385/حكم-سفر-المراة-في-الطاىرة-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_918.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6574,"question":"لقد انتشر في قبائلنا الشغار، وغلو المهور، حتى إن الرجل يبلغ من العمر أكثر من ستين عامًا، ويأخذ بكريمته زوجة عن بنت أقل من 18 سنة بطريق الشغار، وهذا أدى إلى توقف الشباب منا من الزواج، وانحرافهم، وذهابهم إلى البلاد المختلفة؛ ليزاولوا هناك المنكرات؟","title":"حكم زواج الشغار وخطورة التكلف في الولائم وغلاء المهور","answer":"الجواب:\n\nهذا الذي قاله السائل أمر واقع في كثير من الجهات من غلاء المهور، ومن التكلف في الولائم، والحرص على الطمع من الأولياء، أو بعض الأولياء، وهذا لا شك أنه غلط كبير، والتنافس في المهور أمر منكر لقصد مصالحهم، الواجب على الأولياء أن يتقوا الله، وأن ينظروا في مصالح النساء، وأن يرضوا -ولو بالمهر القليل- إذا جاء الكفء، أما أن ينافس في طلب المهور حتى يأخذ المال، ولا يبالي؛ فهذا منكر لا يجوز له، ولو كان أباها، ليس له أن يحبسها لأجل المال الكثير، بل متى جاء الكفء -ولو بالقليل- زوجها، وسارع إلى ذلك، إذ المقصود صيانتها، وحفظ عرضها، وإعانتها على الخير، وإعانة المجتمع الإسلامي على الخير أيضًا. \n\nفعلى كل حال قد صدر فيه رسائل كثيرة، ونصائح كثيرة من هيئة كبار العلماء، وكثير من العلماء -ومني أيضًا- صدر في هذا كثير من الوعظ، والتذكير، وبيان ما يجب على المسلمين، وصدر رسائل في الشغار، والتحذير منه، ووزعت في جميع أنحاء البلاد مرات كثيرة، ولكن كما قيل:\n\n\n\t\n\t\t\n\t\t\tما لجرح بميت إيلام\n\t\t\n\t\n\n\nإذا لم يكن في القلب واعظ، ولم يكن في القلب إقبال على الخير، والهدى؛ لا ينتفع الإنسان بما يسمع، ولا يعلم، بل يصر على باطله، ولا يبالي، القرآن أكبر واعظ، القرآن العظيم، وأعظم ذكر، ومع ذلك أكثر الخلق قد خالفه، فلم يمتثل بما في القرآن من الأوامر، والنواهي متابعة للهوى، وإنما يمتنع بالنصائح من يرغب الحق، ويريد الحق، ويعيش بالحق، ويطلبه، متى وُعِظَ؛ قبل، ومتى ذُكِّر؛ تذكر؛ لأن قصده الحق، وهدفه اتباع الحق.\n\nفالواجب على السائل وجماعته أن يتقوا الله، وأن يتعاونوا على البر والتقوى، وأن يتناصحوا فيما بينهم، كبارهم، ويقومون على سفهائهم، وأعيانهم، يقومون على عامتهم حتى يتعاونوا على الخير، ويستعينوا أيضًا بعلمائهم، وقضاتهم، وأمرائهم في هذا الأمر العظيم؛ حتى يزوج الكفء، ولو بالمهر القليل، وحتى لا يتنافسوا في الولائم الكثيرة التي لا ضرورة إليها، بل يكون الشيء القليل الذي لا يضر الزوج، ولا أهل الزوجة، هذا هو الذي ينبغي للمسلمين فيما بينهم التعاون، فإذا علموا شخصًا يتساهل في هذا الأمر، ويحبس بناته، أو أخواته بغير حق؛ قاموا عليه، ونصحوه، ووجهوه إلى الخير، ولو أدى إلى أن يشتكوه إلى ولي الأمر عندهم؛ حتى يأخذ على يده، وحتى يزوج بناته، أو أخواته عن الأكفاء، ولو من طريق المحكمة إذا لم يحصل من الأولياء الخضوع للحق.\n\nنسأل الله للجميع الهداية، هذا إن شاء الله يعتنى به أكثر فيما يستقبل إن شاء الله.\n\nالسؤال: وهذا سؤال سبق أن أرسله إلينا أحد الإخوة قبل ذلك، وهو يستعين بالله، ثم بسماحتكم أن تنصفوه من هذا الرئيس الفلبيني الذي يفصل الذين، يصلون في المؤسسة، ويهددهم، ويضع الكلب مكان صلاتهم؟\n\nالجواب: هذا كذلك أيضًا سبق أن كتبنا إلى وزير الداخلية، ونسأل الله أن يوفقهم.","link":"https://binbaz.org.sa/fatwas/2421/حكم-زواج-الشغار-وخطورة-التكلف-في-الولاىم-وغلاء-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_948.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6599,"question":"يا شيخ، المرأة عندما صافحت حطت البشت، وخفت أنهم يقولون: موسوسًا .. ؟","title":"حكم مصافحة المرأة الكبيرة","answer":"السؤال: لا تصافح أبدًا .. لا تصافح النساء أبدًا، إلا محارمك، إخواتك، وعماتك.. السؤال: حتى ولو عجوز..؟ الجواب: ولو عجوز، ولو عجوز.","link":"https://binbaz.org.sa/fatwas/2444/حكم-مصافحة-المراة-الكبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_971.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6707,"question":"تقوم إذاعة القرآن الكريم بمكة المكرمة، وذلك بين السادسة إلى الثامنة مساء بأن تقوم نساء، وبنات بتلاوة القرآن الكريم في برنامج ناشئ في رحاب القرآن، هل هذا الفعل جائز، وخصوصًا أن الرسول -عليه الصلاة والسلام- أمر النساء بأن لا يرفعن أصواتهن بالتلبية، كيف بين نوفق هذا وذاك؟","title":"حكم صوت المرأة في برامج تلاوة القرآن","answer":"الجواب:\n\n... وإنما هو من كلام أهل العلم، أهل العلم رأوا أن الأفضل خفض أصواتهن بالتلبية، ونحو ذلك؛ لأنه قد يفتن بعض الناس ببعض الأصوات، وإلا أصواتهن ليست عورة، في حاجاتهن، فقد كن يخاطبن النبي ﷺ والنساء يسمعون، ويسألون عن حاجاتهم، وصوتها مطلقًا ليس بعورة، وإنما العورة خضوع صوتها -يعني الخضوع بصوتها- والترخيم لصوتها، لقوله -جل وعلا-: فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32].\n\nأما جنس الصوت للمرأة فليس بعورة، فلها أن تتكلم مع الرجال، تسأل عن حاجاتها، وتبيع، وتشتري .. لكن كونها تخضع بالقول بغنج، وشيء يطمع بها ضعفاء الإيمان، هذا هو المنكر، ولكن هذا برنامج ناشئ في القرآن ننظر فيه -إن شاء الله- ونعمل ما يلزم إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2578/حكم-صوت-المراة-في-برامج-تلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1074.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6754,"question":"ما حكم إذا خرجت المرأة للعمل في مجال لا اختلاط فيه، واستخدمت مربية مسلمة تقوم بالإشراف على أولادها أثناء غيابها للعمل، وكان زوجها موافقًا على هذا، والتزمت بالحجاب الإسلامي؟","title":"ضوابط خروج المرأة للعمل","answer":"الجواب:  لا حرج في ذلك -إن شاء الله- إذا كان هذا ما ذكرت من الشروط؛ فلا حرج في ذلك إذا كانت تلتزم بالحجاب، ويكون عملها في النساء، والأولاد عندهم من يتولاهم، ويحسن إليهم من النساء الطيبات المسلمات، وزوجها راض، ولا يكون خلوة من الزوج مع الموجودة في البيت، بل عندها من النساء من يمنع الخلوة، فهذا لا حرج فيه.  أما إذا كان يخلو بامرأة بعد زوجته؛ فهذا خطر عظيم، يجب أن تبقى المرأة في أولادها، ولا يحتاج إلى مربية تأتي للأولاد، وربما خلا بها الزوج، وربما وقعت الفتنة، فتبقى الزوجة مع أولادها، ولا حاجة إلى ذهابها، وعليه أن ينفق عليها، ويحسن إليها، ويقوم بحاجتها حتى تربي أولاده، وحتى تكون سكنًا له، ومرجعًا له يسكن بها، ويقضي متعته منها، وألا يقع في الفاحشة المنكرة في مربية أجنبية تقوم مقامها، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2657/ضوابط-خروج-المراة-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1153.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6759,"question":"هل يجوز سفر المرأة بالطائرة، وغيرها بدون محرم، أو الذهاب بها إلى المدرسة، أو السوق مع غير محرمها؟ وإذا كان لا يجوز فبماذا تنصحون من يفعل ذلك، وهو شيء قد تفشى بين الكثير من المسلمين تهاوناً.. أعداء الإسلام؟","title":"حكم خروج المرأة أو سفرها بدون محرم","answer":"الجواب: أما سفر المرأة من دون محرم فهذا لا يجوز، وقد نص الشارع على ذلك، ونص النبي ﷺ على منع ذلك، فقال في الحديث الصحيح: لا تسافر المرأة إلا مع ذي محرم ولما أخبره رجل أن زوجته خرجت حاجة، وقد اكتتب في بعض الغزوات، قال له: ارجع فحج مع امرأتك فرده من الغزو، وأمره أن يذهب مع زوجته في الحج.  فالمقصود: أن سفرها بدون محرم لا يجوز، لا في الطائرة، ولا في السيارات، ولا في القطارات، ولا غيرها، وأما خروجها العادي من بيتها إلى المدرسة، أو إلى السوق، أو إلى كذا، أو إلى كذا، فكذلك لا يجوز أن تكون وحدها مع أجنبي. لكن لو اشترط المحرم سيكون معها غير المحرم؛ لأجل زوال الخلوة، يعني إن كان معها محرم؛ فهذا طيب، وإن لم يتيسر؛ كفى أن يكون معها من يوثق به، ومن تزول معه الخلوة، فإذا خرجت مع السواق، وزوجة السواق، أو مع امرأة أخرى من البيت، أو رجل آخر تحصل به الطمأنينة؛ فهذا يزيل الخلوة؛لأن النبي ﷺ قال: فثالثهما الشيطان فإذا كان معهما ثالث؛ زالت الخلوة؛ ولأن الحاجة ماسة لهذا الأمر، وليس من الميسور أن يكون المحرم معها في كل خرجة من الخرجات، فاكتفي بما يحصل به الطمأنينة، وزوال الخلوة.","link":"https://binbaz.org.sa/fatwas/2651/حكم-خروج-المراة-او-سفرها-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1147.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6765,"question":"ما حكم إذا خرجت المرأة للعمل في مجال لا اختلاط فيه، واستخدمت مربية مسلمة تقوم بالإشراف على أولادها أثناء غيابها للعمل، وكان زوجها موافقًا على هذا، والتزمت بالحجاب الإسلامي؟","title":"ضوابط خروج المرأة للعمل","answer":"الجواب:  لا حرج في ذلك -إن شاء الله- إذا كان هذا ما ذكرت من الشروط؛ فلا حرج في ذلك إذا كانت تلتزم بالحجاب، ويكون عملها في النساء، والأولاد عندهم من يتولاهم، ويحسن إليهم من النساء الطيبات المسلمات، وزوجها راض، ولا يكون خلوة من الزوج مع الموجودة في البيت، بل عندها من النساء من يمنع الخلوة، فهذا لا حرج فيه.  أما إذا كان يخلو بامرأة بعد زوجته؛ فهذا خطر عظيم، يجب أن تبقى المرأة في أولادها، ولا يحتاج إلى مربية تأتي للأولاد، وربما خلا بها الزوج، وربما وقعت الفتنة، فتبقى الزوجة مع أولادها، ولا حاجة إلى ذهابها، وعليه أن ينفق عليها، ويحسن إليها، ويقوم بحاجتها حتى تربي أولاده، وحتى تكون سكنًا له، ومرجعًا له يسكن بها، ويقضي متعته منها، وألا يقع في الفاحشة المنكرة في مربية أجنبية تقوم مقامها، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2657/ضوابط-خروج-المراة-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1153.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6767,"question":"كثير من البرامج المذاعة في وسائل الإعلام يقوم بها نساء حتى في إلقاء اللقاءات الإسلامية، فهل يجوز لأي مسلم الاستماع لأصواتهن أفيدونا جزاكم الله خيرًا؟","title":"حكم سماع صوت المرأة في وسائل الإعلام","answer":"الجواب: صوتها ليس بعورة، وإنما العورة خضوعها، وتغنجها، وتكسرها بالصوت، كما قال الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32].  ولا ينبغي أولًا استعمالهن في الإذاعة، والتلفاز، ونحو ذلك، ولكن متى وجد ذلك، فإن وجد من نفسه ميلًا إلى صوتها، وتلذذًا، وشهوة، فليحذر، وليبتعد، ولا يسمع، فإن كان هناك فائدة فيما تلقيه، ولا يحس من نفسه بشيء من التلذذ، والشهوة للصوت، وإنما أراد أن يسمع الكلام المفيد الذي قد تلقيه، أو الإنذار، أو البلاغ، أو ما أشبه ذلك، فأرجو أن لا حرج عليه في هذا  السماع الذي لا يضر دينه.","link":"https://binbaz.org.sa/fatwas/2652/حكم-سماع-صوت-المراة-في-وساىل-الاعلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1148.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6783,"question":"في مجلة آخر ساعة المصرية نشرت صور كثير من المحجبات، وهذه ظاهرة هناك الآن، ولكن كتب تحتها ظاهرة الحجاب لماذا؟ وعلق عليها الدكتور أحمد شلبي: الحجاب لا وجود له في الإسلام، وبالمناسبة لقد كثر الكلام، والجدال حول الحجاب، وأن المفروض أن تكشف المرأة عن وجهها، وكفيها لحديث الرسول ﷺ لأسماء، وعندما أقول لهم حديث ابن أم مكتوم أوعمياوان أنتما يقول: إنه حديث الرسول لأسماء حديث صحيح، نرجو الإفادة الشافية حيث إن الإخوة السائلين المختلفين موجودون هنا وشكرًا؟","title":"الرد على منكري الحجاب","answer":"الجواب: المنكر للحجاب إما جاهل، وإما مكابر، يقول الله -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هكذا في الآية الكريمة في سورة الأحزاب.  ويقول سبحانه في سورة النور: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية. بين  أن النساء عليهن غض الأبصار، وعليهن حفظ الفروج، وعليهن ألا يبدين زينتهن إلا ما ظهر منها، وهي الملابس الظاهرة، ثم بين من يبدى له الزينة، فقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ إلى آخره، فدل ذلك على وجوب الحجاب، وأن الزينة يجب أن تستر الوجه، والشعور، وبدن المرأة كله محاسن، وكله زينة يجب أن تستر.  وأما حديث أسماء الذي ذكره السائل، وتعلق به بعض الناس: هو أن أسماء بنت أبي بكر دخلت على أختها عائشة، والنبي حاضر -عليه الصلاة والسلام- وعليها ثياب رقاق، فقال لها النبي ﷺ: يا أسماء إن المرأة إذا بلغت المحيض لا يصلح أن يرى منها إلا هذا، وهذا، وأشار إلى وجهه، وكفيه وهو حديث لا يصح عن النبي ﷺ والتعلق به تعلق بالباطل، فهو حديث رواه أبو داود بإسناد منقطع، عن عائشة، وبإسناد ضعيف، منقطع وضعيف، ضعيف من جهة انقطاعه، وضعيف من جهة بعض رواته، فهو حديث لا يصح عن النبي ﷺ. ولو صح لكان هذا قبل الحجاب، لأن الحجاب صريح، أنزل الله فيه الآيات، وأمر المرأة بالحجاب، فهذا لو صح؛ لكان قبل الحجاب، ولكنه غير صحيح، فإنه من رواية سعيد بن بشير، عن قتادة عن خالد بن دريك، عن عائشة، وسعيد بن بشير لا يحتج به، ضعيف في الرواية، ولا يحتج بروايته، وقتادة عن خالد معنعن، وهو مدلس؛ فلا يحتج بروايته إذا عنعن، وخالد بن دريك لا بأس به، لكنه لم يسمع من عائشة، لم يلق عائشة، ولم يسمع منها، فهو منقطع بين خالد، وبين عائشة، وضعيف من جهة رواية سعيد بن بشير، وضعيف من جهة عنعنة قتادة.  فالمقصود: أنه ضعيف من جهات ثلاث، فيه علل ثلاث: علة ضعف سعيد، وعلة تدليس قتادة، وعلة انقطاعه بين خالد، وبين عائشة، فهو ضعيف من وجوه ثلاثة، لا يحتج به، ولا يتعلق عليه، ولو فرضنا أنه صحيح، وجاء بإسناد صحيح؛ لكان هذا قبل أن يأتي الحجاب، وقبل أن يشرع الحجاب كان النساء يجلسون مع الرجال وهن كاشفات الوجوه، يتحدثن معهم، ثم أنزل الله الحجاب، وأمروا بالستر بعد ذلك كما جاءت السنة بذلك، قالت عائشة -رضي الله عنها- لما سمعت صوت صفوان بن معطل لما مر عليها حين خلفها الجيش -يحسبون أنها في هودجها- قالت: فسمعته يسترجع: إنا لله وإنا إليه راجعون لما رآها، قالت: فلما سمعته؛ خمرت وجهي، وكان قد رآني قبل الحجاب، فعرفني. المقصود: أن هذا يبين لنا أنهم كانوا قبل الحجاب يكشفون وجوههم، فلما جاء الحجاب؛ ستروا وجوههم، وهذا الحديث رواه البخاري ومسلم في الصحيحين عن عائشة -رضي الله عنها- أنها قالت: إنه رآني قبل الحجاب، فلما سمعت صوته؛ خمرت وجهي.","link":"https://binbaz.org.sa/fatwas/2649/الرد-على-منكري-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1145.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6787,"question":"الدين الإسلامي أوصى بصلة الرحم، فكيف توفق المرأة بين قوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]، وبين زيارة أرحامها، وأقاربها، لا سيما إن كان لها الكثير من الإخوان، والأخوات، والأقارب، وهذا يقتضي خروجها ثلاثًا إلى أربع مرات في الأسبوع؟","title":"كيف توازن المرأة بين قرارها في بيتها وبين صلة أرحامها؟","answer":"الجواب: ليس من شرط الصلة الزيارة، إذا وصلتهم بالكلام، أو بالهاتف، أو بالمكاتبة، أو بإرسال الحاجة من النفقة، والمساعدة؛ حصل المقصود، ليس من اللازم أن تخرج كل ساعة لأصحابها، وأقاربها، فالصلة تكون بمال يرسل إليهم، وتكون بالمكاتبة، وتكون من طريق التلفون بالهاتف، كل هذا، وتكون من طريق الوصية، توصي فلانة، وفلانة يبلغون قريباتها السلام، وأقاربها السلام.  والزوج بالخيار إن شاء أذن لها، وإن شاء منعها، إن شاء أذن لها بالذهاب إليهن، والزيارة، وإن شاء منعها على حسب ما يراه من المصلحة، وإذا كانت الزيارة في أوقات متباعدة مع الحجاب، ومع الحشمة، ومع الاستقامة؛ فله أن يسمح لها في الأوقات المناسبة، تزور أختها، خالتها، عمتها، أمها، إلى غير ذلك. أما إذا كن يفسدن، ولا خير فيهن؛ فعدم الإذن لها أولى، إذا كن.. عمات، أو أخوات خبيثات منحرفات؛ فلا حاجة إلى ذلك، إذا أرادت أن تصلهن بالمال لفقرهن، تصلهن من دون حاجة إلى الذهاب إليهن، لفسادهن، وانحرافهن. فالمقصود: أنه ينظر في الأصلح، فإذا رأى أن الزيارة لأقاربها، أو لصواحباتها فيها المصالح الدينية، وهي ملتزمة، ومستقيمة في أوقات يحددها، فهذا من باب الإعانة على الخير، وإذا كانت الزيارة لأقاربها قد تفسدها، وقد تضر دينها، وأخلاقها؛ منعها، ينظر في الأصلح.","link":"https://binbaz.org.sa/fatwas/2660/كيف-توازن-المراة-بين-قرارها-في-بيتها-وبين-صلة-ارحامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1156.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6907,"question":".. وبعيدة مع زوجتي وبناتي؟","title":"حكم سفر المرأة مع القريب غير المحرم","answer":"الجواب: السفر بغير المحارم لا يجوز، سواء كانت زوجة أخيك، أو زوجة عمك، أو خالك، أو غيرها، أما إذا كانت محرمًا لك، كزوجة ابنك، أو زوجة أبيك، أو أختك، أو بنتك؛ لا بأس بذلك.  وأما السفر بغير محارمك؛ فلا يجوز إلا إذا كان غير سفر، كالخروج العادي في ضواحي البلد، ولست وحدك، بل معك غيرك، لا تخلو بها، مع عائلتك، فلا بأس تذهب بها مع عائلتك إلى بيت آخر إلى ضواحي البلد، إلى منتزه قريب لا يسمى سفرًا، هذا لا بأس بشرط ألا تكون خاليًا بها، أما مع الخلوة فلا يجوز.","link":"https://binbaz.org.sa/fatwas/2828/حكم-سفر-المراة-مع-القريب-غير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1276.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6917,"question":"هل بنات الأخوال، وبنات العم، والعمات من ذوي الأرحام؟ وهل تجب صلاتهن؟ وهل يأثم من ترك ذلك؟","title":"بنات العم والخال من الأرحام","answer":"الجواب: نعم بنات العم، وبنات الخال، وأولاد العم، وأولاد الخال كلهم من الرحم، لكن من الرحم غير القريب، أقرب منهم الأعمام، والأخوال، والإخوة، والأخوات، هم من الأقارب البعيدين بعض البعد، فإذا استطاع أن يصلهما بالمواساة بالمال؛ فليفعل، وإلا فليصلهما بالكلام الطيب، والفعل الطيب، والزيارة الحسنة التي ليس فيها محذور شرعًا.\n\nالسؤال: إن مستشفى الملك خالد الجامعي لا يوجد به مسجد للصلاة، وجميع المراجعين لهذا المستشفى، والموظفين في وقت الصلاة مستمرين في العمل، ولا يعلم عن صدور الوقت، نرجو الأهمية بهذا؟ الجواب: ننظر في هذا بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/2847/بنات-العم-والخال-من-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1295.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6990,"question":"ما حكم الزواج بنية الطلاق لمدة سبعة أيام، أو عشرة أيام إذا خشي المسافر على نفسه من الزنا؟ وهل فتوى اللجنة الدائمة للإفتاء في جواز الزواج بنية الطلاق تشمل المدة القصيرة والطويلة، أم لا؟ لأن بعض الشباب الذين سافروا في الإجازة السابقة صوروا الفتوى بحجة أنها تنطبق عليهم، ولو كانت المدة قصيرة، فما الحكم في ذلك؟","title":"الفرق بين نكاح المتعة والزواج بنية الطلاق","answer":"الجواب:\n\nهذا ليس من المتعة، المتعة أن يتزوج الإنسان وهو على شرط بينه وبين أهل الزوجة، أو الزوجة على أيام معلومة، أو سنة معلومة، أو شهر معلوم، كما كان في الجاهلية، وفي أول الإسلام، ثم نسخ ذلك في أثناء الإسلام، في حجة الوداع، وقيل: في يوم الفتح، على خلاف بين أهل العلم.\n\nأما كونه ينوي الطلاق هذا ليس بمتعة، يتزوج، وفي نيته أنه متى سافر من أمريكا، أو من أوروبا؛ طلق، قد يهون، ولا يطلق، إنما نوى شيئًا مباحًا له، نوى طلاقًا مباحًا له، وليس هذا من المتعة في شيء، المتعة: المشارطة على مدة معلومة متى مضت؛ انتهى النكاح، وانقضى النكاح، كما يفعل الآن في بعض طوائف الرافضة.\n\nالمقصود: أن المتعة شيء معلوم، بزمن معلوم مقدر، هذا هو الذي نسخه الله إلى يوم القيامة، وهو محرم، أما كون الإنسان يتزوج، ونيته أنه يطلق بعد سنة، أو شهر، أو أسبوع، أو سنتين، أو كذا؛ فقد يرجع عن هذه النية، وقد لا ينفذ هذه النية، شيء بينه وبين ربه -جل وعلا- ليس مشارطة بينه وبين الزوجة، ولا بينه وبين الولي، ولا بينه وبين الأسرة، إنما هو شيء في نفسه، هذا لا يضره عند جمهور أهل العلم، حكاه صاحب المغني عن أكثر العلماء، وقال بعض أهل العلم: لا ينبغي له ذلك، ولا ينبغي أن تكون هذه النية، فإذا ترك هذه النية، وتزوج بدون هذه النية؛ يكون أفضل، وأكمل، وأحوط.\n\nالسؤال: أليس في ذلك غش لأهل الزوجة إذا كانوا لا يعلمون؟\n\nالجواب: ما في غش، هو مباح له الطلاق، ولو ما نوى، ما هو ملزم بأن يبقى معها ولو ما نوى الطلاق، لو أنت تزوجت امرأة، ثم رأيت من المصلحة أن تطلقها بعد ليلة من الزواج؛ لا حرج عليك، رأيتها ما تناسبك، فطلقتها بعد ليلة، أو ليلتين؛ ما في حرج. \n\nالسؤال: من ناحية الإدارة المكتبة، مختلطة، وكل يوم تزيد عن اليوم الذي قبله؟\n\nالجواب: أي إدارة؟ \n\nالطالب: ... وهذا نشر للرذيلة تأتي الفتاة في أي وقت؟\n\nالجواب: ...؟\n\nالطالب: كتبناها لك قبل أسبوعين.\n\nالجواب: يمكن لو كتبت في ... جزاك الله خيرًا على النسيان.\n\nالطالب: وبعد نخبركم: أن رئيس الجهاز العسكري بالحرس الوطني يمنع بعض من يرغب الالتحاق بمدرسة تحفيظ القرآن بالحرس، ولا يرضى بأن يدخل بها إلا عريفًا، وجنديًا فقط، وما فوق العريف، والجندي يمنعه قطعيًا، ولو كان يرغب، ونرجو من فضيلتكم النظر في ذلك؟\n\nالجواب: ينظر في الأمر إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2919/الفرق-بين-نكاح-المتعة-والزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1367.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7129,"question":"صوت المرأة؟","title":"صوت المرأة ليس بعورة لكن لا تخضع بالقول","answer":"الجواب: أما صوت المرأة فليس بعورة، قد كان النساء يخاطبن النبي ﷺ ويخاطبن الصحابة، ويسلم الرجال على النساء، والنساء على الرجال، ليس بعورة، إنما العورة خضوعها بالقول، وتكسرها في القول، وتغنجها في القول قال -جل وعلا- : يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب: 32] المرض، يعني مرض الشهوة. فالحاصل: أن الخضوع بالقول، واللين في القول خلاف العادة، هذا هو الذي ينهى عنه، أما القول المعتاد، والكلام المعتاد فلا بأس به، وليس بعورة، ولهذا قال: وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب: 32] يعني القول المعتاد الذي ليس فيه خضوع، ولا تغنج، ولا غير ذلك مما يدعو إلى الفتنة.","link":"https://binbaz.org.sa/fatwas/3170/صوت-المراة-ليس-بعورة-لكن-لا-تخضع-بالقول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1528.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7134,"question":"نظر المرأة إلى الرجل؟","title":"حكم نظر المرأة إلى الرجل","answer":"الجواب:\n\nمثل ما قال الله -جل وعلا-: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31] مثل الرجل، عليها أن تغض، وعليه أن يغض، والنظر العارض لا يضر، النظر العارض الذي ليس بمقصود لا يضر، مثل ما تنظر إلى الرجال في طريقها، أو في المصلى، في المسجد، إذا صلت مع الناس هذا نظر عارض لا يضر، أما النظر الذي يكون معه الشهوة، أو معه الفتنة؛ فلا يجوز.","link":"https://binbaz.org.sa/fatwas/3171/حكم-نظر-المراة-الى-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1529.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7147,"question":"سفر المرأة بدون محرم حرام، ولكن ما هو مفهوم قول الرسول ﷺ في الحديث: سفر يوم وليلة هل سفرها من أي دولة إلى هنا بطريق الطائرة وهي لا تمكث أكثر من ساعة ونصف يعتبر سفرًا أقل من يوم وليلة؟","title":"ضابط السفر للمرأة","answer":"الجواب:\n\nكل ما سمي سفر؛ فهو ممنوع، لقوله ﷺ: لا تسافر المرأة إلا مع ذي محرم هكذا جاء في الحديث الصحيح في الصحيحين من حديث ابن عباس -رضي الله عنهما-. \n\nأما ما ورد في بعض الروايات ثلاثة أيام، وبعضها يوم وليلة، وبعضها يوم، وبعضها ليلة، وبعضها بريد. فأجاب العلماء عن ذلك بأنها على حسب الأسئلة، هذا يسأل عن يوم، وهذا يسأل عن بريد، وهذا يسأل عن يوم وليلة، وهذا يسأل عن يومين، على حسب الأسئلة، ليس للتقييد، ولكنها تقع من باب سؤال السائل، فيجيبه النبي ﷺ على ما سأل، وليس المراد التقيد، ولهذا جاءت متنوعة في بعضها ثلاثة أيام، وفي بعضها يومين، وفي بعضها يوم وليلة، وفي بعضها ليلة، وفي بعضها يوم، وفي بعضها بريد، والضابط في هذا هو السفر، كل ما يسمى سفر في الطائرة أو في القطار أو في السيارة أو في الإبل، كل ما يسمى سفر؛ يمنع سفرها إلا بمحرم.\n\nالسؤال: هو أحد الموظفين هنا، وأرسل لزوجته من دولة ثانية تأتي له ما يقدر ينزل يأتي بها ...؟\n\nالجواب: كل هذا غلط، كله غلط، لا بد ينزل لها، ويجيبها أخوها، أو عمها، أو نحو ذلك، أما أنها تأتي بالطائرة، قد يحصل لها من يفسدها في الطائرة، يغامزها، ويتكلم معها، ويواعدها للفساد، وقد لا يوافقها أحد عند وصولها، قد يعرض عارض، فلا يخرج لها محرم عند وصولها إلى المطار، قد يعرض عارض في الطائرة، فترجع إلى بلد أخرى.","link":"https://binbaz.org.sa/fatwas/3182/ضابط-السفر-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1540.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7162,"question":"لماذا ينظر النبي ﷺ إلى الخثعمية، ويدير وجه الفضل؟ هل ذلك مباح له وحده ﷺ أم ماذا؟","title":"شبهة توجيه نظر رسول الله إلى الخثعمية","answer":"الجواب:\n\nمثلما تقدم، مثلما سمعتم، هذا من باب ترك أسباب الفتنة؛ لأن النظر قد يكون من أسباب الفتنة، ولو إلى قدها، وحسن صوتها، لا يلزم من هذا السفور. \n\nوالخثعمية ما فيه أنها كانت سافرة، إنما كان ينظر إليها، وتنظر إليه، قد يكون من أجل سماع صوتها، وحسن صوتها، أو لأسباب أخرى، فلهذا خاف عليه النبي ﷺ والنبي لا يخشى عليه من هذا -عليه الصلاة والسلام- لأن الله قد عصمه من هذه الفتنة.","link":"https://binbaz.org.sa/fatwas/3186/شبهة-توجيه-نظر-رسول-الله-الى-الخثعمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1544.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7170,"question":"هل يجوز إذا مر رجل بنساء أن يسلم عليهن، أم لا؟","title":"حكم إلقاء السلام على النساء","answer":"الجواب:\n\nنعم، النبي ﷺ سلم على النساء، وسلم عليهن، وأومأ بيده كما سمعتم في الندوة، فإذا سلم عليهن قال: السلام عليكم؛ فعليهن أن يقلن: وعليكم السلام، وإن كن بعيدات أشار بيده وسلم ليفهموا، وهكذا غيرهم من الرجال إذا بعدوا، أو في محل يخشى ألا يسمعوه؛ يسلم ويشير.","link":"https://binbaz.org.sa/fatwas/3208/حكم-القاء-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1557.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7173,"question":"هل يجوز معانقة ومقابلة الخالة، أو العمة، أو ما شابههما؟","title":"حكم معانقة المحارم","answer":"الجواب:\n\nنعم محارم، كان النبي ﷺ إذا دخلت عليه ابنته فاطمة؛ قام إليها، وأخذ بيدها وقبلها، فإذا دخلت عليه خالته، أو أمه أو عمته أو أخته، إذا قام إليها وقابلها وصافحها أو عانقها؛ لا بأس بذلك.\n\nالسؤال: طيب زوجة عمه؟\n\nالجواب: لا، زوجة عمه ما هي بمحرم.\n\nالطالب: ما يقابلها؟\n\nالجواب: زوجة عمه، وزوجة أخيه، وزوجة خاله ليست بمحرم له، إنما يسلم عليها بالكلام فقط بدون مصافحة، وبدون معانقة، بالكلام، يعني كيف حالك يا فلانة؟ كيف الأولاد؟ كيف عمي؟ كيف خالي؟ أما أنه يقبلها ويصافحها لا. \n\nالسؤال: مقابلتها ما يجوز؟\n\nالجواب: المقابلة تختلف، المقابلة بالكلام لا بأس مع كونها محتجبة مستترة، أما مقابلتها بالمصافحة، أو بالمعانقة، والتقبيل، لا.","link":"https://binbaz.org.sa/fatwas/3212/حكم-معانقة-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1560.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7239,"question":"الجارية المملوكة يجوز لسيدها أن يجامعها، فهل يجوز للعبد المملوك أن يجامع سيدته بإذنها لقوله تعالى: إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:24]؟","title":"حكم جماع العبد المملوك لسيدته","answer":"الجواب:\n\nلا، هذا منكر، هذا إنما هو في الرجال، قال تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ [المؤمنون:5، 6] المراد به الإماء للسيد، ولهذا ذكر ... فالسيد له أن يتصل بزوجته الشرعية، وبأمته الشرعية التي يملكها ملكًا شرعيًا، إما بالسبي، وإلا بالشراء من قوم قد توثق ملكهم لها، فإذا اشتراها، واستبرأها بحيضة؛ جاز له أن يباشرها إذا كان ملكًا شرعيًا، كما يباشر زوجته.\n\nأما العبد لا، ليس له أن يباشر سيدته، لا يقبل، ولا يجامع، هذا منكر بإجماع المسلمين، ليس له أن يباشر سيدته، لا بجماع ولا بغيره، وإنما يخدمها بأوامرها، ولا يلزمها الحجاب عنه، لكن ليس محرمًا لها.\n\nوإنما أباح الله لها عدم الحجاب؛ لأنها تتضرر بذلك، بأسباب كثرة دخوله عليها، وخدمته لها، ولكن ليست حلًا له، فلا يقبل، ولا يجامع، فهي حرام عليه.","link":"https://binbaz.org.sa/fatwas/3298/حكم-جماع-العبد-المملوك-لسيدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1623.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7307,"question":"ما رأي سماحتكم في استمرار الزواج بين الزوج والزوجة الذين لا يصلون، هل يبطل عقد زواجهما، وإذا عادا وتابا إلى الله، وقاما للصلاة فهل يجدد العقد، أم لا؟","title":"حكم عقد الزوجية للزوجين تاركي الصلاة","answer":"الجواب: إذا كانا جميعًا لا يصليان؛ صار العقد صحيحًا مثل عقود الكفرة، أما إذا كان الزوج لا يصلي، وهي تصلي، أو هو يصلي، وهي لا تصلي؛ فلا يصح العقد، يجدد؛ لأن من تركها كفر على الصحيح، فيجدد العقد بعد توبة الذي لا يصلي. السؤال: يعني إذا عادا إلى الصلاة يجدد العقد؟ الجواب: يجدد العقد، وقبل ذلك يمنع منها وتمنع منه.","link":"https://binbaz.org.sa/fatwas/3370/حكم-عقد-الزوجية-للزوجين-تاركي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1688.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7308,"question":"إذا كان عند الرجل أربع نساء، ثم طلق إحداهن، وتزوج بأخرى قبل أن تتم عدة المطلقة؟","title":"حكم الزواج بالخامسة قبل تمام عدة الطلاق للرابعة","answer":"الجواب: ليس له ذلك، لا يجوز له التزوج حتى تخرج من العدة إن كانت رجعية، لا يجوز له بإجماع المسلمين؛ لأنها زوجة، الرجعية إن طلقها واحدة، أو ثنتين؛ فهي رجعية، ليس له الزواج بالخامسة حتى تخرج هذه من العدة.  وإن كان الطلاق بائنًا؛ ففيه خلاف بين أهل العلم، والذي ينبغي ألا يتزوج، هذا هو الصواب؛ عليه أن لا يتزوج حتى تخرج من العدة؛ حسمًا لمادة التساهل؛ وسدًّا لذريعة التزوج في عدة أخرى.","link":"https://binbaz.org.sa/fatwas/3388/حكم-الزواج-بالخامسة-قبل-تمام-عدة-الطلاق-للرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1704.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7314,"question":"إذا كان عند الرجل أربع نساء، ثم طلق إحداهن، وتزوج بأخرى قبل أن تتم عدة المطلقة؟","title":"حكم الزواج بالخامسة قبل تمام عدة الطلاق للرابعة","answer":"الجواب: ليس له ذلك، لا يجوز له التزوج حتى تخرج من العدة إن كانت رجعية، لا يجوز له بإجماع المسلمين؛ لأنها زوجة، الرجعية إن طلقها واحدة، أو ثنتين؛ فهي رجعية، ليس له الزواج بالخامسة حتى تخرج هذه من العدة.  وإن كان الطلاق بائنًا؛ ففيه خلاف بين أهل العلم، والذي ينبغي ألا يتزوج، هذا هو الصواب؛ عليه أن لا يتزوج حتى تخرج من العدة؛ حسمًا لمادة التساهل؛ وسدًّا لذريعة التزوج في عدة أخرى.","link":"https://binbaz.org.sa/fatwas/3388/حكم-الزواج-بالخامسة-قبل-تمام-عدة-الطلاق-للرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1704.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7319,"question":"ما حكم زواج المسلم من أهل السنة والجماعة من الشيعة؟","title":"حكم زواج السنة من الشيعة","answer":"الجواب: لا ينبغي أن يتزوج من الشيعة؛ لأن الشيعة فيهم من يعبد عليًا، ويستغيث بأهل البيت، ويشرك بهم، ويدعوهم من غير الله، فهذا شرك أكبر، ولاسيما الشيعة الموجودة الآن، والتي في غالب الدنيا يغلب عليهم الغلو في أهل البيت. فالذي ينبغي لأهل السنة أن لا يتزوج منها إلا إذا عرف أنها ليست على دين قومها، وأنها دخلت في السنة، واستقامت على السنة، والبعد عما عليه أهلها من الغلو في أهل البيت، فإنهم يغلون في أهل البيت، ويدعون عليًّا من دون الله، والحسين وفاطمة، ويستغيثون بهم، حتى المرأة عند الطلاق تقول: يا علي! إلا من شاء الله منهم، إلا من هداه الله منهم، فينبغي التثبت في هذ الأمور، نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/3391/حكم-زواج-السنة-من-الشيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1706.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7562,"question":"الرسالة هذه من أحد السائلين وهو خلف سرور من جدة أيضاً، ويسأل عن زواج الشغار، يقول: جئت لأحد الإخوان وطلبت منه أن يزوجني بنته وقال لي: زوجني بنتك ولا عندي مانع، وبقيت في حيرة من الأمر، أرجو من فضيلتكم توضيح الطريق الصحيح، وهل في هذا الشيء حلال أم حرام؟ وفقكم الله لعمل الخير، وجزاكم الله خيري الدنيا والآخرة، شاكرين لكم وللعاملين على هذا البرنامج؟","title":"حكم نكاح الشغار","answer":"الجواب: نكاح الشغار، ويسميه بعض الناس نكاح البدل لا يجوز، وهو أن يقول: زوجني بنتك، أو زوج ولدي أو أخي أو ابن أخي وأزوجك بنتي، أو أزوج ولدك، أو ابن أخيه، هذا لا يجوز، هذا هو الشغار الذي نهى عنه النبي ﷺ وزجر عنه في عدة أحاديث، الرسول ﷺ زجر عن نكاح الشغار، وهو ما يسمى: نكاح البدل، فلا يجوز أبداً لأي مسلم أن يتزوج نكاح الشغار ولو بالمهر المعتاد، لا يجوز هذا؛ لأن الشرط نكاح في نكاح، وعقد في عقد، فهو من جنس بيعتين في بيعة، ولأنه يفضي إلى فساد كبير إلى نزاع وخصومات، وإلى إجبار النساء وظلم النساء من جهة أوليائهن لمصالحهم أو مصالح أولادهم، أو أبناء إخوتهم أو نحو ذلك، ثم يفضي إلى النزاع بعد ذلك، كلما تنازع زوج مع زوجته خرجت الأخرى.\nفالمقصود أنه منكر، ولهذا الرسول نهى عنه عليه الصلاة والسلام، ويكفي هذا، كون الرسول ﷺ نهى عنه يكفي هذا، ولكن مع هذا كله يقع أهله في مشاكل كثيرة، وهذا من شؤم الذنوب وشؤم المعصية، معصية الرسول ﷺ، فإن المعصية لها عواقب وخيمة، فالذين يقعون في الشغار ويعصون الرسول ﷺ تقع لهم مشاكل مع نسائهم في الغالب.\nفالواجب على المسلم أن يحذر ذلك، وأن لا يتزوج بالشغار أبداً، والنكاح بالشغار غير صحيح. نعم.","link":"https://binbaz.org.sa/fatwas/4566/حكم-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01407.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7748,"question":"هذه رسالة المرسل محمد ماجد سليمان ، يقول في رسالته: سؤالي حول وطء الزوجة في دبرها، فقد قرأت في كتاب المغني لـابن قدامة الجزء السابع، صفحة رقم اثنين وعشرين فصل: ولا يحل وطء الزوجة في الدبر في قول أكثر أهل العلم منهم علي وعبد الله وأبو الدرداء وابن عباس وعبد الله بن عمرو وأبو هريرة ، وبه قال سعيد بن المسيب وأبو بكر بن عبد الرحمن ومجاهد وعكرمة والشافعي وأصحاب الرأي وابن المنذر ، ورويت إباحته عن ابن عمر وزيد بن أسلم ونافع ومالك ، وروي عن مالك أنه قال: ما أدركت أحداً أقتدي به في ديني يشك في أنه حلال، وأهل العراق من أصحاب مالك ينكرون ذلك، واحتج من أجله بقول الله تعالى نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ [البقرة:223]، وقوله سبحانه: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ [المؤمنون:5-6]، فما رأي الدين في قول الذين أباحوا ذلك واحتجاج الإمام مالك بالآيتين الكريمتين؟ أرجو بيان حكم الدين بذلك، وفي قول الإمام مالك وابن عمر وزيد بن أسلم ونافع ؟! والسلام عليكم ورحمة الله.","title":"حكم وطء الزوجة في الدبر","answer":"الجواب: هذه المسألة مما قامت الأدلة الصحيحة عن رسول الله عليه الصلاة والسلام بالدلالة على تحريمها، وهي مسألة: الوطء في الدبر، هذه هي اللوطية المعروفة، ويقال لها: اللوطية الصغرى، فهي محرمة، هذه المسألة محرمة ومنكر ومن الكبائر، وقد جاءت الأحاديث عن رسول الله ﷺ تحذر من ذلك، وتبين أن وطء الدبر من الزوجة أمر محرم ومنكر، وبه قال عامة أهل العلم وجمهورهم للأحاديث الواردة في ذلك منها قوله عليه الصلاة والسلام: لا ينظر الله إلى رجل أتى رجلاً أو امرأة في دبرها رواه الترمذي والنسائي بإسناد صحيح وأحمد رحمة الله عليهم، ومنها قوله عليه الصلاة والسلام: إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن -وفي لفظ: في أعجازهن، ويروى عنه عليه الصلاة والسلام: ملعون من أتى امرأة في دبرها في أحاديث كثيرة كلها دالة على تحريم الوطء في الدبر.\nأما قوله جل وعلا: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم [البقرة:223]، فهي كما دلت عليه الأحاديث؛ الحرث: هو الفرج، هذا محل الحرث، هو القبل، أما الدبر فليس محل حرث، ولكنه محل قذر.. محل غائط، فليس محل الحرث، وإنما حرث الإنسان قبل زوجته.. محل الولادة.. محل البذر يطؤها فيه ... تحصل البذرة من المني ثم إذا أراد الله شيئاً انعقد ذلك المني مع منيها وجاء الولد، فالقبل هو محل الحرث وليس الدبر، الدبر محل القذر.. محل النجاسة، والقبل هو محل الحرث، وفي الحديث الآخر: مقبلات.. لما قالت اليهود: إن الرجل إذا أتى امرأته من دبرها في قبلها كان الولد أحول، أكذبهم الله وأنزل قوله سبحانه: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم ، قال النبي ﷺ: إذا كان في صمام واحد يعني: في القبل، هو الصمام، يعني: محل الحرث.\nفالحاصل أن الأحاديث الصحيحة وأقوال أئمة العلم من الصحابة ومن بعدهم كلها تدل على تحريم الوطء في الدبر، أما ما يروى عن ابن عمر أنه أجازه فهو غلط على ابن عمر ، والصواب أنه لا يثبت عن ابن عمر ، وإنما أراد ابن عمر أنه يجوز أن تؤتى من قفاها في قبلها، يعني: يأتيها من دبرها في قبلها، يعني يكون إلى الدبر وهي مثلاً على جنبها أو كالساجدة فيأتيها من جهة قفاها في قبلها في الفرج لا في الدبر نفسه، فغلط بعض الناس فظن أنه يجيز الوطء في الدبر، وإنما يأتيها مدبرة في قبلها لا في دبرها، هذا هو الذي أراده ابن عمر وغيره ممن نقل عنه ذلك، ولو فرضنا أن بعض التابعين أو من بعدهم أجاز ذلك صريحاً وتوهم وغلط في هذا فقوله مردود وباطل لا يلتفت إليه؛ لأنه مصادم للآية الكريمة ومصادم للأحاديث الصحيحة، وكل قول يخالف ما قاله الله ورسوله فهو واجب الاطراح وواجب الترك، ولا يجوز أن تعارض به السنة الثابتة عن رسول الله عليه الصلاة والسلام، كما لا يجوز أن يعارض به ما قاله الله عز وجل، فالله قال: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم فالحرث هو محله القبل فقط، وكذلك قال النبي ﷺ: إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن وقال: لا ينظر الله إلى رجل أتى رجلاً أو امرأة في دبرها، ويروى عنه عليه الصلاة والسلام: ملعون من أتى امرأة في دبرها، وقد جاء في حديث ابن عمر ومن حديث عبد الله بن عمرو بسند جيد موقوفاً ومرفوعاً أنه سئل عن الوطء في الدبر فقال: (اللوطية الصغرى).\nفالحاصل أنه محرم بالنص وبقول أهل العلم الذي هو كالإجماع، وما يروى عن ابن عمر أو زيد بن أسلم أو مالك كله لا أصل له ولا صحة له، ولا يثبت عن مالك إباحته فيما نعلم، وإنما أوهام وأغلاط من بعض الرواة عنه والمنتسبين إليه، أما المحفوظ عنه رحمه الله فهو المنع وعدم جواز الوطء في الدبر، وهكذا المحفوظ عن ابن عمر هو المنع وليس الجواز، وإنما توهم بعض الناس في بعض الروايات عنه أنها تؤتى من دبرها في قبلها، فظنوا أنه يجيز الوطء في الدبر، وإنما أراد أن تؤتى من جهة الدبر في القبل نفسه.. في الفرج نفسه لا في الدبر الذي هو محل القذر، هذا هو الحق، وهو كالإجماع من أهل العلم، والخلاف الذي في هذا عن بعض السلف شاذ لا يلتفت إليه ولا يعول عليه بل هو منكر وباطل. نعم..","link":"https://binbaz.org.sa/fatwas/4945/حكم-وطء-الزوجة-في-الدبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04203.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7948,"question":"هذه الرسالة من عبد الرحمن إبراهيم أحمد يقول فيها من جمهورية مصر العربية، يقول: أريد أن أتزوج ابنة خالي ولكني أنا رضعت مع أختها الكبرى، ولكن أختها الكبرى من أم والثانية -التي يريد أن يتزوجها- من أم، هل تحل لي الذي رضعت مع أختها أم لا؟","title":"هل يجوز التزوج من ابنة خاله التي رضع مع أختها؟","answer":"الجواب: إذا كان السائل رضع من أخت المخطوبة من أبيها زوجة أبيها أو من أمها فهو أخ لها، إذا كان رضع من زوجة أبيها أو رضع من أمها فإنه يكون أخاً لها، ولو لم يكن رضع معها، ما دام رضع مع أختها التي قبلها فإنه يكون أخاً لها أو مع أختها التي بعدها كله واحد.\nالمقصود: إذا كان رضع من زوجة أبيها أو من أمها فإنه يكون أخاً لها إما من الأم وإما من الأب وإما منهما جميعاً، فلا يحل له زواجها ولو كان رضاعه مع أخت كبرى أو مع أخت صغرى. نعم.\nالمقدم: أيضاً يقول: هل تحل لأخوي الأصغر أم لا؟\nالشيخ: إذا كان أخوه لم يرضع من أمها تحل له، إذا كان لم يرضع من أمها ولا من زوجة أبيها، ما بينهما رضاع فإنها تحل له، أما الذي رضع من أمها أو رضع من زوجة أبيها فإنها تكون أختاً له. نعم. لكن لابد يلاحظ أن الرضاع لابد يكون خمس رضعات فأكثر، ولابد يكون في الحولين، لابد أن يكون الرضاع خمس رضعات مضبوطة مثبوتة، ولابد أن يكون في الحولين، أما الرضاع أقل من خمس أو فوق الحولين الطفل فوق الحولين، هذا لا يؤثر على الصحيح من أقوال أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5473/هل-يجوز-التزوج-من-ابنة-خاله-التي-رضع-مع-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06804.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7952,"question":"نبدأ أولاً برسالة إبراهيم مطر، يقول إبراهيم مطر في رسالته: السلام عليكم ورحمة الله وبركاته، ووفقكم وجزاكم الله خيراً بما قمتم به من تبصير الناس في دينهم، ولي أسئلة أرجو أن تجيبوا عليها ولكم جزيل الشكر.السؤال الأول يقول: قال الله تعالى: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] فهل الأخت من الرضاعة مثل الأخت من النسب يحرم نكاحها إذا كانت مع أخت من النسب لها أو أختها من الرضاعة؟ أرشدونا أرشدكم الله.","title":"حكم الجمع بين الأختين من الرضاع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقوله سبحانه: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] يعم الأختين من النسب والأختين من الرضاع؛ لأن النبي عليه السلام قال: يحرم من الرضاع ما يحرم من النسب، فلا يجوز الجمع بين الأختين لا من النسب ولا من الرضاع، سواءً كانت الأختان شقيقتين أو لأب أو لأم أو مختلفتين، وسواءً كانتا من النسب أو من الرضاع، هذا هو الحق، وهو الذي عليه أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5470/حكم-الجمع-بين-الاختين-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06801.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8168,"question":"الأخ سعيد محمد زيد اليماني يقول في سؤاله: لقد تزوجت من عمي ابنته، وزوجته ابنة أختي بدون لا أعطيه شيئاً وأعطاني شيء، فهل هذا يجوز أفيدونا جزاكم الله خيراً؟","title":"زواج الشغار.. حكمه وكيفية تصحيحه إن وقع","answer":"الجواب: إذا كان هذا عن اتفاق بينكما وتشارط فهذا هو نكاح الشغار الذي نهى عنه النبي عليه الصلاة والسلام، وهو يسمى عند بعض الناس نكاح البدل فهذا لا يجوز، أما إذا خطبت منه وزوجك وخطب منك وزوجته من دون مشارطة ولا اتفاق على أنك تزوجه وهو يزوجك فهذا لا بأس ولكل واحدة مهر المثل، أو ما ترضى به من المال ولو قليلاً.\nأما التشارط والاتفاق على أنك تزوجه وهو يزوجك من دون شيء فهذا هو نكاح الشغار المنكر والنكاح فاسد، وعليكما أن تجددا النكاح إذا كان لكما رغبة في البنتين، كل واحد يجدد النكاح من دون شرط المرأة الأخرى، أنت تجدد وهو يجدد بدون شرط المرأة الثانية بمهر جديد وبرضا المرأة، والذي لا ترضاه زوجته عليه أن يطلقها طلقة واحدة لأن النكاح باطل لا يصلح، فيطلقها طلقة واحدة ثم إذا هداه الله بعد ذلك له أن يتزوجها بنكاح جديد.\nالمقصود أن هذا النكاح فيه تفصيل: إن كان عن مجرد تراضٍ من غير اتفاق ولا تشارط فلا بأس وعليكما أن تعطيا البنتين مهرهما إلا إذا سمحتا -مهر المثل- إلا إذا سمحتا عنكما، أو ترضيا كل واحد يرضي زوجته بما تيسر. أما إذا كان عن اتفاق أنك تزوجه وهو يزوجك أو مشارطة بينكما فهذا هو الشغار المنكر فالنكاح فاسد ولا يصح وعلى كل منكما إذا كان له رغبة في امرأته وهي ترغبه أن يجدد النكاح من طريق الولي وشاهدين عدلين ولا حاجة إلى الطلاق، بس يجدد النكاح بدون شرط المرأة الأخرى ولا بأس، أما الذي لا ترغبه زوجته أو لا يرغبها فيطلقها طلقة واحدة فقط، ولا تجبر عليه إذا كان لا ترغبه يطلقها طلقة واحدة وإذا اعتدت تزوجت بعد ذلك.\nنعم، إذا كانت قد دخل بها، إذا كان قد دخل بها خلا بها أو وطئها لابد من العدة، أما إذا كنتما لم تدخلا بهما فالطلاق ويكفيه حينئذ ولا حاجة إلى عدة.","link":"https://binbaz.org.sa/fatwas/5964/زواج-الشغار-حكمه-وكيفية-تصحيحه-ان-وقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10405.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8319,"question":"أخونا له سؤال آخر يقول: أخي عنده بنت مستجيبة -كما يقول- ولي ولد، وذهبت إلى أخي أخطب ابنته لولدي ووافق أخي على الزواج، وإني أزوج ابنتي ولده وشرط أخي صداق ابنته على ابني ستة آلاف ريال، وشرطت صداق ابنتي على ولد أخي سبعة آلاف ريال، وتم الزواج بين الطرفين. أفيدونا جزاكم الله خيراً، هل الجواز تام، أو يطلقن البنات؟","title":"زواج الشغار.. حكمه وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: إن كان وقع ذلك بينكما على سبيل الشرط كل واحد منكما يقول زوجني وأزوجك، وأنكما اتفقتما على هذا، هذا هو النكاح الذي نهى عنه النبي ﷺ وسماه: نكاح الشغار فلا يجوز هذا، بل النكاح فاسد وعلى كل واحد منكما أن يجدد النكاح لولده، كل واحد يجدد من دون شرط المرأة الأخرى وليس هناك حاجة إلى الطلاق، ولكن إذا كانت كل واحدة ترغب في زوجها وهو يرغب فيها فإنه يجدد النكاح من أبيها لزوجها بحضرة شاهدين ويكفي ذلك ولا حاجة إلى الطلاق.\nأما إن كان وقع منكما ذلك من غير شرط، بل خطب كل واحد من الآخر من دون شرط فلا حرج في ذلك والزواج صحيح والحمد لله، إنما المنكر أن يكون هناك شرط، بأن يقول كل واحد: زوجني وأزوجك، أو يقول: إذا زوجت ابني أنا أزوج بنتي لابنك، فالمعنى: يكون عن تشارط وعن اتفاق وتواطؤ، هذا هو الذي لا يجوز.\nأما إذا خطب كل واحد من الآخر من دون شرط فلا بأس بهذا، فينبغي التنبه لهذا الأمر، وإذا كان عن تشارط فالواجب تجديد النكاح، كل بنت يجدد لها إذا كانت راغبة في زوجها وهو راغب فيها، يجدد النكاح من وليها لزوجها بحضرة شاهدين من دون شرط المرأة الأخرى. نعم.\nأما إذا كان ما يرغبها أو لا ترغبه فإنه يطلقها طلقة واحدة، ولا يبقى معها. نعم.","link":"https://binbaz.org.sa/fatwas/6132/زواج-الشغار-حكمه-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_110/11002.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8604,"question":"يسأل أيضاً ويقول: إذا كان عند شخص زوجة وطلقها فهل له أن ينكح أختها في عدتها، وإذا ماتت فهل له أن يتزوجها في الحال، أفيدونا أفادكم الله؟","title":"حكم نكاح أخت الزوجة المطلقة قبل انتهاء العدة","answer":"الجواب: إذا طلق امرأة فليس له نكاح أختها ولا عمتها ولا خالتها إلا بعد العدة، بعد انتهاء العدة، إن كانت رجعية فهذا بالإجماع، بإجماع المسلمين ليس له أن يتزوج أختها ولا عمتها ولا خالتها إلا بعد انتهاء العدة؛ لأن الرجعية زوجة، أما إذا كانت بائن، طلاقاً بائناً الطلقة الأخيرة من الثلاث، أو مطلقة على مال -المخلوعة- فهذا فيه خلاف، ولكن الأرجح أنه لا يتزوجها إلا بعد انتهاء عدة أختها، أو بنت أختها، أو بنت أخيها، أما إذا ماتت فهذا لا بأس يتزوجها ولو بعد يوم أو يومين من موتها، إذا كان الزوجة ماتت فقد انتهت عدتها بالموت، انتهى الزواج بالموت، ففي هذه الحال لا حرج أن يتزوج أختها أو عمتها أو خالتها في الحال يعني، من حين ماتت الزوجة. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6743/حكم-نكاح-اخت-الزوجة-المطلقة-قبل-انتهاء-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21009.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8677,"question":"وهذه رسالة وردت إلينا من المستمع (ق. ل. ق) من العراق له فيها عدة أسئلة، يقول في أولها: لقد تزوج أخي امرأة من أقاربنا، وقد تزوج أخو هذه المرأة من أختي، أي: أنه زواج شغار، وقد علمت أنا السائل أنه لا شغار في الإسلام، فما العمل في هذا النكاح، فهل هو محرم على اعتبار أنه شغار، علماً أن كلاً من أخي وأخو زوجته قد أصبح لهم خمسة أطفال، كما أود أن أعلمكم أن زوجة أخي المذكورة هي ابنة عمة أمي، فهل هذا محرم أم لا، أفيدونا أفادكم الله؟","title":"زواج الشغار فاسد لا يصح","answer":"الجواب: الشغار محرم في الإسلام، يقول النبي ﷺ: لا شغار في الإسلام ونهى عن الشغار عليه الصلاة والسلام، قال: والشغار: أن يقول الرجل: زوجني أختك وأزوجك أختي، أو زوجني بنتك وأزوجك بنتي هذا هو الشغار، فإذا تزوج زيد من عمرو أخته على أن يزوجه أخته أو يزوجه بنته هذا هو الشغار، وهو فاسد ولا يصح، والواجب عليهما التوبة إلى الله والاستغفار، وإذا كان لكل واحد الرغبة في زوجته يجدد النكاح من دون شرط المرأة الثانية، إذا كان كل واحد يرغب زوجته وهي ترغب في زوجها فيجدد النكاح من وليها بدون شرط المرأة الأخرى، كل واحد يزوج موليته على زوجها بنكاح جديد من دون شرط المرأة الثانية. ولا حاجة إلى طلاق ولا شيء؛ لأن الماء ماءه والزوجة زوجته بموجب العقد الذي ظنه عقداً صحيحاً، فعليهما التوبة إلى الله ، وعليهما أن يجددا النكاح إذا كان كل واحد يرغب في زوجته وهي ترغب فيه، أما إن كانت لا ترغب فيه يطلقها طلقة؛ لأن النكاح فيه شبهة، فيطلقها طلقة حسماً لتعلقها به وتعلقه بها، وخروجاً من خلاف من صححه مع الإثم نعم، فعليهما التوبة إلى الله وعليهما التجديد للنكاح إذا كان كل واحد يرغب في زوجته وهي ترغب في زوجها بمهر جديد وعقد جديد وشاهدي عدل يحضران النكاح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6822/زواج-الشغار-فاسد-لا-يصح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21509.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8753,"question":"هذه رسالة وردتنا من السائل (عبد الله . ت. ق) من السعودية يقول: أنا شاب تزوجت بنت عمي بمهر قدره مائة وخمسين ألف ريال، واشترط أن نزوج ابنه وفعلاً تزوج ابنه على بنت أخي بنفس المهر، ثم يقول: حصل سوء تفاهم وادعى عمه أن بنته قد كمل رشدها وتلك أقل منها بحوالي ثلاث سنوات، فأقسم بالله العظيم! أنه لن يعطيني بنته أي: زوجتي فأفيدوني هل أترك هذا الزواج، أم أن هذا الزواج حرام أفيدونا أفادكم الله؟","title":"حكم نكاح البدل (الشغار)","answer":"الجواب: الزواج بالمشارطة أن هذا يعطي بنته هذا وهذا يعطي بنته هذا، أو بنت أخيه، أو أخته هذا يسمى: نكاح الشغار ويسميه بعض الناس: البدل، نكاح البدل، وهذا منكر ولا يجوز وهو نكاح فاسد وباطل لا يجوز؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، فليس لك أن تدخل على مدخل، بل يجب عليك أن تفارق هذه البنت، وليس لك أن تزوج هذا الزواج الفاسد المخالف لشرع الله عز وجل.\nأما النزاع بينكما فهذا إلى المحكمة تنظر المحكمة في أمر النزاع بينكما، لكن إذا صلحتما ولم تحتاجا إلى المحكمة فعليك أن تجدد النكاح مع ولي المرأة بدون شرط المرأة الأخرى، وهكذا المرأة الأخرى يجدد نكاحها بدون شرط المرأة الأخرى، فإذا جدد النكاح من دون شرط على مهر قليل أو كثير فلا بأس، وأما بشرط أنه يزوجكم وأن تزوجونه فهذا لا يجوز وهذا هو نكاح الشغار الذي نهى عنه الرسول صلى الله عليه وسلم وأنكره عليه الصلاة والسلام، أما النزاع الذي بينكما والمخاصمة فهذا إلى المحاكم وفيما تراه المحاكم الخير والبركة إن شاء الله.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6916/حكم-نكاح-البدل-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21711.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9246,"question":"هذه رسالة وردت إلى البرنامج من يسري عبد النبي غازي مصري من كفر الشيخ، وهو مقيم بالمنطقة الشرقية يقول في رسالته الطويلة: لي أخ طلق زوجته ثلاث مرات، لكونها تعمل ممرضة بمستوصف بالقاهرة، وكانت تقوم في غير أوقات العمل في شقتها بضرب الحقن للرجال والنساء، وتقوم بالذهاب إلى بعض الشقق لضرب حقن والله أعلم إن كانت نساء أو رجال، ويحضر إليها في الساعة الثانية من الليل بعض الرجال ويقولون: احضري معنا فلانة تعبانة، وتخرج دون إذن زوجها وهو غير راضٍ عن ذلك، حيث قام بطلاقها مرتين من أجل ذلك، وعند تكرار ذلك وهو ضرب الحقن للرجال كان يقول لها: لا تخرجي، تقول له: أخرج رغماً عنك، وليس لك علي حكم، هذا هو الحال وكانت عندما تطلق تقبل أقدامه وتبدي الندم حيث أرجعها مرتين وفي هذه المرة الثالثة تريد الرجوع، وتريد أن تعمل محللاً كي ترجع لزوجها، ولكن دون جدوى؛ لأنها لها ثلاث مرات أفيدونا أفادكم الله في حالتها؟","title":"حكم مراجعة المبتوتة عن طريق المحلل","answer":"الجواب: بعد الطلقة الثالثة لا رجوع إلا بعد زوج شرعي، والمحلل لا يجوز، المحلل تيس مستعار ملعون، لا يجوز نكاحه باطل ولا يحصل به التحليل، ومثل هذه الزوجة لا يرغب فيها ولو نكحت زوجاً آخر، ينبغي للزوج هذا أن لا يعود إليها، وأن لا يرغب فيها؛ لأنها متهمة ما دامت تعمل هذه الأعمال، فلا يليق به أن يرجع إليها، بل يطلب غيرها وأفضل منها: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nهذه المرأة متهمة بالشر، فلا يليق به أن يعود إليها لو تزوجت، ولا تحل له حتى تنكح زوجاً غيره، نكاحاً شرعياً لا تحليل، ويطأها الزوج الجديد ثم يفارقها بموت أو طلاق ثم تعتد، لكن ما دامت بهذه الصفة التي ذكرها السائل، فإنه لا ينبغي أن يعود إليها؛ لأن ظاهرها شر، ولأنها متهمة بالشر، نسأل الله السلامة والعافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7414/حكم-مراجعة-المبتوتة-عن-طريق-المحلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9343,"question":"هذه رسالة وردت من يحيى بن علي محمد جاد الله يماني مقيم في الأفلاج في الهدار، يقول في رسالته: أنا متزوج بدل بأختي لكن زوج أختي سلم المهر وأنا أيضاً سلمت مهر زوجتي، وقد تم هذا العقد برضا الزوجتين وكل واحدة راضية بزوجها، فهل هذا العقد صحيح أم لا أفيدونا أفادكم الله؟","title":"نكاح البدل لا يجوز","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في أحاديث كثيرة، عن جابر وعن أبي هريرة وعن ابن عمر وغيرهم، فالواجب على المؤمن أن يحذر هذا النكاح، وأن لا يفعله، فإن فعله فليتب إلى الله وليستغفر الله وليجدد النكاح، فإنه نكاح فاسد فيجتنبها حتى يجدد النكاح، إذا كان يرغب فيها وهي ترغب فيه عليه أن يجدد النكاح بدون شرط المرأة الأخرى، يعيد النكاح مع وليها عليها بمهر جديد ولو في الحال ما يحتاج عدة؛ لأن الماء ماؤه إذا كانت تريده ويريدها، فيجدد النكاح بدون شرط المرأة الأخرى، أما إن كانت لا تريده فإنه يطلقها طلقة ويفارقها لأنه نكحها بغير حق.\nوهكذا الآخر صاحبه يعيدها بنكاح جديد إذا كانت تريده، ولو في الحال ما يحتاج عدة يعيدها له وليها بمهر جديد، ولا بأس مع التوبة والاستغفار فإن كانت لا تريده فارقها بطلقة واحدة، هذا الواجب وهذا هو الصحيح من أقوال أهل العلم في هذه المسألة، نعم.","link":"https://binbaz.org.sa/fatwas/7514/نكاح-البدل-لا-يجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23810.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9430,"question":"أخونا (س. ص. الخثعمي ) من أبها بعث برسالة مطولة بعض الشيء يقول فيها: إنني ذهبت لأتزوج من أحد أفراد جماعتي، وسبق لي أن تزوجت عدة مرات ولدي بنين وبنات ولكن النساء متن، فذهبت وخطبت عند هذا الرجل الذي من الجماعة وقال: لن أزوجك ابنتي إلا بشرط أن تزوج ابني الأكبر ابنتك، فوافقت وتم الزواج، ولكل واحدة منهن مهر خاص بها وغير متساوٍ، وبرضا كل من ابنته وابنتي وتم الزواج، وبعد مضي خمسة أشهر من زواج ابنتي ماتت، وسؤالي الآن: ما حكم هذا الزواج؟ وهل هو شغار؟ وهل بوفاة ابنتي إن كان شغارًا هل انتهى الشغار بوفاتها أم لا، أرجو التوجيه في هذه الأمور جزاكم الله خيرا.","title":"صورة زواج الشغار وحكمه","answer":"الجواب: نعم. هذا النكاح شغار؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام عن جماعة من أصحابه  عن ابن عمر وأبي هريرة وجابر ومعاوية أنه ﷺ نهى عن الشغار، والشغار مثل ما قال النبي ﷺ: أن يقول الرجل للرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار.\nفالذي ذكرته في السؤال شغار، وما دامت المرأة ماتت فأولادك لاحقون بك، وهم أولادك من أجل شبهة النكاح، وعليك التوبة إلى الله، والندم على ما حصل منك، وهكذا صاحبك عليه التوبة إلى الله، وعلى صاحبك الذي زوجته موجودة أن يجدد النكاح، عليه أن يجدد العقد؛ لأن العقد الأول فاسد، والأولاد لاحقون بآبائهم لأجل الشبهة، وعليه التوبة كما أن عليك التوبة، وعليه أن يجدد العقد بعد ما علم حكم الشرع يجدده من دون شرط امرأة أخرى، يجدده بشاهدين ولو ما توصلتما إلى المحكمة، ولو بالتزويج في البيت أو عند من ترون بحضرة شاهدين، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7595/صورة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19013.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9925,"question":"هذه رسالة وردتنا من مرسلة رمزت لاسمها بأختكم في الله (ص. س) من القيصومة في المملكة تقول في رسالتها: أنا سيدة في الأربعين من عمري لي أطفال سبعة ثلاثة اختارهم الله عز وجل إليه وأربعة أحياء، تقول: تتلخص مشكلتي في عدة أسئلة:أولها: أنني متزوجة منذ عشرين سنة من رجل لا يعرف الصلاة ولا الصيام ويشرب المحرمات من خمر وما شابهه والعياذ بالله، وكلما حاولت الخلاص منه يقول لي: بأنه سوف يتوب، ولكنه بالكلام فقط، وكل من أشكي له حالي يقول: اصبري من أجل أطفالك، وقد صبرت كل هذه السنوات من أجلهم، والآن كبروا وأصبحوا رجال ويطلبون هم مني ذلك ويقولون بأن البيت بيتهم ولا دخل للوالد، وأنا أسألكم الآن: هل علي ذنب في جلوسي معه أم لا، وكذلك جلوس أطفالي عنده؟ أفيدوني أفادكم الله.","title":"حكم البقاء مع زوج لا يصلي ويفعل الكبائر","answer":"الجواب: لا ريب أن ترك الصلاة كفر، ولا ريب أن ترك الصيام من أعظم المعاصي، ولا ريب أن شرب المسكر من أعظم المعاصي والكبائر، فهذا الرجل قد جمع أنواعاً من الخبث والشر وأعظم ذلك ترك الصلاة، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فهذان حديثان عظيمان صحيحان عن رسول الله عليه الصلاة والسلام كلاهما يدل على كفر هذا الرجل، والمسألة فيها خلاف:\nبعض أهل العلم يقولون: لا يكفر إلا إذا كان لا يعتقد الوجوب، إذا كان ينكر وجوبها، وإلا فإنه يكون عاصياً معصية عظيمة ولكن لا يكفر بذلك.\nوذهب آخرون من أهل العلم: إلى أنه يكفر بترك الصلاة ولو لم ينكر وجوبها، وهذا هو الحق وهو الصواب أنه يكفر بترك الصلاة ولو لم ينكر وجوبها، فالذي أنصحك به وأوصيك به أن تمتنعي منه، وأن لا تمكنيه من نفسك حتى يتوب إلى الله ويرجع إلى الصلاة، والأولاد أولاده للشبهة التي هي شبهة النكاح، والقول بأنه لا يكفر بذلك هذه شبهة، فالأولاد أولاده ولا شك أنهم أولاده، ولكنك تبقين في البيت عند أولادك لأنهم كبار، وتمتنعين من أن يقربك بجماع أو غيره حتى يتوب إلى الله وحتى يدع عمله السيئ ولا سيما ترك الصلاة، فإذا تاب إلى الله وصلى فلا مانع، وعليه أن يتوب إلى الله أيضاً من ترك الصيام ومن شرب الخمر، وعلى أولاده أن يعينوه على الخير وأن ينصحوه ويستعينوا على هذا بأقاربهم الطيبين من أعمام وبني عم طيبين يعينونهم على نصيحة والدهم لعل الله يهديه بأسبابهم، فإن من أعظم بره أن ينصح ويوجه إلى الخير لعل الله يهديه بذلك، ولعله يسمع كلمتي هذه، ولعلكم تسجلونها إذا سمعتموها وتقرءونها عليه، فالله جل وعلا نسأله له الهداية. فالحاصل أن عليك أن تبتعدي عنه وألا يقربك حتى يتوب إلى الله من ترك الصلاة، فإذا تاب من ترك الصلاة فهو زوجك، وأما شرب الخمر وترك الصيام فهما معصيتان عظيمتان، لكنهما لا يوجبان بطلان النكاح عند أهل العلم عند أهل السنة والجماعة ، وعليك وعلى أولادك وعلى أقاربه وعلى الأخيار من جيرانه أن ينصحوه، وعليه أن يتقي الله وأن يبادر إلى التوبة قبل أن يحل به الأجل، قبل أن ينزل به الأجل، والخمر شرها عظيم، وقد صح عن رسول الله عليه الصلاة والسلام: أنه لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها والمحمولة إليه وبائعها ومشتريها وآكل ثمنها نعوذ بالله، وصح عن رسول الله أيضاً عليه الصلاة والسلام أنه قال: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن فهذا يدل على ضعف الإيمان أو عدم الإيمان نسأل الله العافية، وقال عليه الصلاة والسلام: إن عهداً على الله لمن مات وهو يشرب الخمر أن يسقيه الله من طينة الخبال، قيل: يا رسول الله! وما طينة الخبال؟ قال: عصارة أهل النار، أو قال: عرق أهل النار.\nوأما ترك صيام رمضان فهو أمر عظيم؛ لأن صيام رمضان من أعظم الواجبات ومن أركان الإسلام، وقد ذهب بعض أهل العلم إلى كفر من ترك الصيام عمداً، فيجب عليه أن يتوب إلى الله وأن يصوم رمضان وأن يحافظ على الصلاة ومن تاب تاب الله عليه، نسأل الله لنا وله ولجميع المسلمين التوفيق للتوبة النصوح والهداية إلى سبيل الخير، والعافية من طاعة الشيطان ومن طاعة قرناء السوء، وينبغي أن يوصى باجتناب قرناء السوء وصحبة الأشرار؛ فإن صحبة الأشرار تجره كثيراً، تضره كثيراً وتجره إلى أسباب الفساد وإلى أسباب غضب الله. فالواجب عليه أن يحذر صحبة الأشرار وأن يبتعد عن قرناء السوء وأن يتوب إلى الله من ترك الصلاة ومن ترك الصيام ومن شرب المسكر، وأن يستقيم على طاعة الله ورسوله، والله يقول جل وعلا: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، والنبي يقول ﷺ: التائب من الذنب كمن لا ذنب له نسأل الله لنا ولكم وله ولجميع المسلمين الهداية والتوفيق والتوبة الصادقة.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8100/حكم-البقاء-مع-زوج-لا-يصلي-ويفعل-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26905.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10070,"question":"المستمع سعيد علي محمد يماني بعث يسأل ويقول: رجل تزوج امرأة على أن يحللها لزوجها الأول، وبعد الزواج رفض أن يطلقها، فما هو توجيهكم؟","title":"حكم زواج التحليل","answer":"الجواب: إذا كان النية تحليلها لزوجها، إذا كانت النية تحليلها لزوجها فهذا نكاح باطل وصاحبه ملعون نعوذ بالله من ذلك والرسول ﷺ لعن المحلل والمحلل له وهو نكاح ملعون صاحبه وهو فاسد لا يحلها لزوجها الأول، ولا للثاني الذي نكحها بنية التحليل ولو رغب فيها، بل يجب عليه أن يطلقها طلقة واحدة لإبطال هذا العقد الفاسد وإزالة شبهته، وبعد ذلك هي مخيرة شاءت تزوجت عليه وإن شاءت تزوجت على غيره بعد خروجها من العدة إذا كان وطئها، فإذا خرجت من العدة بثلاث حيض إن كانت تحيض أو بثلاثة أشهر إن كانت كبيرة لا تحيض أو صغيرة لا تحيض، وإذا خرجت من العدة فهي تنكح من شاءت غير زوجها الأول حتى يتزوجها زوج شرعي ويطأها يتزوجها زوج شرعي ما أراد التحليل ثم طلقها أو مات عنها تحل لزوجها الأول، أما هذا الذي أراد التحليل ولو وطئها لا تحل لزوجها الأول وهو عاص بعمله، ملعون كما في الحديث يجب عليه أن يفارقها بطلقة واحدة ثم بعد التوبة وخروجها من العدة له أن يتزوجها من جديد إذا رضيت بذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8245/حكم-زواج-التحليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30408.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10384,"question":"حدثونا عن نكاح الشغار بالتفصيل، فهناك كثير من الأقرباء والأصدقاء كل منهم متزوج أخت الآخر والعكس بالعكس؟","title":"زواج الشغار.. تعريفه وحكمه","answer":"الجواب: الشغار: هو الذي يكون بالشرط زوجني وأزوجك هذا الشغار، أما إذا قال: زوجني وأزوجك، ما أزوجك حتى تزوجني هذا هو الشغار ما يجوز، النكاح باطل لا يجوز، أما إذا خطب منه، وهذا خطب منه من دون مشارطة فلا بأس، زوجه أخته، وزوجه أخته، بنته بنته عمته عمته لا بأس، لكن من دون مشارطة، أما أن يقول: لابد تزوجني وأزوجك، ما تزوجني ما أوزوجك، هذا يقال له: نكاح الشغار، والرسول نهى عنه عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8556/زواج-الشغار-تعريفه-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28009.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10423,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول المستمع خليفة السعيد من سوريا يقول: أنا رجل مسلم اتفقت أنا ورجل مسلم آخر وزوجته أختي وزوجني بنته، وأنجبت بنته مني تسعة أولاد، وأنا أحبها لأنها صاحبة دين وخلق، هل زواجي صحيح؟ وإذا لم يكن صحيحاً فكيف أعمل، وجزاكم الله خيراً؟","title":"حقيقة نكاح الشغار وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه.\nأما بعد: فهذا الزواج فيه تفصيل: فإن كنت اشترطت عليه وشرط عليك هذا الزواج فهذا يسمى نكاح الشغار، وقد نهى عنه النبي عليه الصلاة والسلام في الأحاديث الصحيحة، والشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي أو بنتي، أو يقول نحو ذلك كبنت أخيه ونحو ذلك، هذا يقال له: الشغار، ويقال له عند بعض الناس: نكاح البدل، فإذا كنت حين زوجته أختك وزوجك بنته عن اشتراط بينكما فهذا يسمى نكاح الشغار، وعليكما أن تجددا العقد، إذا كان كل واحد يرغب في زوجته وهي ترغب فيه فيجدد النكاح بمهر جديد وشاهدين، تقول: زوجتك، وهو يقول: زوجتك، أنت تقول: زوجتك أختي، بمهر جديد ولو قليلاً بحضرة شاهدين عدلين إذا كانت راضية، وهو كذلك إذا كانت بنتك تريده، يقول: زوجتك، وتقول: قبلت، ولو بمهر قليل كمائة ريال أو مائتين أو أكثر، بحضرة شاهدين وينتهي الأمر والحمد لله، وما مضى معفو عنه لأجل الجهل، وأولادكم لكم، أولادك وأولاده كل واحد أولاده تابعون له للجهل، والله يعفو عما سلف بسبب الجهل سبحانه وتعالى، كما قال جل وعلا في كتابه الكريم: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فقال الله: قد فعلت.\nأما إن كنتما لم تشترطا، بل خطب منك وخطبت منه فقط فالنكاح صحيح ولا حرج، خطب أختك وخطبت بنته من دون مشارطة فالنكاح صحيح ولا حرج عليكما والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8593/حقيقة-نكاح-الشغار-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31701.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10456,"question":"المستمع (م. ع. س) يقول: ما حكم الزواج من امرأة لا تصلي؟","title":"حكم الزواج من امرأة لا تصلي","answer":"الجواب: لا يجوز لمسلم أن يتزوج امرأة لا تصلي؛ لأن ترك الصلاة كفر، كفر أكبر على الصحيح، وعند آخرين كفر أصغر، فلا يجوز له أن يتزوج امرأة لا تصلي؛ لأنها كافرة على الصحيح حتى تصلي، وفي النساء بحمد الله المسلمات غنية عنها، يلتمس، يلتمس المرأة الطيبة، يقول النبي ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك فالمؤمن يلتمس ذات الدين المعروفة بالستر والصلاة وحسن السمعة، حتى يختارها شريكة له، أما من عرفت التساهل في دينها، أو بترك الصلاة، فهذه لا يرغب فيها، ولا ينبغي له أن يتزوجها، ولا يصح نكاحه لها إذا كانت لا تصلي، إلا إذا كان مثلها لا يصلي، صح نكاحهما، وهما كافران حينئذ، كما يصح نكاح الوثني مع الوثنية، واليهودي مع اليهودية، والنصراني مع النصرانية، كلهم كافر، نكاحهم صحيح فيما بينهم، إذا تمت شروطه الأخرى، هكذا الذي لا يصلي مع من لا تصلي نكاحهما صحيح، إذا تمت الشروط الأخرى.\nأما المسلم الذي من الله عليه بالاستقامة والصلاة فليس له أن ينكح امرأة لا تصلي، نسأل الله السلامة والعافية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8632/حكم-الزواج-من-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31910.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10572,"question":"سماحة الشيخ! مع بداية هذه الحلقة أمامي رسالتان، الأولى: من الأخت المستمعة (ج. أ. ف) من العراق، والثانية: من الأخت نادية آل محمد السعيد من الجزائر، الرسالتان اتحدتا في السؤال عن خطبة زوج لا يصلي ولاسيما إذا تدخل الوالدان في ذلك وأرغما البنت على القبول بهذا الخاطب رغم أنه لا يصلي، كيف يكون تصرف المخطوبة جزاكم الله خيراً، وهل تلجأ إلى الجهات الرسمية كي تسلم من هذه الخطبة؟","title":"حكم الزواج بمن لا يصلي ونُصح الآباء في ذلك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فأسأل الله  بأسمائه الحسنى وصفاته العلى أن يولي على العراق حاكماً صالحاً يحكم فيهم بشرع الله، وأن يصلح حكام الجزائر ويوفقهم لما فيه رضاه وأن يعينهم على تحكيم شريعته، وأن يصلح أحوال الجميع، نسأله سبحانه أن يصلح أحوال الشعب العراقي وأحوال الشعب الجزائري، وأن يولي على العراق من يحكم فيهم بشرع الله، وأن يولي على جميع بلاد المسلمين من يحكم فيهم بشرع الله.\nأما جواب السائلتين فلاشك أن من لا يصلي لا يجوز للمسلمة أن تقبل الزواج منه؛ لأن ترك الصلاة كفر، والصواب: أنه كفر أكبر، وقال الأكثرون: أنه كفر أصغر.\nوالصواب: أنه كفر أكبر وإن كان لا يجحد الوجوب، أما إذا كان يجحد الوجوب فهذا كفر أكبر عند جميع العلماء ليس فيه خلاف، ولكن الخلاف فيما إذا كان لا يجحد الوجوب ولكنه يتكاسل عن الصلاة يتركها كلها أو بعضها، فالصواب في هذا الصنف وأمثاله أنه كافر كفر أكبر؛ . لقول النبي ﷺ في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  : بين الرجل وبين الكفر والشرك ترك الصلاة والأصل في هذا الكفر الأكبر، الكفر المعرف والشرك المعرف بأل فهو كفر أكبر.\nوروى الإمام أحمد رحمه الله وأهل السنن رحمهم الله بإسناد صحيح عن بريدة  عن النبي ﷺ أنه قال : العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وثبت عنه ﷺ أنه لما سئل عن الأمراء الذين تعرف منهم بعض المنكرات وعن الخروج عليهم، قال له: اسمعوا وأطيعوا ونهى عن الخروج عليهم- قال: إلا أن تروا كفراً بواحاً عندكم من الله فيه برهان وفي رواية أخرى قال: ما أقاموا فيكم الصلاة فدل على أن عدم إقامة الصلاة كفر بواح.\nفالحاصل: أن ترك الصلاة مطلقاً أو بعضها كالظهر أو الفجر أو نحو ذلك كفر أكبر، فلا يجوز للولي سواء كان أباً أو غير أب أن يجبر المولية على نكاح من لا يصلي وهي تصلي وهي مسلمة، بل هذا خيانة للأمانة، بل يجب عليه أن يلتمس لها الرجل الصالح الطيب حتى يضع الأمانة في محلها، ولا يجوز للبنت أن تطيعه في ذلك ولو كان أباها؛ لقول النبي ﷺ: إنما الطاعة في المعروف وقوله ﷺ: لا طاعة لمخلوق في معصية الخالق ولها أن ترفع الأمر إلى ولي الأمر إلى الحاكم الشرعي حتى يخلصها من هذا البلاء.\nوالواجب على الأولياء أن يتقوا الله، وأن لا يزوجوا مولياتهم إلا على الأكفاء، وأهم شيء الكفء في الدين إذا كانت المولية مسلمة، والله يقول جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71] فالكافر ليس ولياً للمؤمنة، ولا يجوز لوليها أن يزوجها بتارك للصلاة أو معروف بالفسق إذا لم ترض بذلك، وهذا فيما يتعلق بغير الكفر، أما بالكفر فلا يجوز لها الرضا، ولو رضيت لا يجوز لها أن تزوج بالكافر وهي مسلمة.\nلكن الفسق لو كان عنده بعض الفسق كشرب الخمر وهو يصلي، أو يتعاطى بعض المعاملات الربوية، أو يتهم بشيء من الأعمال المنكرة، الأعمال التي هي تعتبر معصية، هذا يجوز للمسلمة أن تتزوجه، لكن تركه أولى والتماس الطيب أولى بالمؤمنة، أما الكافر فلا ليس لها أن تتزوج الكافر، كالذي يسب الدين، أو يستهزئ بالدين، أو يترك الصلاة أو ما أشبه ذلك مما يوجب كفره، كالذي يستحل الخمر أو يستحل الزنا هذا كفر أكبر نسأل الله العافية، أو يستحل الربا.\nفالحاصل أن الواجب على الأولياء أن لا يزوجوا مولياتهم المسلمات إلا بمسلمين، وليس له أن يزوج موليته المسلمة بمن يترك الصلاة أو يتعاطى ما يوجب كفره نسأل الله السلامة والعافية. نعم.\nالمقدم: جزاكم الله خيراً، إذاً كلمة للوالدين لعله من المناسب أن تتفضلوا بها الآن؟\nالشيخ: تكلمنا سابقاً ليس للوالدين ولا غير الوالدين أن يزوجوا المولية بمن يخالفها في الدين، إذا كانت مسلمة ليس له أن يزوجها كافراً، لا نصرانياً ولا يهودياًَ ولا وثنياً ولا تاركاً للصلاة ولا غيرهم ممن يحكم عليه بكفر، كالساب للدين، والمستهزئ بالرسول أو بالدين ونحو ذلك ممن يحكم بكفره، حتى العاصي ينبغي أن لا يزوجها العاصي وإن كان مسلماً، ينبغي أن يلتمس لها الطيب الكفء، لكن لو تزوجت بمسلم عاصي برضاها صح، لكن كونه يلتمس لها الطيب البعيد عن المعاصي هذا من أداء الأمانة، وإذا كرهت الزواج بالعاصي لم يجبرها على العاصي حتى العاصي لا يجبرها عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8741/حكم-الزواج-بمن-لا-يصلي-ونصح-الاباء-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32301.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10574,"question":"من القصيم من بريدة المستمع محمد .........بعث برسالة تضمنها ثلاثة أسئلة، في سؤال الأول يقول: ما هو نكاح الشغار؟ أفيدونا جزاكم الله خيراً؟","title":"صفة زواج الشغار وحكمه","answer":"الجواب: نكاح الشغار هو: أن يشترط كل واحد من الوليين نكاح المولية الأخرى، فيقول أحدهما زوجتك بنتي على أن تزوجني بنتك، أو أختي على أن تزوجني أختك، وهكذا ما أشبه ذلك، يعني يشترط كل واحد تزوجه بالأخرى، زيد يخطب هند، وعمرو يخطب أخت زيد، كل واحد يشترط على الآخر، زيد يشترط على عمرو، وعمرو يشترط على زيد أخته، أو بنته، أو بنت أخيه، هذا هو الشغار؛ لقول النبي ﷺ: الشغار أن يقول رجل زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار أي التشارط في تزويج المولية للشخص سواءٌ كانت بنته، أو أخته، أو بنت أخيه، أو بنت عمه، يقول أنا أزوجك إياه لكن بشرط أنك تزوجني بنتك ، أو أختك، أو ما أشبه ذلك، وهذا لا يجوز المهر هذا باطل، أما لو خطب منك وخطب الآخر من دون مشارطة، فلا حرج، وخطب بنت هذا وهذا خطب بنت هذا، والآخر خطب بنته، أو أخته لا حرج، من دون مشارطة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8747/صفة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32307.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10581,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ل. و. ك) يقول: أنا شاب تزوجت وكان عمري فوق السادسة عشرة، وكنت في ذلك الوقت لا أصلي، وكانت زوجتي تصلي وأنا لا أصلي، وقد جلست مع زوجتي مدة طويلة حوالي سنة أو أكثر، وبعد ذلك لجأت إلى الله وتبت واستغفرت وندمت على هذا المنكر، وبعد فترة من التوبة حملت زوجتي وأنجبت لي ولداً، وتم بيننا التوفيق بعد ذلك، سؤالي يقول:ما حكم عقد النكاح؟ وهل هو باطل أم هو صحيح؟ وما حكم الوقت الذي قضيته مع زوجتي قبل التوبة وبعد التوبة؟ وما حكم العقد بعد التوبة هل يكفي أم لا يجوز إلا بتجديد العقد؟ وما حكم الولد بعد التوبة؛ لأنه جاء بعدها؟ وهل توبتي تكفي أم علي شروط يجب علي أن أعملها مثل الكفارة أو الصيام أو غير ذلك جزاكم الله خيراً؟","title":"حكم من تزوج بامرأة تصلي وهو لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فلا شك أن ترك الصلاة من أعظم الجرائم، ومن أكبر المنكرات؛ لأنها عمود الإسلام، من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع، وقد دل الحديث الصحيح عن رسول الله عليه الصلاة والسلام أن تركها كفر، فقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه الإمام مسلم في صحيحه، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، والأحاديث في هذا المعنى كثيرة، لكن ينظر في تارك الصلاة، فإن كان قد جحد وجوبها ولم يقر بوجوبها فهذا كافر عند جميع العلماء، والعقد باطل إذا تزوج امرأة تصلي وهو لا يصلي فعقده باطل؛ لأن الله جل وعلا قال في حق الكفرة مع المسلمين: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] فلا يحل للكافر نكاح المسلمة، ولا للمسلمة نكاح الكافر، ويقول جل وعلا: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]، يعني: لا تزوجوا المشركين حتى يؤمنوا.\nأما إن كان السائل يؤمن بوجوبها ويعلم أنها فريضة، ولكن يتهاون فتركها تهاوناً فهذا النكاح فاسد على الصحيح، ولكن ولدك هذا تابع لك، لأجل الشبهة؛ لأن بعض أهل العلم يرى أنه ليس بكافر، إذا كان يعتقد وجوبها ولكنه تكاسل، فيرى أنه ليس بكافر كفراً أكبر، ولكنه كفر أصغر، ويرى أن النكاح صحيح، وأن ولده لاحق به، فأنت بهذه الحال إذا كنت لا تجحد وجوبها فالولد لاحق بك؛ لأجل الشبهة.\nوالصحيح أن تركها كفر أكبر، لكن من أجل الشبهة الولد لاحق بك، وعليك أن تجدد النكاح، وأن تتوب إلى الله مما سلف توبة صادقة، وعليك أن تجدد النكاح بعقد شرعي ومهر وشاهدين، إذا كانت تريدك وأنت تريدها، فإنك تجدد النكاح هذا هو الصواب.\nوأولادك لاحقون بك الذين ولدوا قبل التجديد، وعليك التوبة إلى الله والندم والإقلاع من هذا العمل السيئ، والعزم الصادق أن لا تعود فيه، ومن تاب تاب الله عليه، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له، فالحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8753/حكم-من-تزوج-بامراة-تصلي-وهو-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32401.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10696,"question":"سماحة الشيخ! يشكو كثير من النساء من أنهن ابتلين بأزواج لا يصلون، ولم يكتشفن هذا إلا بعد الزواج؟","title":"حكم بقاء المرأة عند زوج لا يصلي","answer":"الجواب: هذا من البلاء العظيم، فإذا عرفت ذلك تمتنع منه وتذهب إلى أهلها، ولا تمكنه من نفسها، لا من جماع ولا غيره حتى يتوب إلى الله ويستقيم على الصلاة، وإلا فالواجب الفراق. نعم.\nالمقدم: قد تتحجج بالأطفال، وما أدراك ما الأطفال؟\nالشيخ: ليس في هذا حجة، الرزق على الله، هي أولى بأطفالها حتى يهديه الله.\nالمقدم: والحالة هذه.\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.\nالشيخ: الله المستعان، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/8861/حكم-بقاء-المراة-عند-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33011.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":10702,"question":"يقول: لي أعمام كل واحد عنده ولد وبنت زوجوا أبناءهم من بعضهم، هل يسمى هذا بزواج الشغار؟ علماً بأنهم أنجبوا أطفال، فما رأي سماحتكم في هذا الزواج؟ وهل هذا الزواج باطل علماً بأن لكل زوجة من الزوجات مهر خاص ولا يساوي مهر الأخرى، فهل في هذه الحالة يجب الطلاق، وهل الأطفال شرعيون أم لا، أفيدونا جزاكم الله خيراً؟","title":"نكاح الشغار.. حكمه وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: إذا كان الزواج من دون اشتراط بل خطب هذا وخطب هذا وزوج هذا وزوج هذا بالرضا، فليس هذا شغارا ولا حرج أن ينكح الإنسان ابنة عمه أو ابنة خاله والآخر كذلك لا حرج في ذلك، الشغار أن يكون عن شرط زوجني وأزوجك، هذا هو الشغار، إذا قال كل منهما للآخر: زوجني ابنتك وأنا أزوجك بنتي، أو زوج ولدي وأنا أزوج ولدك أو ما أشبه ذلك، هكذا جاء الحديث عن رسول الله عليه الصلاة والسلام لما سئل عن الشغار قال: هو أن يقول الرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار يعني المشارطة هذا يشرط وهذا يشرط، أما إذا خطب هذا من هذا وخطب هذا من هذا من دون مشارطة فلا حرج في ذلك ولا يسمى شغاراً.\nوإذا كان شغاراً بالمشارطة فالأولاد تابعون لآبائهم من أجل شبهة النكاح؛ لأن نكاح الشغار فاسد وفيه خلاف بين أهل العلم، فالشبهة التي في صحة النكاح وفساده توجب إلحاق الأولاد بآبائهم، ولكن ما دام كل واحد يرغب في زوجته فإنه يجدد النكاح كل واحد يجدد النكاح، وإذا كانت زوجته لا ترغب فيه فإنه يطلقها طلقة واحدة وتكفي، أما إذا كان يرغب فيها وهي ترغب فيه فإنه يجدد النكاح، إذا كان هناك مشارطة فيزوجه من جديد يزوج وليها من جديد بعقد شرعي ومهر شرعي وحضور شاهدين ولا حاجة إلى عدة بل في الحال؛ لأن الماء ماؤه إن كانت حاملاً فالماء ماءه.\nفالحاصل: أنه يزوج في الحال بحضرة شاهدين وبعقد جديد ومهر جديد إذا رضيت به وهو أحبها فلا بأس بذلك، أما إذا كان لا يرغب فيها أو هي لا ترغب فيه، فيطلقها طلقة واحدة فإذا اعتدت تزوجت من شاءت.\nفينبغي الفهم لهذا المقام لئلا يشتبه المقام، فالمشارطة تجعل النكاح شغاراً وعدم المشارطة تجعل النكاح صحيحاً، فالذي يقول لعمه أو لخاله: زوجني بنتك وهو يقول: أزوجك بنتي مشارطة زوجني وأزوجك، يعني: ما يرضى هذا إلا بزواج هذا، لا يعطيه ابنته حتى يعطيه ابنته أو أخته حتى يعطيه أخته، فهذا هو الشغار، أما إذا كان بالرضا من دون مشارطة فلا حرج في ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8878/نكاح-الشغار-حكمه-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34202.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10860,"question":"من العراق بغداد المواطن عادل جاسم بعث يسأل ويقول: يقال: إن رسول الله ﷺ حرم زواج المتعة في خطبته الشهيرة أثناء حجة الوداع، أصحيح ما يقال؟","title":"حكم نكاح المتعة","answer":"الجواب: نعم حرم نكاح المتعة في حجة الوداع -عليه الصلاة والسلام- قال: إني كنت أذنت في الاستمتاع من النساء، وإن الله قد حرم ذلك إلى يوم القيامة، فالمتعة محرمة، إذ قال بعض أهل العلم: إنه حرمها مرتين في حجة الوداع، وفي عام الفتح، ولكن في هذا نظر، وبكل حال فهي أصبحت محرمة منسوخة، سواء كانت محرمة مرتين، أو مرة واحدة، فهي أصبحت محرمة وممنوعة، ولا يحل نكاح المتعة، بل لابد أن يكون النكاح عن رغبة، لا عن متعة عند أهل السنة والجماعة بإجماع أهل السنة والجماعة.","link":"https://binbaz.org.sa/fatwas/9041/حكم-نكاح-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35709.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10881,"question":"سؤال لأحدهما يقول: أنا مواطن مصري أشتغل في الأردن تزوجت من عام (73) ميلادية، وعندي خمسة أولاد، وعقدت عقد الزواج على زوجتي، وهي لا تصلي، وأنا -الحمد لله- أصلي، وكنت لا أعرف أن عقد الزواج باطل إذا كان أحد الزوجين لا يصلي إلا من برنامجكم نور على الدرب، هل يجوز أن أعقد على زوجتي عقدًا جديدًا بشاهدي عدل، وولي بدون المأذون الشرعي والمحكمة، خوفًا من الوقوع في معصية مع زوجتي عند ذهابي إلى مصر؛ لأن المأذون والمحكمة سوف يعقدان بعد إجراءات طويلة ووقت طويل، وما مصير الأولاد الخمسة؟","title":"حكم عقد النكاح بامرأة لا تصلي","answer":"الجواب:  نعم الصواب أن الرجل إذا تزوج امرأة لا تصلي، أو تزوجها وهي تصلي وهو لا يصلي أن العقد لا يصح في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء لقوله ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح عن بريدة بن حصيب  ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، وهناك أحاديث أخرى كذلك تدل على هذا المعنى. فإذا وقع هذا النكاح بين رجل يصلي وهي لا تصلي، أو بالعكس فإنه يجدد من شاهدين عدلين، والمأذون الشرعي مع الولي لابد من الولي إما بحضور الولي، وإلا وكيل الولي، وليس هناك ضرورة إلى المحكمة، ولا إلى المأذون، بل إذا حضر الولي والزوج وشاهدين، وزوجه وليها بعدما تاب الله على من لا يصلي، واستقامت الأحوال فإنه يكفي، يقول له الولي: زوجت، ويقول الزوج: قبلت بحضرة شاهدين إذا كان راضية المرأة بذلك فالحمد لله. أما الأولاد فهم يلحقون لأجل شبهة النكاح، وذهب الأكثرون إلى أنه يصح النكاح، ولو كان لا يصلي إذا كان موحدًا لله، مؤمنًا بالإسلام، يؤمن بالآخرة، وليس عنده من النواقض إلا ترك الصلاة، فقال الأكثرون: أن تركها لا يكون كفرًا أكبر، بل يكون كفرًا دون كفر، ولا يكون كفرًا أكبر يبطل النكاح. ولكن الصواب قول من قال بأنه كفر أكبر للأحاديث السابقة وغيرها من الأحاديث الدالة على ذلك، ولأن الصلاة عمود الإسلام، لا يقاس عليها غيرها، هي عمود الإسلام. فالواجب على من تركها أن يبادر بالتوبة، وأن يدخل في الإسلام من جديد بتوبته إلى الله  ويجدد النكاح إذا كانت زوجته طيبة مصلية سليمة وهو المقصر بترك الصلاة يجدد النكاح.  أو بالعكس هي لا تصلي وهو يصلي يجدد النكاح، وليس من شرط ذلك أن يكون عند المحكمة، أو عند المأذون إذا وجد الولي والشاهدان العدلان والزوج وهي راضية كفى والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9065/حكم-عقد-النكاح-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35911.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":10992,"question":"من الطائف رسالة بعث بها المستمع (ح. هـ. م. الحارثي) يقول: أبعث إليكم بسؤالي هذا وهو أنني قد تزوجت، ولم أبلغ سن الرشد، وإن ولي أمري هو الذي تولى تزويجي، وحيث أنني لم أعلم ذلك الوقت مسؤولية الزواج، وتزوجت بعقد ومهر قدره ثمانية آلاف ريال، لكنني لم أدفع المهر المعلوم في العقد، وقد زوج ولي أمري شقيقتي لأخي زوجتي، وقد أنجبت زوجتي ما يزيد عن عشرة أبناء، أسأل الآن هل هذا الزواج صحيح، وماذا يجب علي فعله إذا كان غير صحيح، هل أجدد عقد الزواج؟ أرشدوني جزاكم الله خيرًا.","title":"عقد زواج فيه نظر يرجع فيه للمحكمة","answer":"الجواب:  هذا العقد فيه نظر والذي نرى أن تراجع المحكمة، لأنه قد يكون من عقد الشغار، قد يكون فيه تشارط، والشغار لا يجوز وهو نكاح البدل، فعليك أن تراجع أنت ووالدك وزوج أختك، عليكم أن تراجعوا المحكمة، وهي تفيدكم -إن شاء الله- في بلدكم، حتى تعرف الحقيقة المحكمة، وتعرف هل شروط الشغار موجودة فيه أم لا، وفيما تراه المحكمة إن شاء الله الكفاية، فعليكما أنت ووالدك أو وليك إن كان غير الوالد عليكما أن تراجعا المحكمة مع زوج أختك، حتى تنظر المحكمة في الزواج الذي أشرت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9179/عقد-زواج-فيه-نظر-يرجع-فيه-للمحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11003,"question":"من الطائف رسالة بعث بها المستمع (ح. هـ. م. الحارثي) يقول: أبعث إليكم بسؤالي هذا وهو أنني قد تزوجت، ولم أبلغ سن الرشد، وإن ولي أمري هو الذي تولى تزويجي، وحيث أنني لم أعلم ذلك الوقت مسؤولية الزواج، وتزوجت بعقد ومهر قدره ثمانية آلاف ريال، لكنني لم أدفع المهر المعلوم في العقد، وقد زوج ولي أمري شقيقتي لأخي زوجتي، وقد أنجبت زوجتي ما يزيد عن عشرة أبناء، أسأل الآن هل هذا الزواج صحيح، وماذا يجب علي فعله إذا كان غير صحيح، هل أجدد عقد الزواج؟ أرشدوني جزاكم الله خيرًا.","title":"عقد زواج فيه نظر يرجع فيه للمحكمة","answer":"الجواب:  هذا العقد فيه نظر والذي نرى أن تراجع المحكمة، لأنه قد يكون من عقد الشغار، قد يكون فيه تشارط، والشغار لا يجوز وهو نكاح البدل، فعليك أن تراجع أنت ووالدك وزوج أختك، عليكم أن تراجعوا المحكمة، وهي تفيدكم -إن شاء الله- في بلدكم، حتى تعرف الحقيقة المحكمة، وتعرف هل شروط الشغار موجودة فيه أم لا، وفيما تراه المحكمة إن شاء الله الكفاية، فعليكما أنت ووالدك أو وليك إن كان غير الوالد عليكما أن تراجعا المحكمة مع زوج أختك، حتى تنظر المحكمة في الزواج الذي أشرت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9179/عقد-زواج-فيه-نظر-يرجع-فيه-للمحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11257,"question":"من جدة رسالة بعثت بها إحدى الأخوات المستمعات تقول: أم ياسر مصرية أختنا لها قضية تقول فيها: كانت والدتي لا تصلي، ثم إنا علمناها الصلاة والحمد لله، واستجابت وداومت على الصلاة بفضل من الله، ثم إنها أيضًا تخلصت من المعتقدات الشركية مثل الاعتقاد بنفع الموتى وما أشبه ذلك، إلا أن لنا والدًا لا يصلي، ولا زالت ترتبط به نفسيًا ومعنويًا، فما هو رأي سماحتكم في هذا الموضوع جزاكم الله خيرًا؟","title":"حكم تمكين المرأة نفسها من زوج لا يصلي","answer":"الجواب:  الحمد لله على هدايتها، ولكن ليس لها أن تمكن زوجها الذي لا يصلي من نفسها؛ لأن ترك الصلاة كفر أكبر، فعليها أن تبتعد عنه وأن تخبره بأنها لا تحل له، وأخبروه أنتم أيضًا حتى يتوب، فإذا تاب وصلى فهي زوجته، وإن استمر في ترك الصلاة فهي تحرم عليه، ونسأل الله لنا وله الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن وإليكم.","link":"https://binbaz.org.sa/fatwas/9439/حكم-تمكين-المراة-نفسها-من-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37412.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":11271,"question":"بعد هذا رسالة بعث بها المستمع (ع. ف) من جدة يسأل فيها جمعًا من الأسئلة فيقول: ما حكم تزويج من لا يصلي وإن ادعى ذلك؟","title":"لا يجوز تزويج المسلمة بمن لا يصلي","answer":"الجواب:  من لا يصلي لا يجوز تزويجه بالمصليات؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9464/لا-يجوز-تزويج-المسلمة-بمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37515.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11530,"question":"يقول: ما حكم الزوجة التي لا تصلي؟ علمًا بأني بينت لها عقوبة تارك الصلاة، فأحيانًا تصلي وأحيانًا تترك، فمثلًا تصلي الظهر، وتترك بقية الفروض، جزاكم الله خيرًا.","title":"حكم الزوجة التي لا تصلي وأثر ذلك على العقد","answer":"الجواب:  حكمها أنها كافرة، ولا يجوز بقاؤها في عصمته، يجب إبعادها إلا أن تتوب توبة صادقة، وإلا فالواجب إبعادها؛ لأن ترك الصلاة كفر أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. هذا هو الصواب من قولي العلماء: أن تركها كفر أكبر، فالواجب عليك إبعادها، وعدم بقائها عندك، بل ترسلها إلى أهلها، نعم، لعدم صلاحها لكفرها، نسأل الله العافية. المقدم: نسأل الله السلامة والعافية، سماحة الشيخ! كثير من إخواننا الذين يستمعون إلى مثل هذه الفتوى يتصلون ويسألون: هل يجب علينا أن نعيد كتابة العقد -وهم كثرة- ويرجون من سماحتكم أن يكون هناك فتوى تعم أرجاء العالم الإسلامي؛ حتى يفطنوا لهذا الأمر؟  الشيخ: نعم، إذا تزوج امرأة لا تصلي وهو يصلي؛ فالعقد غير صحيح، أو تزوج وهو يصلي، وهي لا تصلي فالعقد غير صحيح، لابد أن يكونا جميعًا مسلمين، فإن كانت لا تصلي، وهو يصلي؛ فليس بصحيح، أو العكس، لابد أن يكونا مصليين، أو غير مصليين جميعًا، يصح العقد إذا كانا غير مصليين، كافرين جميعًا، أو كانا مصليين جميعًا. أما إذا كان الزوج لا يصلي، وهي تصلي؛ فلا يصح أو العكس، هي لا تصلي، وهو يصلي، فالواجب تجديد العقد، إذا كان لهما الرغبة في بعضهما، يكون كل واحد يرغب الآخر، يعني: إذا كان يرغب فيها، وهي ترغب فيه يجدد العقد بحضرة شاهدين، والولي الشرعي، يقول: قد زوجتك وهو يقول: قبلت، بمهر جديد، ولو قليلًا، بمهر جديد، لابد من تجديد العقد على الصحيح، ولو كان التارك لها لا يجحد وجوبها، الصحيح: أن تركها كفر مستقل، نعوذ بالله، نعم. المقدم: جزاكم الله خيرًا، هل يعد سماحتكم المسلمين بإصدار فتوى حول هذا الموضوع؟ الشيخ: قد صدر في هذا كتابات كثيرة، نعيد نشرها، إن شاء الله. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9715/حكم-الزوجة-التي-لا-تصلي-واثر-ذلك-على-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38511.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11546,"question":"من السودان أحد الإخوة المستمعين رمز إلى اسمه بالحروف: (ب. ش. ب) يقول: تزوجت ابنة عمي بالرغم عني، واكتشفت أنها لا تصلي، وأمرتها بالصلاة لكنها لم تستمع، ولم تسمع إذا طلقتها فسيغضب والدي مني، كيف يكون التصرف مع مثل هذه؟ جزاكم الله خيرًا.","title":"حكم التزوج بامرأة لا تصلي","answer":"الجواب:  إذا تزوج المسلم امرأة لا تصلي، فإن النكاح غير صحيح في أصح قولي العلماء؛ لأن ترك الصلاة كفر، وإن لم يجحد وجوبها التارك، هذا هو الصواب. وذهب جمع من أهل العلم إلى أن تارك الصلاة لا يكفر إذا كان لم يجحد وجوبها، ولكنه أتى منكرًا عظيمًا ومعصية عظيمة وكبيرة شنعاء أعظم من الزنا، وأعظم من العقوق، وأعظم من السرقة، وأعظم من شرب الخمر، لكنه لا يكفر عند جمع من أهل العلم إذا كان لم يجحد وجوبها. لكن الصواب والراجح هو أنه يكفر بذلك، وإن لم يجحد وجوبها، ويكون النكاح غير صحيح إذا كان الزوج يصلي وهي لا تصلي، يكون النكاح غير صحيح، وهكذا العكس لو كانت تصلي هي، وهو لا يصلي كذلك، ما يصح عقدة النكاح، لقول النبي ﷺ في الحديث الصحيح: رأس الأمر الإسلام، وعموده الصلاة إذا ترك العمود؛ سقط الفسطاط، والمعنى: سقط الإسلام. ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولم يقل: إذا جحد وجوبها أطلق -عليه الصلاة والسلام-وهذا الحديث صحيح رواه الإمام أحمد ، وأهل السنن بإسناد صحيح عن بريدة . وفي صحيح مسلم، عن جابر بن عبدالله -رضي الله عنهما- عن النبي ﷺ أنه قال: بين الرجل، وبين الكفر والشرك ترك الصلاة وهذا الحكم يعم الرجال والنساء؛ لأن القاعدة الشرعية: أن ما ثبت في حق الرجال؛ يثبت في حق النساء، وهكذا العكس إلا بدليل يخص أحدهما، وليس هنا دليل يخص الكفر بالرجل، بل من كفر مطلقًا من الرجال والنساء.  فعليك أيها السائل أن تفارقها، وأن تردها إلى أهلها، ولو لم يرض أبوك؛ لأن المعاصي ليس للإنسان فيها طاعة، الطاعة لله، يقول النبي ﷺ: إنما الطاعة في المعروف ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق فعليك أن تردها إلى أهلها، وأن تعطيها طلقة صكًا بطلقة؛ خروجًا من الخلاف، وحتى يعتمد على الصك في تزويجها لغيرك، ومتى هداها الله، وأردت الرجوع إليها بعد ذلك بعقد جديد؛ فلا بأس، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9729/حكم-التزوج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29602.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":11762,"question":"يقول: ماذا أفعل مع زوجتي إذ أني نصحتها بأن تصلي، ولكن لم تسمع كلامي، ولم تستمع إلى نصيحتي، حتى إني ألاحظها في كثير من الأوقات لا تصلي أبدًا، بينما تقول: إنها تصلي، ما هو توجيهكم يحفظكم الله؟","title":"كيفية معاملة الزوج زوجته التي لا تصلي","answer":"الجواب:  إذا تيقنت أنها لا تصلي؛ فطلقها، وأبعدها، لا خير فيها؛ لأن ترك الصلاة كفر أكبر، فإذا علمت أنها لا تصلي، ولم تسمع منك؛ فأبعدها بالطلاق، وأبشر بأن الله سيعوضك خيرًا منها، فلا تتساهل معها أبدًا.  الواجب نصيحتها، وتأديبها على ذلك، فإن لم ينفعها ذلك، وأصرت على ترك الصلاة، فالواجب عليك فراقها، وسوف يعوضك الله خيرًا منها، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9946/كيفية-معاملة-الزوج-زوجته-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39408.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11777,"question":"من القصيم بريدة رسالة بعث بها مستمع يقول (س. ع. م) يقول: لي زوجة لا تصلي، وقد أمرتها عدة مرات بالصلاة، ولكن أيضًا هي لا تصلي، وبعض الأحيان تقول: إنها تصلي، لكن أنا لم أرها فما هو توجيه سماحتكم؟ يحفظكم الله.","title":"حكم بقاء الرجل مع زوجة لا تصلي","answer":"الجواب:  إذا كنت تعلم أنها لا تصلي، فالواجب فراقها؛ لأن ترك الصلاة كفر أكبر على الصحيح، وإن لم يجحد وجوبها، فهذه لا خير فيها، إذا كنت تعلم أنها لا تصلي؛ فأبعدها، وطلقها، وأبشر بالخير، سوف يعوضك الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، لكن قبل هذا تنصحها، وتأمرها بالتوبة؛ لعلها تتوب، ويهديها الله بأسبابك، فيكون لك مثل أجرها، فإن أبت، أو رأيت منها الكذب؛ فأبعدها، وفارقها، وطلقها، وأبشر بالخير، نعم.","link":"https://binbaz.org.sa/fatwas/9962/حكم-بقاء-الرجل-مع-زوجة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39424.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11846,"question":"إحدى الأخوات تقول المرسلة ع أم نشرا، أم نشرا تقول: إن زواجها كان بدلًا، وإني قد سمعت أنه حرام، وغير جائز، وقد أنجبت تسعة أولاد من ذلكم الزوج، وقد قمت بتربيتهم جميعهم بدون أن ينفق عليهم أحد غيري، هل يجوز أن أطلب طلاقي من ذلكم الزوج؟","title":"صفة زواج الشغار وكيفية تصحيحه لمن وقع فيه","answer":"الجواب:  إذا كان الزواج بدلاً يعني: هو نكاح الشغار، بأن تزوجتيه على أن يزوج أخاك أو أباك ابنته أو أخته، هذا نكاح الشغار، كل واحد يقول: زوجني على أن أزوجك، هذا يقول: زوجني بنتك على أن أزوجك بنتي، أو يقول: أختي أو أختي أو .. أختك يعني: بدل، كل واحد يشترط بنته، أو أخته أو بنت أخيه على الآخر، هذا لا يجوز، نكاح غير صحيح، ومتى علمتم الحكم الشرعي جددوا النكاح، ولو بعد سنوات يجدد النكاح بدون شرط المرأة الأخرى، كل واحد يجدد النكاح والأولاد أولادكم لأجل الشبهة ولاحقون بكم .... ولا حرج. وإنفاقك على أولادك، جزاك الله خيرًا إذا أنفقتي عليها من دون حاجة إلى مطالبته، هذا إليك، هذا معروف منك، وإلا فالنفقة عليه إذا كان قادرًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10035/صفة-زواج-الشغار-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39615.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":12470,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول: أبو تركي يسأل ويقول: تزوجت ابنة عمي، وابن عمي تزوج أختي بدون أن يدفع أيًا منا مهرًا سوى بعض نفقات الزواج، فهل ما فعلناه جائز؟","title":"صفة نكاح الشغار وحكمه","answer":"الجواب:  هذا فيه تفصيل: إن كان هذا العقد عن مشارطة، هذا يقال له: نكاح الشغار، ولا يجوز، والعقد باطل، يجب تجديده إذا كان مشرطًا بينكم، زوجني وأزوجك، أما إذا خطب منكم، وخطبتم منه، ورضيت كل واحدة بالمهر الذي تعطاه من حلي، ونقود؛ فلا بأس، ولا حرج في ذلك، يعني: يكفي ولو قليلًا من المال إذا تراضوا عليه، أما إذا كان مشارطة زوجني وأزوجك؛ فهذا نكاح الشغار الذي نهى عنه النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10671/صفة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40412.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":12605,"question":"الأمر سماحة الشيخ الذي ترونه مانعًا؛ لأن يقع العقد بين المتخاطبين.","title":"الحال التي يبطل فيها النكاح","answer":"الجواب:  مثلما تقدم.  المقدم: وهو؟  الشيخ: اختلاف الدين.  المقدم: اختلاف الدين هذا أهم شيء؟ الشيخ: إذا اختلف الدين؛ بطل النكاح، إلا في مسألة واحدة وهي نكاح المسلم للكتابية المحصنة خاصة. نعم. المقدم: جزاكم الله خيرًا، واختلاف الدين في مثل ترك الصلاة مثلًا؟  الشيخ: نعم، ترك الصلاة يوجب الكفر، يكون الدين مختلف، أما المعصية فلا توجب بطلان النكاح، ما دام مسلمًا، هو مسلم وهي مسلمة. نعم. المقدم: نعم، وغير ذلك لو تكرمتم؟ الشيخ: نعم.  المقدم: غير ذلك هل هناك شيء آخر؟ الشيخ: ما فيه إلا هذا، ليس فيه إلا هذا، المعاصي لا تبطل النكاح، وإنما يبطله الكفر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10815/الحال-التي-يبطل-فيها-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41403.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة","مبطلات النكاح"]},{"id":12620,"question":"الأمر سماحة الشيخ الذي ترونه مانعًا؛ لأن يقع العقد بين المتخاطبين.","title":"الحال التي يبطل فيها النكاح","answer":"الجواب:  مثلما تقدم.  المقدم: وهو؟  الشيخ: اختلاف الدين.  المقدم: اختلاف الدين هذا أهم شيء؟ الشيخ: إذا اختلف الدين؛ بطل النكاح، إلا في مسألة واحدة وهي نكاح المسلم للكتابية المحصنة خاصة. نعم. المقدم: جزاكم الله خيرًا، واختلاف الدين في مثل ترك الصلاة مثلًا؟  الشيخ: نعم، ترك الصلاة يوجب الكفر، يكون الدين مختلف، أما المعصية فلا توجب بطلان النكاح، ما دام مسلمًا، هو مسلم وهي مسلمة. نعم. المقدم: نعم، وغير ذلك لو تكرمتم؟ الشيخ: نعم.  المقدم: غير ذلك هل هناك شيء آخر؟ الشيخ: ما فيه إلا هذا، ليس فيه إلا هذا، المعاصي لا تبطل النكاح، وإنما يبطله الكفر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10815/الحال-التي-يبطل-فيها-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41403.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة","مبطلات النكاح"]},{"id":13226,"question":"ننتقل بعد ذلك إلى رسالة بعثت بها أختكم في الله فتاة الإسلام من اليمن، تقول: سماحة الشيخ! إذا كان الزوج لا يحافظ على الصلاة، فيصلي أيامًا، ويدعها أخرى، وكذلك الصيام، هو رجل طيب القلب، ولا يمنع زوجته عن مجالس العلم، وحرية الالتزام، فما حكم الزواج في مثل هذه الحالة، هل أستمر معه، أم لا، علمًا بأن لي منه ابن وبنت، وهو ابن عمي، وهل الامتناع في الفراش عنه يعتبر معصية، أفتونا مأجورين؟","title":"حكم بقاء الزوجة مع زوج متهاون بالصلاة","answer":"الجواب:  إذا كان الرجل لا يصلي بعض الأوقات لا يجوز البقاء معه؛ لأن ترك الصلاة كفر، فإذا كان زوجك لا يصلي بعض الأوقات؛ فالواجب عليك البعد عنه، والذهاب إلى أهلك، والامتناع منه حتى يتوب إلى الله ويصلي، هذا هو الصواب من قولي العلماء. والقول الثاني: أنه لا يكفر بذلك، أنه كفر دون كفر، وأنه عاصٍ، معصية عظيمة، ولكن لا يكفر بذلك إلا إذا جحد الوجوب، وهذا قول ضعيف ومرجوح.  والصواب: أنه متى تركها عمدًا؛ كفر بذلك؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وكل امرأة زوجها يترك الصلاة يجب عليها أن تفارقه، وأن تمنعه من نفسها حتى يتوب إلى الله، وإلا فعليها أن تفارقه إلى أهلها، وأن تطلب فسخ الطلاق من جهة المحكمة، ولا يجوز لها البقاء معه؛ لأنه بترك الصلاة؛ صار كافرًا في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر نسأل الله العافية، ولو ما جحد وجوبها، لكن متى جحد وجوبها، قال: ما هي بواجبة؛ كفر عند الجميع -نعوذ بالله- ولو صلى، نسأل الله العافية. المقدم: نسأل الله العافية، بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11510/حكم-بقاء-الزوجة-مع-زوج-متهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52013.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":13646,"question":"هذا السائل من السودان رمز لاسمه بـ (أ. ع. ح) يقول: أجبرني والدي على الزواج من قريبة لي، ولكنني لا أحبها، وهي لا تصلي، ولي منها ثلاثة أولاد، وهي تكره أمي، ماذا أفعل معها مأجورين؟","title":"ماذا يفعل من تزوج امرأة لا تصلي؟","answer":"الجواب: إذا كانت لا تصلي، وأنت تصلي فالنكاح غير صحيح، الذي ما يصلي كافر، إذا كنت أنت تصلي والحمد لله، وهي لا تصلي؛ فالنكاح غير صحيح، وأبعدها إلى أهلها، وسوف يرزقك الله خيرًا منها، من ترك شيئًا لله؛ عوضه الله خيرًا منه يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأبعدها، والتمس غيرها من المصليات، وأبشر بالخير، وأولادك تابعون لك لأجل الشبهة، أولادك منها أولاد لك، وتابعون لك، ونسبهم صحيح، ولكن فارقها، أعطها وثيقة بطلقة واحدة، واسأل ربك أن يبدلك خيرًا منها، وسل الله لها الهداية. نعم. المقدم: وإن رجعت إلى الصلاة سماحة الشيخ؟ الجواب: وإن تابت فلك أن تبقيها تجدد العقد، إذا تابت؛ فلا بأس أن تجدد العقد إن رغبت فيها، يكون بعقد جديد، ومهر جديد إذا تابت. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11979/ماذا-يفعل-من-تزوج-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52817.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14094,"question":"رسالة وصلت إلى البرنامج من الرياض وباعثها المستمع (م. عبد الله)، أخونا يقول: إنني تزوجت امرأة، وقد رزقني الله منها بولد، وأنا أفكر في طلاقها من ثاني أيام العرس، سبب ذلك أنني لم أحضر لخطبتها، والسبب الثاني: أنها كانت لا تصلي قبل الزواج، وبعد الزواج أمرتها تصلي فصلت، وعندما سافرت للعمل؛ قطعت الصلاة. سؤالي: هل إذا طلقتها أكون آثم؟ وهل إذا صبرت عليها أكون مأجور؟ وهل هذا ابتلاء من الله  لعباده بهذا النوع من النساء؟ نرجو أن تفيدونا حول هذه القضايا. جزاكم الله خيرًا.","title":"حكم طلاق الرجل للمرأة التي لا تصلي","answer":"الجواب: إذا كانت لا تصلي؛ فالنكاح غير صحيح، مادمت تصلي والحمد لله أنت، فهي لتركها الصلاة تعتبر كافرة في أصح قولي العلماء، ولو كانت تقر بالوجوب.\nفالواجب تجديد العقد إذا تابت إلى الله وأنابت إليه توبة صادقة، وأنت ترغب فيها، يجدد العقد، أما الآن فالواجب عليك فراقها، ما دامت تصلي إذا حضرت وتترك الصلاة إذا غبت؛ فهذه لا خير فيها، هذه فاسدة، عقيدتها فاسدة، وخوفها من الله معدوم أو ضعيف، تراعيك ولا تراعي حق الله! فهذه ينبغي فراقها وإبعادها، وأنت مأجور، بل واجب عليك طلاقها وإبعادها؛ لفساد دينها، بسبب تضييعها الصلاة. وقد ذهب جمع من أهل العلم من أئمة الحديث وغيرهم من المحققين إلى كفر تارك الصلاة كفرًا أكبر، ولو أقر بوجوبها، مع أن إقراره بوجوبها في الغالب لا يكون صحيحًا بل مجاملة، لو كان يقر بوجوبها إقرارًا صحيحًا لما تركها؛ لأن إقراره بالوجوب يدفعه إلى أن يصلي، ولكن عدم إقراره بالوجوب أو ضعف عقيدته في ذلك جرأته على تركها -نسأل الله العافية- وهكذا المرأة.\nفالواجب عليك وعلى أمثالك تطليق المرأة التي لا تصلي وإبعادها، ومتى تابت توبة صادقة وشهد لها بالخير؛ أمكنك أن تزوجها من جديد بعقد جديد، وهكذا المرأة التي عند زوج لا يصلي؛ تبتعد عنه، وتذهب إلى أهلها، ولا تبقى معه؛ لأنه متى ترك الصلاة كفر، وهذه مصيبة عظيمة اليوم وقعت في الناس.\nفالواجب على الرجل أن يبعد المرأة التي لا تصلي، وعلى المرأة أن تبتعد عن الرجل الذي لا يصلي، وأن تذهب إلى أهلها، حتى ولو كان معها أولاد، رزقهم على الله، وهي أحق بأولادها من هذا الزوج الذي لا يصلي، وعلى القاضي أن يجعل أولادها عندها، ويلزمه بنفقتهم، حتى يتوب إلى الله ويرجع إلى الله، ثم بعد ذلك يجدد العقد، إذا كان بعد خروجها من العدة، وإن كان تاب في العدة؛ فهي زوجته إذا كان حين الزواج يصلي وهي تصلي، أما البقاء مع زوج لا يصلي أو مع زوجة لا تصلي؛ فهذا لا يجوز، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12523/حكم-طلاق-الرجل-للمراة-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61002.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","نصائح وتوجيهات"]},{"id":14198,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. ح. ع. العتيبي) أخونا يقول في رسالته: أرجو إفادتي في هذه القضية: لي أخت ليست متزوجة والآن استحقت الزواج تقدم لخطبتها أحد الأشخاص وقال لوالدي: زوجني ابنتك وأزوجك ابنتي، والمعنى على ما يدل بالبدل وقرر والدي بزواجها بدلًا، وكما سمعنا بأن البدل حرام ولذلك اعترضته - أنا أخوها - اعترضت على والدي حتى لا يتم هذا الزواج لكن في نفسي شيء هل أكون آثمًا عندما أعترض على الوالد في مثل هذه الأشياء؟","title":"حكم الاعتراض على الوالد في نكاح الشغار","answer":"الجواب: قد أحسنت فيما فعلت، ولكن يكون ذلك بالأسلوب الحسن والنصيحة؛ لأن الوالد حقه عظيم، فيكون الاعتراض عليه بالأسلوب الحسن والنصيحة والتوجيه وإرشاده إلى سؤال أهل العلم حتى يعلم الحكم الشرعي. وهذا النكاح الذي ذكرت يسمى: نكاح الشغار، ويسميه بعض الناس الآن: البدل؛ وهو: أن يزوج الرجل ابنته أو أخته أو غيرهما من مولياته كبنت أخيه ونحو ذلك على آخر بشرط أن يزوجه الآخر ابنته أو أخته أو غيرهما أو يزوج ابنه، هذا لا يجوز، سواء سمي مهرًا أم لم يسم مهرًا؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه نهى عن الشغار في عدة أحاديث عنه عليه الصلاة والسلام من حديث ابن عمر وحديث جابر وحديث أبي هريرة وغيرهم، وقال عليه الصلاة والسلام: لا شغار في الإسلام، وقال: الشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي أو زوجني أختك وأزوجك أختي. وثبت في مسند أحمد وسنن أبي داود عن معاوية  أنه كتب إلى أمير المدينة في شخصين تزوجا بالشغار وبينهما مهر فأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي عليه الصلاة والسلام. وقد ذهب بعض أهل العلم إلى أنه إذا كان هناك مهر كالمعتاد فليس بشغار، ولكنه قول مرجوح وضعيف، والصواب أنه شغار مطلقًا سواء كان فيه مهر أم لم يكن فيه مهر، إذا كان كل واحد شرط على الآخر التزويج؛ زوجني وأزوجك، أو لا أزوجك حتى تزوجني.. أو ما أشبهه من العبارات الدالة على أنه شرط. أما إذا خطب بنت ووافق ثم خطب الآخر ووافق من دون مشارطة فلا حرج في ذلك، الممنوع المشارطة وأن هذا لا يزوج هذا إلا بشرط تزويجه موليته، وهذا فيه فساد كبير؛ من ذلك أنه جعل بضع هذه مهرًا لهذه هذا هو المعنى في الحقيقة، ومن ذلك أنه يفضي إلى إجبار النساء وظلمهن من أجل مصلحة الولي، ومن ذلك أنه يفضي إلى خصومات كثيرة ونزاع كلما حصل بين هذه وزوجها شيء حصل بين الأخرى وزوجها شيء، وهذا يفضي إلى مفاسد لا تنتهي، ومن حكمة الله  ومن إحسانه إلى عباده ومن رحمته لهم أن حرم هذا العقد. فالواجب على أهل العلم وعلى كل مسلم أن يحذروا الناس من هذا العقد، وأن يمتثلوا أمر الرسول عليه الصلاة والسلام في ذلك، وفيما أحل الله غنية وكفاية عما حرم الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12651/حكم-الاعتراض-على-الوالد-في-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61602.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":14286,"question":"رسالة وصلت إلى البرنامج من حائل، باعثها المستمع: (م. م. ع. ع) أخونا يسأل عن الشغار سماحة الشيخ، ولعله لا يستطيع التفريق بين الشغار وما هو غير شغار في الزواج، ويرجو من سماحتكم التوجيه، إذ يسأل ويقول: هل يجوز أن يزوج أبي ولد عمي، وعمي يزوجني ابنته؟ علمًا؛ بأن الجميع موافقون على هذا الزواج، ولقصد القرابة والمودة بين الأخوين، وهل يدخل هذا الزواج في حكم الشغار؟ ما هو رأيكم هل أتمم هذا الزواج أو لا؟ جزاكم الله خيرًا.","title":"صورة نكاح الشغار وحكمه","answer":"الجواب: الشغار لقد ثبت عن النبي ﷺ في الأحاديث الصحيحة النهي عنه قال: والشغار أن يقول الرجل للرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار أن يقول كل واحد للآخر: زوجني، وأزوجك، هذا يقول: زوجني ابنتك أو أختك، وأنا أزوجك بنتي أو أختي على سبيل المشارطة، هذا هو الشغار. أما إذا خطب أبوك بنت عمك لك، وخطب عمك بنت أبيك وهي أختك لولده أو لابن أخيه فكل هذا لا بأس به إذا لم يكن على سبيل المشارطة والإلزام.\nأما إذا كان على سبيل المشارطة: لا أزوج حتى تزوج، يعني كل واحد يقول: لا أزوجك حتى تزوجني أو تزوج ولدي، هذا هو الشغار المنهي عنه؛ لأنه جعل كل واحدة مهرًا للأخرى، فهو عقد بعقد فلا يجوز ذلك، ولأنه وسيلة إلى ظلم النساء وإكراههن على الزواج بمن لا يرضين، ولأنه وسيلة أيضًا للخصومات والنزاع الكثير، كلما حصل شيء بين الزوج وزوجته تأست بها الأخرى أو ألزمها وليها بذلك حتى يكون النزاع مستمرًا.\nفالحاصل أن الشغار هو أن يقول كل واحد للآخر: زوجني بنتك أو نحوها من مولياته؛ وأنا أزوجك بنتي أو نحوها من مولياته، مشارطة، على سبيل الشرط والإلزام، أما إذا كان من غير هذا الشرط بل خطب منه وهذا خطب من الآخر وكل وافق من دون مشارطة فلا بأس بذلك ولا حرج.\nالمقدم: بارك الله فيكم، وإن تساوى المهر، وإن تساوت التكاليف؟\nالشيخ: نعم، لا حرج، سواء تساوت أو اختلفت. نعم.\nالمقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12757/صورة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61802.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14487,"question":"الأخت: (أ. ح. ن. ر) من اليمن - إب، بعثت برسالة، وضمنتها هذا السؤال، تقول: إن زوجي لا يغتسل من الحدث الأكبر إلا بعد يوم أو يومين، وأحيانًا يجلس من العصر إلى اليوم الثاني صباحًا، وفي بعض الأوقات يذهب إلى عمله.الشيخ: أعد، نسأل الله العافية، أعد.المقدم: تقول: إن زوجي لا يغتسل من الحدث الأكبر إلا بعد يوم أو يومين، وأحيانًا يجلس من العصر إلى اليوم الثاني صباحًا، وفي بعض الأوقات يذهب إلى عمله ويعود في المساء، ثم يغتسل من الحدث بالرغم من توفر الماء والوقت للاغتسال وهو لا يصلي، وإني دائمًا أنصحه بالصلاة والاغتسال، ولكنه لا يستمع إلى كلامي، وهذا يعذبني كثيرًا، وأنا امرأة مصلية، وأعرف أمور ديني.","title":"حكم البقاء مع زوج لا يصلي ولا يغتسل من الجنابة","answer":"الجواب: هذا الرجل يظهر من حاله أنه ليس بمؤمن، ولا يعرف أحكام الدين، أو يعرفها ويعاندها، فلا يحل لك البقاء معه، هذا الرجل يعتبر كافرًا؛ لأنه ترك الصلاة عمدًا، ولم يبال بها، ولم يبال بغسل الجنابة، فهذا يعتبر كافرًا، وليس للمسلمة أن تبقى مع كافر، والله يقول : لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10] ويقول -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا[البقرة:221] يعني: لا تزوجوهم حتى يؤمنوا، وترك الصلاة كفر أكبر في أصح قولي العلماء، وإن لم يجحد وجوبها، فإن جحد وجوبها صار كافرًا عند جميع العلماء. والذي يظهر من حال زوجك أنه مع تركه لها لا يؤمن بها، لو كان يؤمن بها لما فعل هذا الفعل القبيح؛ لأن الإيمان يدعوه إلى أن يحترم الصلاة، وأن يبادر إليها، وأن يغتسل من الجنابة، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة .\nوقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في الصحيح من حديث جابر ، ولم يقل: إذا جحد وجوبها، أطلق، فدل ذلك على أنه يكفر، وإن لم يجحد الوجوب؛ ولما سئل ﷺ عن الأئمة الذين يتخلفون عن الدين، ويظلمون الناس، سألوه: هل يخرجون عليهم؟ قال: لا، إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فإنه أخبرهم ﷺ: أنه يأتي في آخر الزمان أمراء جورة يعرف منهم وينكر -من أعمالهم- فسألوه: هل يخرجون عليهم؟ هل يقاتلونهم؟ فقال: لا، ما أقاموا فيكم الصلاة، ما صلوا وفي اللفظ الآخر: إلا أن تروا كفرًا بواحًا، عندكم من الله فيه برهان فهذا يدل على أن من ترك الصلاة ولم يقمها فقد أتى كفرًا بواحًا، يستحل، يحل معه الخروج عليه من ولاة الأمر أهل الحل والعقد، حتى يزال عن الرئاسة والإمامة ويجعل مكانه من يقوم بالإمامة. فالحاصل: أنّ هذا الرجل الذي ذكرت صفاته كافر إذا صح ما قلت عنه، وليس لك البقاء معه، بل يجب أن تخرجي إلى أهلك، أو تبقي مع أولادك إن كان عندك أولاد، وتمتنعين منه، وترفعين أمره إلى الحاكم الشرعي، حتى يفرق بينك وبينه، وحتى يقام عليه حد الله. نسأل الله له الهداية، نسأل الله أن يرده إلى الهدى، نعم. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12971/حكم-البقاء-مع-زوج-لا-يصلي-ولا-يغتسل-من-الجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63207.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح","قضايا المرأة"]},{"id":14639,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول السائلة (م. ر. ع) أختنا تقول في رسالتها: إنها فتاة في مقتبل العمر، زوجني أبي بشخص لا يعرف عنه شيئًا، سوى أنه من نفس العائلة، وبعد الزواج بدت منه أفعال مشينة، لا يرضاها الله ورسوله ﷺ، فهو تارك للصلاة، سيئ العشرة، وما خفي كان أعظم، وأنا الآن أطلب التفريق، وخاصة أنه يطلب مني ترك الصلاة، الأمر الذي وقف في وجهي أنه يطلب أن أدفع له المهر أضعافًا مضاعفة. وجهوني حول هذا الموضوع، جزاكم الله خيرًا.","title":"حكم البقاء مع زوج لا يصلي ويأمر بترك الصلاة","answer":"الجواب: لقد أساء والدك -عفا الله عنا وعنه- في تزويجك على شخص لا يعرف حاله الدينية، فهذا غلط من والدك، والواجب على كل والد، وعلى كل ولي أن ينظر لموليته، وألا يزوجها إلا ممن يعرف عنه الدين والصلاح والخير، وألا يتساهل في هذا الأمر، لا لقريب ولا لغير قريب؛ لأنها أمانة في ذمة الولي.  فالواجب أن يختار لها من يعرف عنه الصلاح والخير، وحسن السمعة، والمحافظة على الصلاة في الجماعة. وإذا فرط في هذا أساء وأثم، وللمولية الخيار في ذلك، فإذا رأت ما يسوؤها من المعاصي فلها أن تطلب الفسخ، تطلب الطلاق، وإذا رأت منه ما يوجب الكفر وجب عليها ذلك كترك الصلاة؛ لأن ترك الصلاة كفر، فالذي يترك الصلاة، ويأمر بترك الصلاة من أكفر الناس نعوذ بالله، ولو قال: إنه يعلم وجوبها، ويقر بوجوبها، ما دام يتركها وعلاوة على ذلك يأمر بتركها، فهذا شره عظيم، وقد قال النبي الكريم -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة. فالواجب عليك الذهاب إلى أهلك، وعدم تمكينه من نفسك، حتى يتوب إلى الله ، ويحافظ على الصلاة كما أمر الله، ثم بعد ذلك يجدد النكاح له، بزواج شرعي إذا رضيت بذلك، وثبتت التوبة يجدد النكاح؛ لأن نكاح المسلمة التي تصلي من زوج لا يصلي لا يجوز، ولا يصح، فالنكاح غير صحيح، إذا كان لا يصلي حين النكاح، وأنت -بحمد الله- تصلين، فالنكاح غير صحيح. وليس له حق في المال في المهر؛ لأن الفراق من جهته هو الذي سبب الفرقة بتركه الصلاة، والنكاح فاسد، والمهر لك بما استحل من فرجك، قد استحل من فرجك بهذا النكاح الفاسد، ما حرم الله، فيكون لك المهر، وعلى والدك السعي لدى المحكمة بالتفريق بينك وبينه على الوجه الشرعي الذي شرعه الله لعباده، وبما تراه المحكمة الكفاية -إن شاء الله-، نعم.\nالمقدم: جزاكم الله خيرًا في آخر رسالتها سماحة الشيخ، تنوه إلى أن الوالد غير مستعجل في هذا الموضوع، فهو لا يسعى إلى التفريق؟ الشيخ: الوالد عليه أن يتقي الله، وأن يتلافى ما فعل من الشر، وأن يتوب إلى الله من عمله السيئ، وعليه أن يسعى في خلاصك كما فعل ما سبب وقوع ما وقع من هذا النكاح الفاسد، الواجب عليه أن يتقي الله، وأن يراقب الله، وأن يتصل بالمحكمة حتى تفرق بينك وبينه، إلا إذا تيسر أنه يفارق بدون المحكمة، ولو أعطاه والدك بعض الشيء من باب إنهاء النزاع بسرعة فلا بأس، إذا أعطاه بعض الشيء معروفًا منه، ليخلصك بسرعة، فلا بأس بذلك، وإلا فلا حق له عليك؛ لأنه كافر بتركه الصلاة؛ ولأنه استحل من فرجك ما حرم الله بهذا النكاح الفاسد، فوجب لك المهر، وهذه أمور تعلمها المحاكم الشرعية، وفيها الكفاية، والحمد لله. لكن إذا اصطلحتم معه، أو مع أقاربه على أن تعطوه شيئًا، ويطلق، ولا تذهبوا إلى المحكمة فلا حرج في ذلك. المقدم: جزاكم الله خيرًا شيخ عبدالعزيز طالبها أيضًا بأن تترك الصلاة هي فيما لو أصر على بقائها معه، كيف تتيقن من توبته؟ الشيخ: متى تاب سوف لا يطلبها بترك الصلاة، متى تاب سوف يترك هذا الطلب، فإن طالبها بترك الصلاة فهو غير تائب؛ لأن طلبه ترك الصلاة أعظم وأشنع من تركه الصلاة، نسأل الله العافية، نعم.\nالمقدم: جزاكم الله خيرًا، والطريق إلى معرفة توبته يا شيخ عبدالعزيز هو؟ الشيخ: لا بد من البينة، من العارفين من جيرانه وأقاربه، إذا شهد له عدلان فأكثر بالتوبة، وظهرت ذلك عليه بشهادة جيرانه، ومن حوله من أصدقائه، فإن هذا يثبت به أمر التوبة إذا كان الشاهدان فأكثر عدولًا، نعم. المقدم: جزاكم الله خيرًا. إذًا: لا تعود إليه حتى تتيقن تمامًا بهذا الأسلوب الذي تفضلتم به؟ الجواب: ولا تعود إلا بنكاح شرعي جديد؛ لأن النكاح الأول فاسد، فإذا رضيت بالعود إليه بعد التوبة، فلا بد من تجديد النكاح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13162/حكم-البقاء-مع-زوج-لا-يصلي-ويامر-بترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62712.mp3","categories":["الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":14792,"question":"السائلة: التي رمزت لاسمها بالحائرة (س. ع) من جازان، كتبت في الحقيقة رسالة مطولة مختصرها -يا سماحة الشيخ- تقول: أحيطكم علمًا -يا سماحة الشيخ- بأنني امرأة متزوجة من رجل يسيء في معاملتي، فهو قليل الصلاة، كثير السهر، كثير السب والشتم، يمنعني من زيارة أقاربي، يهددنني إن فعلت ذلك بالطلاق، ومن آخر ما وقع منه بأنه خطب لابنه الأكبر، وبعد عقد قرانه تخلى عنه، ورفض أن يعينه على تكاليف الزواج. فأنا الآن حائرة كما أنه لا يصرف علينا كما يجب، بل يضيع الأموال فيما لا يرضي الله  في السهرات وغيرها.فأنا الآن بين نارين وبناتي أصبحن كبيرات، لا أستطيع تركهن معه، ولا أستطيع الوقوف مع ابني ضده، فلسنا له أندادًا، وجهونا -يا سماحة الشيخ- في ضوء هذه الرسالة؟","title":"حكم البقاء مع زوج تارك للصلاة سيئ الخُلُق","answer":"الجواب: إن كان الرجل لا يصلي، أو يدع الصلاة في بعض الأحيان، فهذا كفر وضلال، الصحيح أن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فالواجب عليك فراقه، والذهاب إلى أهلك، والمطالبة بالطلاق من جهة المحكمة. أما إن كان يصلي، ولكن قد يتأخر عن صلاة في الجماعة، وإلا يصلي في البيت فهو عاصٍ، وقد تشبه بالمنافقين، ولكن لا يكفر بذلك. أما ما كان من جهة النفقة، ومن جهة السب والشتم فهذا عليك نصيحته أنت وأقاربه كإخوانه أو أبيه إن كان له أب أو جد، أو أقارب جيدين، أو جيران صالحين، تقولين لهم، وتستعين بالله، ثم بهم على نصيحته؛ لعل الله يهديه بأسبابكم، وإذا لم يقبل النصيحة ففي إمكانك الرفع إلى المحكمة، أو الذهاب إلى أهلك، وطلب الطلاق؛ لأن هذه الحال لا عيشة معها، حالة سيئة، فإذا لم يستقم على الطريق السوي، فلك أن تعافيه، وتطلبي الطلاق لسوء أخلاقه وسوء أعماله، ولكن إذا تيسر منك ومن أبيه أو جده أو إخوانه أو أعمامه أو جيرانه الطيبين، إذا تيسر نصيحته، لعله يهتدي، لعله يستقيم، لعل أخلاقه تصلح، لعله يترك السهر، إذا تيسر هذا فأبشري بالخير، واحتسبي الأجر.  فإن لم يتيسر هذا، فلك أن تذهبي إلى أهلك، وتطلبي الطلاق؛ لأن هذه أخلاق سيئة، لا يلزمك الصبر عليها، نسأل الله العافية، ونسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13282/حكم-البقاء-مع-زوج-تارك-للصلاة-سيى-الخلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56115.mp3","categories":["الطلاق","حكم الصلاة وأهميتها","الأنكحة المحرمة"]},{"id":14927,"question":"رسالة وصلت إلى البرنامج من المستمع: (ب. م. أ) يقول: هل يجوز الزواج بالتبادل أو في البدلة، بمعنى: رجلان يتبادلان بأخواتهم، أو في بناتهم؟ مع دفع مبلغٍ من المال كمهر، لكل واحدةٍ منهن، ولكن أقل من المهر السائد في المنطقة؟ علمًا أن الزواج بموافقتهن. أفيدونا، أفادكم الله.","title":"هل يجوز الزواج بالتبادل إذا وافقت الزوجتان؟","answer":"الجواب: الزواج بالتبادل لا يجوز، كونه يسمى: نكاح الشغار، وقد نهى عنه النبي ﷺ في أحاديث كثيرة صحيحة، وهو أن يقول: زوجني أختك، وأزوجك أختي، أو بنتك، وأزوجك بنتي، أو ما أشبه ذلك، هذا لا يجوز، ولو بالمهر، ولو تراضى الجميع؛ لأن الرسول نهى عن ذلك -عليه الصلاة والسلام-؛ ولأنه وسيلة إلى إجبار النساء، وظلم النساء؛ ولأنه وسيلة إلى الفتن، والخصومات، إذا تنازع هذا مع زوجته، كذلك الرجل الآخر تنازعه زوجته أو أهلها. فالحاصل: أنه لا يجوز لما يترتب عليه من الشرور، أما إذا خطب هذا، وخطب هذا من دون شرط، هذا خطب من الأسرة، وخطبوا منه، من دون مشارطة؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13423/هل-يجوز-الزواج-بالتبادل-اذا-وافقت-الزوجتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64008.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14991,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد بن علي حمدان تهامي أخونا له جمع من الأسئلة من بينها سؤال يقول:عندي بنت وطلبها مني رجل للزواج بها، فاشترطت عليه أن يزوجني بأخته، فزوجني بها، وزوجته بابنتي، فما حكم ذلك؟","title":"ما حكم من زوج ابنته برجل وشرط أن يزوجه بأخته؟","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذه الصورة التي ذكرها السائل تسمى نكاح الشغار، وقد ثبت عن رسول الله -عليه الصلاة والسلام- في عدة أحاديث النهي عن ذلك، فهو نكاح فاسد مطلقًا، سواء سمي مهرًا أو لم يسم مهرًا، والواجب فسخه، وإذا كان كل واحد يرغب في المرأة فإنه يجدد النكاح، ولا حاجة إلى طلاق، كل واحد يجدد النكاح بمهر وشاهدين وولي، ولا حرج في ذلك مع التوبة والاستغفار عما مضى، والأولاد يلحقون بآبائهم؛ لأن النكاح نكاح شبهة، فأولاده لاحقون به، ولكن عليه أن يجدد النكاح إذا كانت ترغب فيه وهو يرغب فيها، يجدد النكاح بمهر جديد، وشاهدي عدل إذا رضيت المرأة بذلك، وبذلك ينتهي الأشكال، لكن بشرط ألا تشترط المرأة الأخرى، يعني: لا يشترط المرأة الأخرى، يتزوجها من غير اشتراط لتزوج الأخرى، كل واحد يتزوج برضى المرأة من دون اشتراط المرأة الأخرى، ويكون هذا نكاحًا جديدًا بشروطه التامة، برضاها وبالولي، لكن لا يشترط خروجها من العدة، بل يتزوجها في الحال؛ لأن الماء ماؤه، يتزوجها في الحال، ولا حاجة إلى عدة، فإن لم ترده طلقها طلقة واحدة، تكفي طلقة واحدة لإنهاء هذا النكاح الفاسد.  وعلى الجميع التوبة إلى الله سبحانه، على الرجال والنساء والأولياء، عليهم التوبة إلى الله جميعًا؛ لأنهم وقعوا أمر نهى عنه النبي ﷺ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13481/ما-حكم-من-زوج-ابنته-برجل-وشرط-ان-يزوجه-باخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49301.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15026,"question":"أيضًا يقول: هل يجوز أن يجمع شخص بين امرأة وبنت ولد أخيها؟","title":"حكم الجمع بين المرأة وبنت ولد أخيها","answer":"الجواب: ثبت في الصحيحين عن النبي -عليه الصلاة والسلام- أنه: \"نهى أن يجمع الرجل بين المرأة وعمتها، وبين المرأة وخالتها\" وبين أهل العلم أن العمة تكون قريبة، وتكون بعيدة، والخالة كذلك، فليس للرجل أن يجمع بين المرأة وبنت أخيها التي هي عمتها، ولا بنت ابن أخيها، التي هي عمة أبيها، مثل هذا السؤال، فإن عمة الرجل عمة لأولاده وإن نزلوا، وهكذا خالته خالة لأولاده وإن نزلوا.  فليس له أن يجمع بين امرأةٍ وبنت أخيها، ولا بنت بنت أخيها، ولا بنت ابن أخيها، ولا بنت ابن ابن أخيها، وهكذا؛ لأنها عمة الجميع، وهكذا ليس له أن يجمع بين المرأة وبين بنت أختها، ولا بنت بنت أختها، ولا بنت ابن أختها؛ لأنها خالة الجميع وإن نزلوا، نعم.","link":"https://binbaz.org.sa/fatwas/13535/حكم-الجمع-بين-المراة-وبنت-ولد-اخيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65308.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15165,"question":"هذا رسالة وردتنا من عبدالله حسين بن علي من الطائف من الشرقية، شارع عكاظ، يقول فيه: لدي سؤال وهو كما يلي:أفيدكم أنني رضعت على ابنة عمي أكثر من الرضاعة الشرعية بكثير جدًا، فأصبحت أخًا لها بالرضاع، والسؤال هو: هل يجوز لي أن أتزوج من إحدى أخواتها؟ وهل يجوز لأخي أيضًا أن يتزوج من إحدى أخواتها؟ علمًا بأن لأختي هذه -من الرضاعة يعني- أختان في سن الزواج؟أفيدوني، أفادكم الله.","title":"حكم نكاح أخت الأخت من الرضاعة ونكاح الأخ لأحدى أخواتها","answer":"الجواب: إذا كنت رضعت -أيها السائل- من أمها، أو معها من امرأة أخرى رضاعًا كثيرًا خمس مرات فأكثر، فإنها تحرم عليك وحدك، تكون أخًا لها، ولا تحرم على إخوانك؛ لأن إخوتك ما رضعوا من أمها، ولا ارتضعوا من امرأة ارتضعت منها؛ فيكونوا أجانب، ولا حرج عليهم في نكاحها، ونكاح أخواتها. أما أنت فلا، إذا كنت رضعت من أمها، أو من امرأة غير أمها أرضعتكما جميعًا أنت وإياها؛ فإنك تكون أخًا لها إذا كان الرضاع خمس رضعات، وكان في الحولين، كان رضاعك من أمها وأنت في الحولين، وأما إخوتك فلا لا بأس عليهم أن ينكحوها، أو ينكحوا أخواتها. وهكذا أنت إذا كنت رضعت معها من امرأة أخرى؛ فلك أن تنكح أخواتها من شئت من أخواتها، أما إذا كنت رضعت من أمها؛ فإنك تكون أخًا لها ولأخواتها جميعًا من أمها وأبيها، إذا كنت رضعت من أمها من لبن أبيها؛ صارت أخواتها أخوات لك من أبيها وأمها جميعًا دون إخوتك، نعم.","link":"https://binbaz.org.sa/fatwas/13667/حكم-نكاح-اخت-الاخت-من-الرضاعة-ونكاح-الاخ-لاحدى-اخواتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65902.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15172,"question":"هذا رسالة وردتنا من عبدالله حسين بن علي من الطائف من الشرقية، شارع عكاظ، يقول فيه: لدي سؤال وهو كما يلي:أفيدكم أنني رضعت على ابنة عمي أكثر من الرضاعة الشرعية بكثير جدًا، فأصبحت أخًا لها بالرضاع، والسؤال هو: هل يجوز لي أن أتزوج من إحدى أخواتها؟ وهل يجوز لأخي أيضًا أن يتزوج من إحدى أخواتها؟ علمًا بأن لأختي هذه -من الرضاعة يعني- أختان في سن الزواج؟أفيدوني، أفادكم الله.","title":"حكم نكاح أخت الأخت من الرضاعة ونكاح الأخ لأحدى أخواتها","answer":"الجواب: إذا كنت رضعت -أيها السائل- من أمها، أو معها من امرأة أخرى رضاعًا كثيرًا خمس مرات فأكثر، فإنها تحرم عليك وحدك، تكون أخًا لها، ولا تحرم على إخوانك؛ لأن إخوتك ما رضعوا من أمها، ولا ارتضعوا من امرأة ارتضعت منها؛ فيكونوا أجانب، ولا حرج عليهم في نكاحها، ونكاح أخواتها. أما أنت فلا، إذا كنت رضعت من أمها، أو من امرأة غير أمها أرضعتكما جميعًا أنت وإياها؛ فإنك تكون أخًا لها إذا كان الرضاع خمس رضعات، وكان في الحولين، كان رضاعك من أمها وأنت في الحولين، وأما إخوتك فلا لا بأس عليهم أن ينكحوها، أو ينكحوا أخواتها. وهكذا أنت إذا كنت رضعت معها من امرأة أخرى؛ فلك أن تنكح أخواتها من شئت من أخواتها، أما إذا كنت رضعت من أمها؛ فإنك تكون أخًا لها ولأخواتها جميعًا من أمها وأبيها، إذا كنت رضعت من أمها من لبن أبيها؛ صارت أخواتها أخوات لك من أبيها وأمها جميعًا دون إخوتك، نعم.","link":"https://binbaz.org.sa/fatwas/13667/حكم-نكاح-اخت-الاخت-من-الرضاعة-ونكاح-الاخ-لاحدى-اخواتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65902.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15254,"question":"هذه رسالة أخرى من السائلة (ش. ح) من جدة تقول: مشكلتي تتعلق بزوجي، فهو رجل مقصر في دينه، لا يصلي، وحينما أدعوه إلى الصلاة يغضب ويستهزئ بي، ويصر على تركه الصلاة، بحجة أن أباه لم يكن يصلي، فلماذا هو يصلي؟وذات يوم ألحيت عليه في ذلك، فقال لي: إذا استمريت على هذا الوضع، فالباب مفتوح، وعندها طلبت منه الطلاق.ومرة أخرى أيضًا وتقريبًا لنفس السبب قال لي: لا تكلميني إلى يوم القيامة، فما رأيكم في هذا الرجل؟ وفي كلامه الذي قاله في مناسبتين في الأولى قوله: الباب مفتوح، وفي الثانية: لا تكلميني إلى يوم القيامة، هل يعتبر هذا طلاقًا أم ماذا؟ وهل يجوز لي البقاء معه على هذا الحال؟","title":"حكم البقاء مع زوج لا يصلي","answer":"الجواب: هذا الرجل لا يجوز البقاء معه، ما دام يترك الصلاة كما ذكرت، فهو بذلك كافر، وبئس القدوة أبوه، إذا كان أبوه لا يصلي، فبئس القدوة، ولا يجوز أن يقتدى بالكافر الذي لا يصلي، أو يسب الدين، أو يأتي بناقض من نواقض الإسلام، أو بمعصية من معاصي الله، كل هؤلاء لا يقتدى بهم، هذا الرجل كافر اقتدى بكافر على حسب قوله، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. والأصح من أقوال أهل العلم أن من تركها تهاونًا وكسلًا فهو كافر، وإن لم يجحد وجوبها، وإذا كان هذا الرجل يجحد وجوبها صار كافرًا بالإجماع. وبكل حال فهذا الرجل رجل سيئ وكافر بترك الصلاة في أصح أقوال أهل العلم، فلا يجوز لك البقاء معه، بل يجب عليك أن تفارقيه ولا تمكنيه من نفسك. وقولها: الباب مفتوح، هذه كناية إذا أراد بها الطلاق معناها: اخرجي أنت طالق، فهي طلاق، وإذا كان ما أراد الطلاق، فليست بطلاق، لكن بكل حال حتى لو لم يطلق ما ينبغي لك البقاء معه، بل يجب عليك فراقه، وأن تتركيه وتذهبي إلى أهلك وأولادك معك، وليس له حق في الأولاد لكفره، فأنت أولى بأولادك، وهو رجل سيئ قد تعاطى كفرًا بالله ، فعسى الله أن يتوب عليه. فإذا تاب وأنت في العدة، ورجع إلى الله، وأناب إليه، وندم على ما فعل وصلى فلا بأس بالرجوع إليك، ما دمت في العدة، أما بعد العدة فلا إلا بنكاح جديد، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13755/حكم-البقاء-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67402.mp3","categories":["الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":15259,"question":"هذه رسالة أخرى من السائلة (ش. ح) من جدة تقول: مشكلتي تتعلق بزوجي، فهو رجل مقصر في دينه، لا يصلي، وحينما أدعوه إلى الصلاة يغضب ويستهزئ بي، ويصر على تركه الصلاة، بحجة أن أباه لم يكن يصلي، فلماذا هو يصلي؟وذات يوم ألحيت عليه في ذلك، فقال لي: إذا استمريت على هذا الوضع، فالباب مفتوح، وعندها طلبت منه الطلاق.ومرة أخرى أيضًا وتقريبًا لنفس السبب قال لي: لا تكلميني إلى يوم القيامة، فما رأيكم في هذا الرجل؟ وفي كلامه الذي قاله في مناسبتين في الأولى قوله: الباب مفتوح، وفي الثانية: لا تكلميني إلى يوم القيامة، هل يعتبر هذا طلاقًا أم ماذا؟ وهل يجوز لي البقاء معه على هذا الحال؟","title":"حكم البقاء مع زوج لا يصلي","answer":"الجواب: هذا الرجل لا يجوز البقاء معه، ما دام يترك الصلاة كما ذكرت، فهو بذلك كافر، وبئس القدوة أبوه، إذا كان أبوه لا يصلي، فبئس القدوة، ولا يجوز أن يقتدى بالكافر الذي لا يصلي، أو يسب الدين، أو يأتي بناقض من نواقض الإسلام، أو بمعصية من معاصي الله، كل هؤلاء لا يقتدى بهم، هذا الرجل كافر اقتدى بكافر على حسب قوله، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. والأصح من أقوال أهل العلم أن من تركها تهاونًا وكسلًا فهو كافر، وإن لم يجحد وجوبها، وإذا كان هذا الرجل يجحد وجوبها صار كافرًا بالإجماع. وبكل حال فهذا الرجل رجل سيئ وكافر بترك الصلاة في أصح أقوال أهل العلم، فلا يجوز لك البقاء معه، بل يجب عليك أن تفارقيه ولا تمكنيه من نفسك. وقولها: الباب مفتوح، هذه كناية إذا أراد بها الطلاق معناها: اخرجي أنت طالق، فهي طلاق، وإذا كان ما أراد الطلاق، فليست بطلاق، لكن بكل حال حتى لو لم يطلق ما ينبغي لك البقاء معه، بل يجب عليك فراقه، وأن تتركيه وتذهبي إلى أهلك وأولادك معك، وليس له حق في الأولاد لكفره، فأنت أولى بأولادك، وهو رجل سيئ قد تعاطى كفرًا بالله ، فعسى الله أن يتوب عليه. فإذا تاب وأنت في العدة، ورجع إلى الله، وأناب إليه، وندم على ما فعل وصلى فلا بأس بالرجوع إليك، ما دمت في العدة، أما بعد العدة فلا إلا بنكاح جديد، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13755/حكم-البقاء-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67402.mp3","categories":["الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":15403,"question":"السائل (عدنان . م. ع) من الأردن يقول: بأنه متزوج منذ عامين، وعرف من بعض الأصدقاء بأنه إذا عقد الزواج، وهو لا يؤدي فريضة الصلاة، فالعقد باطل، مع العلم بأنني عقدت العقد ولم أكن أصلي ولا أركع ركعة، وأنا الآن التزمت بالصلوات الخمس التزامًا تامًا، هل يجب علي أن أعيد مرة ثانية؟ وكيف يكون ذلك بعد طلاقي من زوجتي وعقد جديد؟فأفيدونا يا سماحة الشيخ.","title":"ما حكم عقد النكاح لمن كان لا يصلي؟","answer":"الجواب: إذا كنت لا تصلي وهي تصلي فالعقد غير صحيح على الصحيح؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة فإذا كنت لا تصلي والمرأة طيبة تصلي، فالعقد غير صحيح، يجدد بعد توبتك يجدد، أما إذا كانت مثلك لا تصلي، فالعقد صحيح، كنكاح الكافر للكافرة.  أما إذا كانت تصلي وأنت لا تصلي فالعقد غير صحيح ويجدد على الصحيح بعد توبتك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13901/ما-حكم-عقد-النكاح-لمن-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56722.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح"]},{"id":15463,"question":"وأول سؤال نطرحه على فضيلته ورد إلينا من المستمع أبو بكر شعيب عثمان، سوداني الجنسية، مقيم في جدة، يقول: هل يجوز للرجل أن يتزوج بمهر ابنته؟ أو يتفق مع رجل آخر كل واحد منهما يأخذ بنت الثاني زوجة له بدون مهر أم لا؟ وماذا يسمى هذا في الشرع؟","title":"حكم أخذ الوالد من مهر ابنته وحكم نكاح الشغار","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبدالله، وعلى آله، وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: فلا حرج في أن يتزوج الرجل من مهر ابنته؛ لقول النبي ﷺ: أنت ومالك لأبيك وقوله ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فإذا أخذ من مهرها ما لا يضرها، ودفعه في زوجة له، فلا حرج، لكن لا يضرها، بل يدع لها شيئًا ينفعها عند زوجها، ويغنيها عن الحاجة إلى الغير، ويكون سببًا لوئامها مع زوجها، وبقائها مع زوجها، هذا هو الذي ينبغي؛ لقول النبي ﷺ: لا ضرر ولا ضرار فلا يضرها، ويشق عليها، ولا يكون سببًا لفراقها من زوجها بأخذه مهرها، ولكن لا حرج أن يأخذ منه شيئًا لا يضرها، فيستعين به في حاجاته، يجعله مهرًا لزوجة، أو بغير ذلك. أما المسألة الثانية وهي كونه يزوج ابنته على شخص آخر ليزوجه ابنته هذا لا يجوز، وهذا يسمى شغارًا في الإسلام، والنبي ﷺ قال: لا شغار في الإسلام ونهى عن الشغار في أحاديث كثيرة، قال -عليه الصلاة والسلام-: والشغار أن يقول الرجل: زوجني ابنتك وأزوجك بنتي أو زوجني أختك وأزوجك أختي هذا هو الشغار، وهو حرام وفاسد، وهو أن يشرط كل واحد منهما نكاح الأخرى كبنته أو أخته أو بنت أخيه، سواء كان هذا له أو لولده أو لابن أخيه، ونحو ذلك، هذا كله لا يجوز، والصحيح أيضًا أنه لا يجوز، ولو سمي مهرًا، حتى ولو سمي مهرًا.  وقد خالف في هذا من خالف من أهل العلم، وقالوا: إذا سمي لكل منهما مهر العادة، وتراضتا بذلك، فلا بأس، ولكن هذا قول مرجوح، وليس بصواب. والصواب: أنه متى وقع الشرط بينهما فإن المهر لا يحل ذلك سموا مهرًا أو لا؛ لأن الرسول ﷺ نهى عن الشغار، ولم يستثن، ولم يقل: إلا أن يكون لهما مهر، وما جاء في حديث ابن عمر في تفسير الشغار أنه ليس بينهما صداق فهو من كلام نافع، ليس من كلام النبي ﷺ، بل هو من كلام الراوي نافع، وكلامه ليس بحجة، الحجة في كلام النبي ﷺ، والنبي ﷺ لم يفصل بين الشغار الذي فيه مهر، والشغار الذي لا مهر فيه، ويدل على هذا ما رواه أحمد و أبو داود بإسناد جيد عن معاوية : \"أنه كتب إليه أمير المدينة، وذكر له أن بعض رجال قريش تزوج امرأة وجعل لها مهرًا، وتزوجها شغارًا، فكتب إليه معاوية  يقول له: فرق بينهما، فإن هذا هو الشغار الذي نهى عنه النبي \" ولم يلتفت معاوية إلى المهر، وهذا هو الصواب؛ لأن العلة موجودة، ولو فيه مهر، وهذه العلة هي أن هذا الشرط يفضي إلى ظلم النساء، وإلى استحلال فروجهن من غير حق، وإلى النزاع الكثير والخصومات بين الطرفين، وإلى تزويجهن بدون إذنهن، وهذه كلها نتائج وثمرات لهذا العقد الفاسد، وهي ثمرات خبيثة، ونتائج رديئة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13989/حكم-اخذ-الوالد-من-مهر-ابنته-وحكم-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_701/nour_70104.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15683,"question":"تسأل أختنا سؤالها الأخير في هذه الحلقة، وتقول: ما رأيكم إذا كان الزوج لا يصلي، أو الزوجة لا تصلي، والزوج يصلي، ما الذي على من يصلي والحال ما ذكر؟جزاكم الله خيرًا.","title":"حكم نكاح من لا يصلي","answer":"الجواب: إذا تزوج إنسان امرأة، ثم بان بعد الزواج أن أحدهما لا يصلي يفسخ النكاح؛ لأن من لا يصلي كافر على الصحيح من أقوال العلماء، ولو لم يجحد الوجوب، ولو كان كسلًا، ترك الصلاة كفر أكبر، نسأل الله العافية في أصح قولي العلماء.\nفإذا كان لا يصلي فسخ النكاح، أو كانت هي لا تصلي وهو يصلي فسخ النكاح.\nأما إن كانا لا يصليان جميعًا، فالنكاح صحيح، كنكاح سائر الكفرة.\nأما إذا كان أحدهما يصلي، والآخر لا يصلي، فإنه يفسخ النكاح حتى يتوب من لا يصلي، وإذا تاب ورجع جدد النكاح له عليها إذا رضيت بذلك.\nوإن كانت هي التي لا تصلي فإذا تابت ورجعت جدد لها النكاح عليه إذا رغب في ذلك، والدليل على هذا قول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة مع أدلة أخرى في ذلك، نعم. المقدم: سنعود إلى أسئلتك الباقية يا أخت (ج. ع) من الجمهورية اليمنية في حلقة قادمة -إن شاء الله تعالى-.","link":"https://binbaz.org.sa/fatwas/14234/حكم-نكاح-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57204.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16304,"question":"من الرياض المستمع (ر. ك. ف) رسالة وضمنها هذا السؤال يقول: لي ولد، ولأخي ولد، وكل منهما يريد أن يتزوج أخت الآخر، لكنا نسمع أن البدلة لا تجوز إلا بقطع مهر، ويكون زيادة في مهر الواحدة عن الأخرى، هل هذا صحيح، أم لا؟ نرجو الإفادة والتوضيح جزاكم الله خيرًا.","title":"ماهية نكاح الشغار وحكمه","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في عدة أحاديث، فلا يجوز نكاح البدل بالمشارطة، يقول هذا: زوجني أختك، وأزوجك أختي، أو زوجني بنتك، وأزوجك بنتي، هذا هو نكاح البدل، ويقال له: نكاح الشغار، ولو سموا مهرًا، ولو تساوى المهر، ولو اختلف المهر، ما دام فيه مشارطة لا يجوز. أما إذا خطب هذا بنت هذا، وهذا بنت هذا لنفسه، أو لأخيه، أو لولده من دون مشارطة؛ فلا بأس، الممنوع المشارطة، فأما إذا تراضوا من دون مشارطة، البنت رضيت، أو الأخت رضيت، والأخرى رضيت من دون مشارطة، بل خطب هذا، وخطب هذا؛ فلا بأس بذلك، الممنوع المشارطة، كونه يشترط ما أزوجك حتى تزوج، يعني: ما أزوجك بنتي حتى تزوجني بنتك، أو ما أزوج ولدك حتى تزوج ولدي، هذا ما يجوز، هذا هو الذي نهى عن النبي، عليه الصلاة والسلام.  فالواجب ترك ذلك، ولو سموا مهرًا متساويًا، أو أحدهما أكثر من الآخر، المهر لا يبيح الشغار، لكن لا بد من التراضي، وألا يكون هناك مشارطة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15005/ماهية-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81006.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16311,"question":"من الرياض المستمع (ر. ك. ف) رسالة وضمنها هذا السؤال يقول: لي ولد، ولأخي ولد، وكل منهما يريد أن يتزوج أخت الآخر، لكنا نسمع أن البدلة لا تجوز إلا بقطع مهر، ويكون زيادة في مهر الواحدة عن الأخرى، هل هذا صحيح، أم لا؟ نرجو الإفادة والتوضيح جزاكم الله خيرًا.","title":"ماهية نكاح الشغار وحكمه","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في عدة أحاديث، فلا يجوز نكاح البدل بالمشارطة، يقول هذا: زوجني أختك، وأزوجك أختي، أو زوجني بنتك، وأزوجك بنتي، هذا هو نكاح البدل، ويقال له: نكاح الشغار، ولو سموا مهرًا، ولو تساوى المهر، ولو اختلف المهر، ما دام فيه مشارطة لا يجوز. أما إذا خطب هذا بنت هذا، وهذا بنت هذا لنفسه، أو لأخيه، أو لولده من دون مشارطة؛ فلا بأس، الممنوع المشارطة، فأما إذا تراضوا من دون مشارطة، البنت رضيت، أو الأخت رضيت، والأخرى رضيت من دون مشارطة، بل خطب هذا، وخطب هذا؛ فلا بأس بذلك، الممنوع المشارطة، كونه يشترط ما أزوجك حتى تزوج، يعني: ما أزوجك بنتي حتى تزوجني بنتك، أو ما أزوج ولدك حتى تزوج ولدي، هذا ما يجوز، هذا هو الذي نهى عن النبي، عليه الصلاة والسلام.  فالواجب ترك ذلك، ولو سموا مهرًا متساويًا، أو أحدهما أكثر من الآخر، المهر لا يبيح الشغار، لكن لا بد من التراضي، وألا يكون هناك مشارطة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15005/ماهية-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81006.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16337,"question":"يسأل سؤالًا يقول فيه: ما حكم من يزوج ابنته لشاب لا يصلي لا في البيت، ولا في المسجد بحكم القرابة؟ جزاكم الله خيرًا.","title":"حكم تزويج القريب الذي لا يصلي","answer":"الجواب: ليس لأحد أن يزوج شخصًا لا يصلي، سواء كان شابًا، أو شيخًا، وسواء كان قريبًا، أو بعيدًا، هذا منكر، هذا ظلم للمرأة، وخيانة، ولا يجوز لها أن ترضى... أيضًا هي، ليس للولي ولا لها، ليس لهم جميعًا تزويج المرأة المسلمة المصلية لشخص لا يصلي؛ لأن ترك الصلاة كفر، كفر أكبر على أصح أقوال العلماء، وإن لم يجحد وجوبها؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فترك الصلاة منكر عظيم، وكفر ظاهر، فلا يجوز للمرأة أن تنكح كافرًا بترك الصلاة، أو بغير ذلك، المسلمة لا تنكح الكافر، يقول الله : لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10] ويقول -جل وعلا-: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ [البقرة:221] فليس لوليها أن يزوجها إلا للمسلم، إذا كانت تصلي. أما إذا كانت لا تصلي، وتزوجها مثلها من لا يصلي صح، وعليهما التوبة جميعًا، والرجوع إلى الله، والقيام بالصلاة، هذا هو الواجب على الجميع، وعلى الأولياء أن يعتنوا بهذا الأمر، وهكذا من اشتهر بشرب الخمر، أو معاصي أخرى، ينبغي لوليها أن يصونها عنه؛ لأنه قد يضرها، قد يدعوها إلى هذا المنكر، فالولي يختار لها الرجل الصالح الطيب حسب الطاقة، حسب الإمكان، وأما تارك الصلاة فلا يجوز أبدًا، تزويجه؛ لأن تركها كفر، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15031/حكم-تزويج-القريب-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71313.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":16342,"question":"من المدينة المنورة رسالة مؤثرة، بعثت بها إحدى الأخوات المستمعات، تقول المرسلة: (م. س. ح) أختنا تقول: إن زوجي لا يصلي، ولا يصوم، ويشرب الخمر، وكثيرًا ما نصحته، وصبرت عليه، وعلى أفعاله من الضرب المبرح، والشتم عسى أن يهديه الله مدة ثماني سنوات، ولكن دون جدوى، وكان يقول: إذا حصل اجتماع، ومناقشة بيني وبينك في وجود أهلي وأهلك؛ فأنت طالق، وقد تم الاجتماع في مجلس واحد، وبحضور أهلي وأهله، وحصلت مناقشة بيننا، فهل بذلك تعتبر هذه طلقة، أم لا؟ وكم هي عدة المطلقة، هل هي ثلاثة أطهار؟ أم ثلاث حيض؟ ثم ما هو مصير أطفالي؟ هل يكون الأب -وصورته كما وضحتها لكم- هو الولي في تلك الحالة، أم الأم؟ وعلى من تجب النفقة؟ وجهوني جزاكم الله خيرًا.","title":"حكم البقاء مع زوج لا يصلي ويفعل الكبائر","answer":"الجواب: أولًا يجب عليك ترك هذا الزوج، وعدم البقاء معه؛ لأن من لا يصلي كافر، وإن أقر بالوجوب في أصح قولي العلماء، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فهي عمود الإسلام، من تركها؛ كفر، وإذا كان لا يؤمن بها صار كافرًا عند جميع أهل العلم. ثم مع هذا فيه شر آخر، شرب الخمور، والسب، والشتم، والإيذاء، والضرب، كل هذه عيوب قبيحة شديدة، لكن أعظمها، وأخطرها ترك الصلاة؛ لأنه كفر. فنصيحتي لك الحذر، والبعد عنه، ولا يجوز لك البقاء معه، بل يجب أن تغادري المكان إلى أهلك. أما ما يتعلق بالطلاق الذي صدر منه، والنفقة على أولاده فهذا تبع المحكمة، عليك مراجعة المحكمة، والمحكمة تنصفك -إن شاء الله- تعطيك حقك؛ لأن هذه خصومات بينك وبينه، فالحاكم ينظر في الأمر، ويعطيك وثيقة الفرقة والطلاق، ويعطيك حقك -إن شاء الله- من جميع الوجوه، والمحكمة فيها الخير والبركة في بلدكم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15036/حكم-البقاء-مع-زوج-لا-يصلي-ويفعل-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71405.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح","قضايا المرأة"]},{"id":16466,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من البحرين بتوقيع إحدى المستمعات تقول: بنت الطهماجي، تقول في قضيتها: تزوجت رجلًا ملتزمًا، لكنه تغير في سلوكه الدنيوي والديني، حلق لحيته، وشرب الدخان، والمسكرات حتى إنه يبحث عن وظيفة وإن كانت غير شريفة، تساهل في أمر الصلاة، فمرة يصلي، وأخرى لا يصلي، وما صلاها يصليها نقرًا، كيف أتصرف معه، علمًا بأن لدي منه ولدين، وأنا عند الأهل في الوقت الحاضر؟ وجهوني جزاكم الله خيرًا.","title":"حكم بقاء المرأة مع زوج يصلي أحيانًا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالواجب عليك ترك هذا الزوج، والذهاب إلى أهلك، والرفع عنه إلى المحكمة؛ حتى يفرق بينك وبينه إذا كان تارة يصلي، وتارة لا يصلي، مع ما فيه من العيوب الأخرى من شرب المسكر، وغير ذلك، لكن أعظمها ترك الصلاة، فإن تركها كفر، بخلاف المسائل الأخرى فإنها معصية. وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: بين الرجل، وبين الكفر والشرك ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليك الذهاب إلى أهلك حتى يسهل الله التوبة، أو الفرقة، إما أن يتوب، وإما أن يطلق، ولا يجوز لك البقاء معه ما دامت حاله ما ذكرت من جهة الصلاة. أما المعاصي الأخرى -لو كان يصلي- فهي عيب، وعذر لك أن تطلبي الطلاق؛ لأنها عيب كبير، كونه يشرب الخمر، هذا عيب كبير مع حلق اللحية، ومع شرب الدخان، هذه عيوب، لكن أشدها وأعظمها ترك الصلاة؛ لأنها كفر في أصح قولي العلماء، وإن لم يجحد الوجوب، متى ترك الصلاة بعض الأحيان، وإن لم يجحد وجوبها؛ كفر بذلك في أصح قولي أهل العلم، فنسأل الله له الهداية، وأن يمن الله عليه بالتوبة، نعم. المقدم: اللهم آمين، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15180/حكم-بقاء-المراة-مع-زوج-يصلي-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81301.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":16521,"question":"اتفق والدي وعمي والد زوجتي عندما خطب والدي منهم أن والدي يدفع أي مبلغ يطلبه والد أي بنت يريدها ولده، ولكن لم يعجب ولده أي بنت، فطلب مني والدي أن يزوجه بشقيقتي، فوافق والدي، وذهبنا، وعقدنا القران، ودفع والدي مبلغ عشرة آلاف ريال لوالد العروسة، وكذلك جاء عمي وولده، وعقد ولده القران على أختي، ودفع أيضًا نفس المبلغ، وبعد سنة من عقد القران سأل والدي أحد العلماء، فأفاده أنه لا يجوز، ويسمى شغارًا، ولكن كل واحد يدفع لزوجته مهرًا متفقًا عليه، ودفعته لزوجتي قبل العرس بمبلغ وقدره خمسة آلاف ريال، وكذلك دفع رحيمي لزوجته نفس المبلغ، فهل هذا الزواج شغار، أم لا؟ أفيدوني جزاكم الله خيرًا.","title":"حقيقة الشغار المنهي عنه","answer":"الجواب: الشغار: هو أن يكون العقد مشروطًا بين المتعاقدين، يقول هذا: زوجني، والآخر يقول: زوجني، زوجني وأزوجك، كل واحد منهما يشترط على الآخر، فإذا كان والدك وعمك اشترطا هذا العقد؛ فهذا هو الشغار. أما إن كان والدك خطب ابنة عمك لك، ولم يشترط والدها شيئًا، أو خطب والدها منكم، ولم تشترطوا شيئًا؛ فلا حرج، أما إذا كان عن تشارط بين الوالد، وبين العم، تشارطا على أنه يزوجك ابنته، وأبوك يزوج ولده ابنته، هذا هو الشغار المنهي عنه، الرسول نهى عن الشغار -عليه الصلاة والسلام- في عدة أحاديث قال: والشغار أن يقول الرجل: زوجني ابنتك، وأزوجك ابنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار. أما إذا خطب هذا من هذا من دون شرط، ثم خطب الآخر بعد ذلك في أي وقت من دون شرط؛ فلا يضر، ولا يكون شغارًا إلا بالمشارطة، والاتفاق، وأنتم أعلم بالواقع، فإذا كان والدك، وعمك تشارطا، واتفقا على الأمر الواقع، وأنه يزوجك، وأبوك يزوج ولده، وأنه لابد من هذا؛ فهذا هو الشغار، والعقد باطل. وعلى كل واحد منكما أن يجدد العقد إذا كان له رغبة فيها، وهي ترغب فيه؛ يجدد العقد، عقدًا شرعيًا برضاها، من دون شرط المرأة الأخرى، كل واحدة لها رضاها... رغبتها من دون شرط، فيجدد العقد بمهر جديد، وعقد جديد وشاهدين، إذا كان كل واحد يرغب في الآخر من دون شرط المرأة الأخرى، والله ولي التوفيق، نعم. المقدم: الله ولي التوفيق، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15241/حقيقة-الشغار-المنهي-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75702.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16715,"question":"سماحة الشيخ! أنا لا أملك شيئًا من المال، والمهر عندنا غالٍ؛ فلجأت للمقايضة، أي: أعطيت أختي إلى ابن عمي، وأخذت بنت عمي بدل أختي، فما حكم هذا؟ جزاكم الله خيرًا.","title":"ما حكم أن أزوج أختي لابن عمي، وأتزوج بنت عمي دون مهر؟","answer":"الجواب: هذا لا يجوز، هذا يسمى نكاح الشغار، إذا كان بينكم مشارطة أنت تعطيه أختك، وهو يعطيك أخته؛ هذا ما يجوز، الرسول ﷺ نهى عن هذا في عدة من الأحاديث الصحيحة، أما لو خطبت بنتًا، وخطب بنتًا من دون مشارطة، بالتراضي؛ فلا بأس، أما أن تقول: زوجني وأزوجك هذا لا يجوز، لا مع البنت، ولا مع الأخت، ولا مع بنت الأخ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15478/ما-حكم-ان-ازوج-اختي-لابن-عمي-واتزوج-بنت-عمي-دون-مهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76110.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16773,"question":"القضية التالية: قضية رضاع يقول: ما رأيكم في زواج رجل من امرأة رضع مع أختها الكبرى؟","title":"حكم زواج رجل من امرأة رضع مع أختها","answer":"الجواب: إذا كان رضع من أمها خمس رضعات فأكثر، فهو أخوها، والنكاح باطل، إذا ثبت ذلك بالبينة الشرعية، أما إذا كان الرضاع أقل من خمس رضعات، أو كان فيه شك، ليس هناك من يضبطه، فالزواج صحيح، ولا يضره ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/15540/حكم-زواج-رجل-من-امراة-رضع-مع-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82211.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16793,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من العراق، وباعثتها إحدى المستمعات من هناك تقول: أم نجم، أم نجم لها قضيتان، القضية الأولى تقول فيها عن نفسها: أنا سيدة متزوجة، وأصلي وأصوم، وعلى عبادة تامة، وزوجي يسير على غير ما أنا عليه، حيث يحتسي الخمر، ويفعل المجتنبات، وكل ما حرم الله، مع العلم أن لدي أبناء منه، وحاولت إصلاحه، فاهتدى إلى الصواب لمدة أقل من سنة، حيث صلى وصام، ولكن عاد إلى ما كان عليه، وأحاول مرة أخرى أن أصلحه أنا وأولادي، ولكن دون جدوى، فأسألكم: هل تحق لي صلاتي وصيامي؟ أم أتحمل إثمًا معه؟ هذا السؤال الأول، والثاني سأوافيكم به بعد أن أسمع هذه الإجابة، جزاكم الله خيرًا.","title":"حكم البقاء مع زوج لا يصلي ويقارف الكبائر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الواجب عليك -أيها السائلة- عدم البقاء مع هذا الزوج، نسأل الله لنا وله الهداية، والتوفيق للتوبة النصوح، ما دام بهذه الحال، وأنه لا يصلي؛ فإن الذي لا يصلي يعتبر كافرًا - في أصح قولي العلماء- كفرًا أكبر، فلا يجوز لك البقاء معه، بل يجب اجتنابه، والحذر منه، وعدم تمكينه من نفسك، والواجب أيضًا عدم اعتباره زوجًا؛ حتى يتوب إلى الله مما هو فيه من ترك الصلاة، وغير ذلك مما يعتبر كفرًا. أما ما يتعلق بشرب المسكر فهذه معصية كبيرة، فإن الخمر من كبائر الذنوب، فالواجب عليه التوبة إلى الله من ذلك، وأنت بالخيار إذا صلى، واستقام على الصلاة، وترك ما يوجب كفره؛ فأنت بالخيار، إن شئت بقيت معه، وإن شئت طلبت الطلاق ما دام يتعاطى المسكر؛ لأنه عيب كبير، وخطر عليك وعلى أولادك، نسأل الله لنا وله الهداية، والرجوع إلى الصواب، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15544/حكم-البقاء-مع-زوج-لا-يصلي-ويقارف-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76301.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":16938,"question":"أحسن الله إليكم، هذه الرسالة من اليمن من السائل محمد أحمد يقول: سماحة الشيخ ما حكم من تزوج من امرأة تصلي وهو لا يصلي؟ وما حكم عكس ذلك مأجورين؟ وهل يجوز الزواج من رجل لا يصلي؟","title":"حكم الزواج بمن لا يصلي","answer":"الجواب: الصواب أنه يجدد النكاح إذا كان يصلي، وهي لا تصلي، أو العكس هي تصلي، وهو لا يصلي فإنه يجدد النكاح، هذا هو الأحوط والأفضل، لقول النبي ﷺ: بين الرجل، وبين الكفر، والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. أما إذا كانا لا يصليان جميعًا فالعقد صحيح، إذا كانا لا يصليان كلاهما فالعقد صحيح، أما إذا كانت لا تصلي، وهو يصلي، أو هو لا يصلي، وهي تصلي فلا يصح تزوجه منها إلا بعد التوبة، إذا كان لا يصلي حتى يتوب، أو هي لا تصلي حتى تتوب، وإذا عقد العقد، وهو لا يصلي، أو هي لا تصلي، واحد منهما يصلي وواحد لا يصلي يجدد العقد على الصحيح.","link":"https://binbaz.org.sa/fatwas/15711/حكم-الزواج-بمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58611.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16984,"question":"رسالة من أحد الإخوة المستمعين له فيها سؤالان، في سؤاله الأول يقول: زوج أختي لا يصلي أبدًا حتى أيام الجمعة، ولا أظنه إنكارًا لوجوب الصلاة، إنما بحجة أنه عامي، لا يقرأ ولا يكتب، فهل في بقاء أختي معه شيء، وإنني عندما أسمع عقوبة تارك الصلاة؛ يشفق عليه قلبي، ويحن، كما أنني أعانقه أحيانًا كأيام الأعياد، وغيرها، انصحوني جزاكم الله خيرًا.","title":"هل يجوز للمرأة البقاء مع زوج لا يصلي؟","answer":"الجواب: ترك الصلاة كفر بنص النبي -عليه الصلاة والسلام- والصحيح من أقوال أهل العلم: أنه كفر أكبر، يخرج من الملة، وإن لم يجحد وجوبها، لكن إن جحد وجوبها؛ كفر عند جميع العلماء. يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولا يجوز بقاء أختك معه، بل يجب التفريق بينهما إلا أن يتوب. والواجب عليك هجره، وعدم معانقته، وعدم صحبته حتى يتوب إلى الله  فهجر مثله من أهم المهمات، وأقل الأحوال أنه سنة مؤكدة، والقول بالوجوب قول قوي، القول بوجوب هجر من أظهر المعصية، والكفر قول قوي. فعليك يا أخي! أن تنصحه لله، وأن تخوفه من الله، وأن تجتهد في توبته؛ لعل الله يهديه بأسبابك، فإن أصر على الباطل، وأبى أن يقبل منك؛ فاهجره هذا هو المشروع. وإن رأيت المواصلة للنصيحة بين وقت وآخر؛ فذلك خير، من باب النصح لله، ولعباده، من دون أن تتخذه صاحبًا، أو صديقًا، أو عشيرًا، لا، ولكن بين وقت وآخر تمر عليه، وتنصحه تقول: اتق الله.. راقب الله يا عبد الله! الصلاة عمود الإسلام، من تركها كفر؛ لعل الله يهديه بأسبابك. وإذا تيسر أن تقول لإخوانه، أو أبيه، أو أصدقائه: أن ينصحوه أيضًا؛ حتى يساعدوك، فهذا أمر مطلوب، والمسلمون إخوة يتناصحون، وهذا إنسان قد تعاطى ما يخرجه من الإسلام، فالواجب نصيحته، وأمره بالمعروف، ونهيه عن المنكر، والأخذ بيده إلى الصواب؛ لعل الله يهديه بأسبابك. وقد قال الله  في كتابه العظيم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] وقال سبحانه في كتابه العظيم: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] وقال النبي ﷺ في الحديث الصحيح: الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم. نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، حجته أنه لا يقرأ، ولا يكتب، ما هو توجيهكم حول هذا؟ الشيخ: هذه ليست حجة، يجب عليه أن يصلي وإن كان عاميًا، ليس من شرط الصلاة أن يكون يقرأ ويكتب، عليه أن يصلي، ويتعلم، ويتفقه في دينه، ولا يدع الصلاة، عليه أن يصلي، وعليه أن يؤدي الزكاة، وعليه أن يصوم رمضان، وعليه أن يحج حج البيت إن استطاع، وإن كان غير عالم، وإن كان عاميًا، لكن يلزمه التفقه في دينه، والسؤال عما أشكل عليه؛ لأنه مخلوق لعبادة الله، فواجب عليه أن يتعلم هذه العبادة، ويتبصر فيها، يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ويقول سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21].  فهذه العبادة الذي خلقنا لها، وأمرنا بها يجب أن نفقهها، وأن نعلمها، وأن نسأل أهل العلم عنها؛ حتى نكون فيها على بصيرة، وحتى نؤديها على علم، ويقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين فالذي يعرض، ولا يتفقه هذه من علامة أن الله ما أراد به خيرًا، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، ذكرتم أن من وسائل التعليم: السؤال، هل تتفضلون بذكر وسائل أخرى؟  الشيخ: نعم، سؤال أهل العلم من وسائل الفقه في الدين، وتدبر القرآن الكريم من وسائل ذلك، وهو أعظم كتاب، وأشرف كتاب، وأنفع كتاب، تدبره، والإكثار من قراءته من أعظم الأسباب في الفقه في الدين، والبصيرة، وهكذا حضور حلقات العلم.. سماع خطب الجمع بإنصات، وحضور قلب.. وسماع النصائح من الناصحين؛ كل هذا من أسباب تحصيل العلم. فالواجب على العامي أن يجتهد في حضور حلقات العلم، وفي الإصغاء لخطب الجمعة، وفي سؤال العلماء عما أشكل عليه، وإذا كان يقرأ القرآن يجتهد في تدبره، والاستفادة منه، وإذا كان لا يقرأ؛ يجتهد في سماع الأشرطة التي فيها تفسير القرآن الكريم، وسماع القرآن من إذاعة القرآن، كل هذا يفيده كثيرًا وينفعه كثيرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15776/هل-يجوز-للمراة-البقاء-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82905.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","قضايا المرأة"]},{"id":17163,"question":"من تبوك رسالة بعث بها المستمع: سالم مسلم البياضي، الأخ سالم يسأل ويقول: حدثونا لو تكرمتم عن نكاح الشغار، وعن حكمه، وما حكم إكراه البنات عليه؟ جزاكم الله خيرًا.","title":"تعريف الشغار وحكم إكراه البنات في الزواج","answer":"الجواب: نكاح الشغار هو أن يشترط الولي على الآخر نكاح بنته، أو أخته إذا أراد تزويجه على بنته، أو أخته، فيقول: نعم أزوجك ابنتي، أو أختي بشرط أنك تزوجني ابنتك، أو أختك، أو تزوج ابني، أو ابن أخي، أو أخي، هذا هو الشغار، شرط نكاح في نكاح، الرسول نهى عن هذا -عليه الصلاة والسلام- نهى عن الشغار، ولو كان فيه مهر. فالواجب الحذر من ذلك، فالتزويج لا يكون بالشرط، يكون بغير شرط، تزوجه إذا رغبت فيه ورضيت المرأة تزوجه من دون شرط نكاح آخر، فشرط النكاح .... يسمى الشغار، فإذا قال: أزوجك ابنتي، أو أختي، أو بنت أخي على شرط أنك تزوجني، أو تزوج ولدي، أو أخي بنتك، أو أختك، أو بنت أخيك، أو نحو ذلك، هذا هو الشغار، لا يجوز، والنكاح باطل على الصحيح. المقدم: وما حكم إكراه البنات؟ الشيخ: أما إكراه البنات فلا يجوز، يقول النبي ﷺ: لا تنكح الأيم حتى تستأمر والأيم: الثيب التي قد تزوجت ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله، وكيف إذنها؟ قال: أن تسكت. فلا يجوز تزويج النساء إلا برضاهن حتى من الأب، حتى الأب لا يكرههن، لابد... الحق لهن، والحاجة لهن، فلابد من مشاورة البنت، ثيبًا كانت أو بكرًا، فإن رضيت وإلا فلا تزوج، لا يزوجها أبوها، ولا أخوها، ولا غيرهما بالإكراه، والغصب لا، بالمشاورة وطيب النفس، فإذا رضيت فالحمد لله، وإن أبت فلا، لكن إذا كانت بكرًا يكفي سكوتها، إذا تشاور، وسكتت كفى. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15982/تعريف-الشغار-وحكم-اكراه-البنات-في-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72215.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17484,"question":"بعد هذا ننتقل إلى قضية يثيرها الأخ: يوسف عمر علي الصومالي، الأخ يقول: إنه انتشر في الوقت الحاضر دعوة بين الناس، وفتوى تجيز العقد على المرأة الحامل غير المتزوجة، سواء للذي أحبلها، أو لغيره، ويقول: إن هذا الموضوع انتشر، ويرجو من سماحتكم معالجته، وتنبيه الناس إلى خطورته، وبيان الحكم الشرعي فيه، جزاكم الله خيرًا.","title":"حكم عقد النكاح بامرأة حامل","answer":"الجواب: الحامل من الزنا، أو من غير الزنا، لا يجوز العقد عليها حتى تطهر، لقول النبي ﷺ بل لقول الله : وَأُوْلاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ [الطلاق:4] ولقول النبي ﷺ ينهانا: من كان يؤمن بالله واليوم الآخر، فلا يسقي ماءه زرع غيره يعني: منيه زرع غيره يعني حمل غيره.  فإذا كانت حاملًا من المطلق، أو الميت، فليس لها أن تتزوج حتى تضع الحمل، وإذا كانت حاملة من الزنا، فليس لها أن تتزوج لا بالزاني، ولا بغيره حتى تضع؛ لأن حملها مشوب بنطفة لا تنسب للزاني، ولا لغيره، ينسب لأمه، فالزاني لا ينسب إليه الطفل، مثلما قال النبي ﷺ: الولد للفراش، وللعاهر الحجر.  فالولد لأمه إذا كانت ليست فراش، وإن كانت فراشًا فالولد لزوجها، والزاني يأخذ الحد الشرعي، فإذا حملت وهي ليست ذات زوج فإنها لا يجوز تزوجها مطلقًا في أي بلاد الله حتى تضع الحمل، فإذا وضعت الحمل؛ جاز لها التزوج بعد التوبة، والرجوع إلى الله، والإنابة، فيجوز للمسلم أن يتزوجها بعد التوبة. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16387/حكم-عقد-النكاح-بامراة-حامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72511.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","مبطلات النكاح"]},{"id":17521,"question":"الفتاة التي لا تصلي هل يجوز الزواج بها؟","title":"حكم الزواج بالفتاة التي لا تصلي","answer":"الجواب: يجوز الزواج بها لأمثالها من الذين لا يصلون؛ لأنهم يكفرون بترك الصلاة كلهم، فتساووا في الكفر، فإن تزوجها من لا يصلي فلا حرج، أما أن يتزوجها من يصلي فالصحيح أنه لا يصح النكاح، بل عليهم التجديد تجديد النكاح إذا تابوا إلى الله ورجعوا إليه ، أما إذا كانا لا يصليان جميعًا فالنكاح صحيح وعليهما التوبة إلى الله والبدار بأداء الصلاة ونكاحهم صحيح؛ لأن الرسول ﷺ لما أسلم الناس لم يسألهم عن أنكحتهم أقرهم على أنكحتهم، لكن من تزوج امرأة يعرف أنها لا تصلي وهو يصلي لا يصح أو بالعكس هو لا يصلي وهي تصلي كذلك لا يجوز، فإذا علمت أنه لا يصلي لا يحل لها أخذه وهو كذلك لا يحل له أخذها إذا كانت لا تصلي، فإن وقع العقد وجب أن يجدد ويعاد، إذا كان كل واحد يرغب في صاحبه يجب أن يجدد إذا تاب من يترك الصلاة ورجع إلى الله فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16461/حكم-الزواج-بالفتاة-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83715.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17570,"question":"يسأل تفسير قول الحق تبارك وتعالى: وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ كِتَابَ اللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ أَنْ تَبْتَغُوا بِأَمْوَالِكُمْ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ فَمَا اسْتَمْتَعْتُمْ بِهِ مِنْهُنَّ فَآتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَاضَيْتُمْ بِهِ مِنْ بَعْدِ الْفَرِيضَةِ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا [النساء:24]،  هل زواج المتعة حلال؟ أرجو تفسير هذه الآية؟","title":"حكم زواج المتعة","answer":"الجواب: المحصنات: هن المزوجات، حرامٌ نكاح المزوجة؛ حتى يموت زوجها، أو يطلقها، وتخرج من العدة، إلا ما ملكت أيمانكم إلا ملك اليمين، إذا كان سبيت، سباها المسلمون، فإنها تحل لمن سباها.. من جاءت في نصيبه، لمن أعطي نصيبه من الإماء، تحل له إذا استبرأها بحيضة، ولو أن لها زوجًا في الكفار، سبيها فراقٌ بينها وبين زوجها، كتاب الله عليكم يعني: الزموا كتاب الله، وأن تبتغوا بأموالكم هذا فيه شرعية المهور، وأنه يبتغي الزوجة بمال، يدفع المال، هذا هو المشروع، ولو قليلا في النكاح، إلا من عجز، يجوز أن يتزوج بغير مال مثل تعليمها شيئًا من القرآن، أو شيئًا من الحديث، أو تعليمها شيئًا من الصناعات، أو العلوم النافعة، للحديث السابق في قصة الواهبة، التي زوجها النبي ﷺ على شخصٍ يعلمها من القرآن.\nأما المتعة، فقد كانت مباحة في أول الإسلام، ثم حرمها الله بعد ذلك عام خيبر، وقيل: في حجة الوداع، وقيل: عام الفتح، والمقصود أنها حرمت في آخر أيام الهجرة، كانت مباحةً، يتزوج الإنسان المرأة على الشهر، والشهرين، والسنة، والسنتين، لمدة معلومة، بشيءٍ معلوم، فإن انتهت المدة، انتهى النكاح، هذه المتعة، ثم نسخت، قال النبي ﷺ: إن الله قد حرم ذلك إلى يوم القيامة، فمن كان عنده منهن شيء؛ فليخل سبيلها رواه مسلم في الصحيح، وفي الصحيحين عن علي ، قال: إن الله حرم لحوم الحمر الأهلية، وحرم المتعة من النساء، الاستمتاع بالنساء.\nفالمقصود؛ أنها حرمت، وانتهى حلها، وصارت في آخر حياة النبي ﷺ محرمةً على المسلمين، وكان حلها منسوخًا بالأدلة الشرعية، فالواجب الحذر من ذلك، ولا يجوز للمسلم أن يتزوج امرأةً متعةً، شهرًا، أو شهرين، أو سنة، أو سنتين، بل يجب أن ينكحها للرغبة فيها، فإن ناسبته بقيت معه، وإن لم تناسبه طلقها، من دون أن يحدد المدة، هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/16493/حكم-زواج-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72605.mp3","categories":["الأنكحة المحرمة"]},{"id":17594,"question":"يسأل سماحة الشيخ مع الناس الذين يسألون عن زواج الشغار، توجيهكم، وكيف يكون الشغار؟","title":"صورة زواج الشغار وحكمه","answer":"الجواب: نكاح الشغار محرم ولا يجوز وباطل على الصحيح، ولو سمي فيه مهر؛ لأن الرسول نهى عنه في أحاديث كثيرة عليه الصلاة والسلام، والشغار أن يقول: زوجني وأزوجك، زوجني بنتك وأزوجك بنتي، أو زوجني بنتك وأزوجك أختي، أو زوجني أختك وأزوجك أختي، هذا يقال له: الشغار، يشترط نكاح مرأة بمرأة، هذا الشغار، يعني: اشتراط هذا أخت هذا أو بنت هذا، أو هذا بنته وهذا أخته، هذا هو الشغار، يقول النبي ﷺ لما نهى عن الشغار قال: والشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار، شرط عقد في عقد، ولو سموا مهرًا. فالواجب الحذر من ذلك وعدم فعل ذلك، أما إذا خطب منه ولم يشترط شيئًا وخطب الآخر وتزوجوا لا بأس، خطب بنته والآخر خطب بنته أو أخته وتزوجوا من دون مشارطة هذا لا بأس، لا حرج ، أما بالمشارطة فهذا لا يجوز. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16529/صورة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84114.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17960,"question":"سماحة الشيخ! الأخت السائلة أم أحمد من الزلفي تقول: زوجي هداه الله لا يصلي، وقد ناصحته كثيرًا، فهو يترك بعض الأوقات ويصلي بعض الأوقات في البيت، هل من توجيه من سماحة الشيخ عبد العزيز حفظه الله؟","title":"حكم البقاء مع زوج لا يصلي إلا أحيانًا","answer":"الجواب: الواجب على كل مسلم أن يتقي الله، وأن يراقب الله، وأن يصلي الصلوات الخمس كلها في الجماعة في المساجد، ولا يجوز له ترك شيء منها، ولا الصلاة في البيت، هذا منكر، النبي ﷺ يقول: من سمع النداء فلم يأت يعني: إلى المسجد فلا صلاة له إلا من عذر قيل لـابن عباس: ما هو العذر؟ قال: خوف أو مرض»، «وجاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب.\nوقال ﷺ: لقد هممت أن آمر بالصلاة تقام، ثم آمر رجلًا فيؤم الناس، ثم أنطلق إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم، هذا لا يجوز للمؤمن أن يصلي في البيت، بل يجب أن يصلي مع الناس، والذي يترك الصلاة كافر، نسأل الله العافية.\nيقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. فإذا كان لا يصلي بعض الأوقات اتركيه، اذهبي إلى بيت أهلك لا تجلسي عنده؛ لأن ترك الصلاة كفر، نسأل الله العافية، فإذا كان هكذا ولم يسمع منك ولم يقبل النصيحة؛ اتركيه واذهبي إلى أهلك، حتى يهديه الله أو يطلق.\nالمقدم: جزاكم الله خيرًا على هذا التوجيه سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16972/حكم-البقاء-مع-زوج-لا-يصلي-الا-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59833.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","قضايا المرأة"]},{"id":18194,"question":"على بركة الله نبدأ برسالة أم عمار من الجبيل، كتبت هذه الرسالة بأسلوبها الخاص وتذكر يا سماحة الشيخ بأنها امرأة متزوجة ولديها ولد طفل، ملتزمة بأوامر الله، وتحمد الله، وتشكره على ذلك، تذكر بأن زوجها متهاون في الصلاة، ويشرب المسكر، قدمت له النصيحة عدة مرات، ومرة يستجيب ومرة يعاند ويكابر، تقول: الآن لنا سنتين من زواجنا صبرت لعل الله  أن يهديه، والسؤال يبقى يا سماحة الشيخ! هل أخبر أهلي وأنفصل عنه أم ماذا؟أصبر من باب الرضا بالقضاء والقدر على أمل أن يهديه الله، وأخشى إن انفصلت عنه أن يأخذ مني أبنائي أو ابني؟ فأرجو إرشادي سماحة الشيخ إلى ما فيه خير ديني ودنياي.","title":"حكم الزوج المتهاون بالصلاة والشارب للمسكر","answer":"الجواب: بسم الله الرحمن الرحيم،الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: هذا الزوج في أمره تفصيل، إن كان لا يصلي بعض الأحيان فالواجب عليك تركه، والذهاب إلى أهلك، وعدم البقاء معه؛ لأن ترك الصلاة كفر أكبر لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، أما إذا كان يصلي ولكن قد يصلي في البيت ما يصلي مع الجماعة بعض الأحيان فهذا لك الصبر مع النصيحة. وهكذا شربه الخمر منكر عظيم، فلك الصبر لعل الله يهديه، لأنه مسلم، شرب الخمر لا يخرجه عن الإسلام يكون عاصي قد أتى كبيرة عظيمة، وإن طلبت الفراق منه فلك العذر، لأن تهاونه بالصلاة في الجماعة وتعاطيه المسكر عيب كبير، فلك أن تخرجي إلى أهلك، وتطلبي الفراق من جهة المحكمة. أما إذا ترك الصلاة فتركها كفر، ليس لك البقاء معه، بل يجب أن تفارقيه، وأن تذهبي إلى أهلك، وأن تسعي في الفراق من طريق المحكمة، نسأل الله لنا وله الهداية. المقدم: اللهم آمين، أثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17239/حكم-الزوج-المتهاون-بالصلاة-والشارب-للمسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78201.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18425,"question":"تقول: إن لديها أخ لا يصلي ولا يصوم وعمره خمس وعشرون سنة، وهو من يوم أن بلغ وهو لا يعرف الصلاة ولا الصوم، فهل يجوز أن نأكل معه؟وهل يجوز أن أخطب له زوجة تصلي؛ عسى أن تعينه على العودة إلى دينه؟ أم نخطب له زوجة مثله لا تصلي؟ وهل وهو خال لبناتي يجوز لهن أن يكشفن عليه؟ وجهونا جزاكم الله خيرًا.","title":"حكم إعانة تارك الصلاة على الزواج","answer":"الجواب: عليكم أن تنصحوه؛ لأن هذا منكر عظيم، فعليكم أن تنصحوه لعل الله يهديه بأسبابكم؛ لأن ترك الصلاة كفر، كفر أكبر لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالواجب أن ينصح وأن يوجه إلى الخير، فإن لم يستجب يرفع أمره إلى المحكمة إلى ولاة الأمور حتى يستتاب فإن تاب وإلا قتل. أما الكشف له فلا بأس؛ لأنه محرم ولو كان كافرًا، محرم لأخواته وبنات أخيه وبنات أخته هو محرم، لكن يجب أن يهجر وأن يشدد عليه، إذا لم ينفع فيه الكلام الطيب يجب أن يهجر ويبين له الكراهة لعمله والمقت لعمله وأنه أتى منكرًا عظيمًا لعل الله يهديه بأسباب ذلك. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا. بالنسبة للخطبة له، يريدون أن يزوجوه فيزوجوه مصلية أو تاركة صلاة؟ الشيخ: لا ما يجوز يتزوج مصلية؛ لأنه ما يحل لها تتزوجه، المصلية لا يحل لها أن تتزوج بإنسان لا يصلي، بل عليه أن يتوب إلى الله ، وينبغي أن يترك حتى لعل الله يمن عليه بالتوبة، ولا يغرر به أحد؛ لأن التي لا تصلي قد يزيدها شرًا، إذا كانت لا تصلي تحل له التي ما تصلي مثله كافرة مثله، تحل له، لكن كونه يُساعد في ذلك قد يضرها هي أيضًا، قد يزيدها شرًّا إلى شرها. نعم. المقدم: إذًا يتأنى في موضوع الزواج ... الشيخ: التأني أولى، التأني أولى حتى لعل الله يهديه، لعله يرجع إلى الصواب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17504/حكم-اعانة-تارك-الصلاة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73307.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18770,"question":"السائلة تقول في هذا السؤال -سماحة الشيخ-: ما حكم الشرع في نظركم في المرأة التي تصلي وزوجها لا يصلي، وهي متمسكة بالصلاة مع العلم بأنها بذلت مجهودًا كبيرًا في إقناعه ليصلي، ولكنه لا يركع ولا ركعة واحدة، لديها أطفال منه، وهي تؤمل في ذلك خير، فماذا توجهونها؟ مأجورين.","title":"حكم بقاء المرأة مع زوج تارك للصلاة","answer":"الجواب: الذي لا يصلي يعتبر كافرًا، نسأل الله العافية، هذا هو أصح قولي العلماء في الموضوع؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة أخرجه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالصلاة عمود الإسلام، فالذي لا يصلي لا خير فيه، ولا يعتبر مسلمًا، وعليها أن تفارقه، ولا تمكنه من نفسها، عليها أن تفارقه، وتمنعه من نفسها، وتذهب إلى أهلها، حتى يتوب إلى الله، وحتى يسلم، ويدع عمله السيئ، هذا هو الصواب، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17898/حكم-بقاء-المراة-مع-زوج-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79104.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":18860,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثها أخ لنا من هناك يقول: المرسل أخوكم في الإسلام عوض السلمي من جدة، أخونا رسالته مطولة في الواقع فهمت منها سماحة الشيخ: أنه استمع إلى النقاش الذي تفضلتم به عن عقد الزواج على المرأة التي لا تصلي، وكثير من الناس بدأ يتساءل حول هذا الموضوع، ويريدون أن يصححوا أوضاعهم، فكيف توجهونهم؟ جزاكم الله خيرًا، وذلكم إذا تزوج رجل امرأة لا تصلي أو امرأة تزوجت رجلًا واكتشفت أنه لا يصلي، كيف توجهونهم؟جزاكم الله خيرًا.","title":"حكم عقد النكاح إذا كان أحد الزوجين لا يصلي","answer":"الجواب: هذه المسألة مسألة عظيمة، وهي ما إذا تزوج الرجل الملتزم المصلي امرأة لا تصلي أو بالعكس؛ تزوج الرجل المقصر الذي يترك الصلاة تزوج امرأة ملتزمة طيبة تحافظ على صلاتها، فذهب بعض أهل العلم إلى أنه يصح النكاح إذا كان كل منهما لا يجحد الصلاة، بل يقر بها، ويعلم أنها واجبة، ولكنه يتكاسل، وهذا هو المعروف في مذهب مالك وأبي حنيفة والشافعي -رحمة الله عليهم-. وذهب جمع من السلف إلى أن ترك الصلاة كفر أكبر، وإن لم يجحد وجوبها، وهذا ذهب إليه جمع كبير من أهل الحديث -رحمة الله عليهم-، ورواه عبد الله بن شقيق العقيلي التابعي الجليل عن أصحاب النبي -عليه الصلاة والسلام- جميعًا، وقال: «إن أصحاب النبي ﷺ كانوا لا يرون شيئًا تركه كفر إلا الصلاة» والعمدة في هذا ما ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد في مسنده وأصحاب السنن الأربع بإسناد صحيح عن بريدة . وفي صحيح مسلم عن جابر بن عبد الله الأنصاري -رضي الله عنهما- عن النبي -عليه الصلاة والسلام- أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة وهناك أحاديث أخرى في الموضوع، وهذا القول أصح القولين، وهو أن ترك الصلاة عمدًا كفر أكبر، وإن لم يجحد وجوبها في ظاهر الكتاب والسنة. فإذا تزوج الرجل الملتزم المصلي امرأة لا تصلي فإن النكاح ليس بصحيح على الصحيح، فإذا تابت جدد النكاح، وله رغبة فيها، ولها رغبة فيه يجدد النكاح، وهكذا العكس؛ لو تزوج رجل لا يصلي امرأة ملتزمة تصلي، فالنكاح ليس بصحيح أيضًا، وعليهما تجديده إذا تاب من لا يصلي، إذا تاب توبة صادقة، فإنه لا مانع من التجديد إذا كان كل واحد منهما يرغب في الآخر، هذا هو المختار، وهذا هو الأرجح من حيث الدليل، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17997/حكم-عقد-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92207.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19079,"question":"ننتقل بعد هذا إلى سؤال وصل إلى البرنامج من الأردن من أحد الإخوة المستمعين من هناك، يسأل سؤال عن امرأة تصلي، وتصوم، وصاحبة طاعة؛ إلا أنها مع رجل لا يصلي، كيف تتصرف مثل هذه المرأة؟ جزاكم الله خيرًا.","title":"حكم بقاء المرأة مع زوج لا يصلي","answer":"الجواب: إذا كان الزوج لا يصلي فالواجب عليها تركه، والذهاب إلى أهلها؛ لأن ترك الصلاة جريمة عظيمة، ومنكر عظيم، بل كفر أكبر في أصح قولي العلماء، وإن لم يجحد وجوب الصلاة، أما إن جحد وجوبها؛ فإنه يكون كافرًا بإجماع المسلمين، ليس فيه نزاع بين أهل العلم. وإنما النزاع فيما إذا تركها مع إقراره بأنها واجبة عليه، ولكن حمله الكسل، والتشاغل بالأمور الدنيا؛ فهذا هو محل النزاع. والصواب أنه يكفر بذلك؛ لقول النبي ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه رحمه الله، عن جابر بن عبد الله الأنصاري، وخرج أحمد رحمه الله، وأهل السنن بإسناد صحيح عن بريدة  عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. في أحاديث أخرى تدل على المعنى. فالواجب على كل مسلم أن يتقي الله، وأن يحافظ على الصلاة في وقتها، وأن يؤديها في الجماعة أيضًا كما شرع الله، وأن يحذر التهاون بها. ومتى تركها الإنسان فإن الزوجة يحرم عليها البقاء معه وهي مسلمة مصلية، لا تبقى معه، هذا هو الصواب، وهذا هو أرجح القولين، ومتى تاب تاب الله عليه، متى تاب وثبتت توبته أمكن الإصلاح بينه وبين زوجته. وهكذا كل من يتعاطى مكفرًا يخرجه من الإسلام يفرق بينه وبين زوجته المسلمة، حتى يعود إلى الإسلام، وحتى يتوب وبعد هذا ينظر في مراجعته لها، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18254/حكم-بقاء-المراة-مع-زوج-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79702.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":19141,"question":"أخونا يسأل عن زواج الشغار ويقول: إنه معروف لدينا باسم الزقار.الشيخ: الزقار!المقدم: نعم. يقول: من وقع فيه ومضى على زواجه سبع سنوات وأنجب بنين وبنات، كيف يتصرف؟","title":"حكم زواج الشغار وكيفية معالجته لمن وقع فيه","answer":"الجواب: نكاح الشغار -ويسميه بعض الناس نكاح البدل- هذا النكاح على حسب أسمائه يعرف بأنه اشتراط امرأة في امرأة، اشتراط أحد الوليين الزوجة الأخرى، والآخر كذلك، كل واحد يقول: زوجني بنتك وأزوجك بنتي، أو أختك وأزوجك أختي وما أشبه ذلك، هذا قد نهى عنه النبي ﷺ في الأحاديث الصحيحة \"نهى عن الشغار\"، في الصحيحين من حديث ابن عمر، وفي صحيح مسلم من حديث أبي هريرة، ومن حديث جابر، يقول النبي ﷺ: الشغار أن يقول الرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار، فإذا وقع فالصحيح أنه يكون فاسدًا. والواجب أن يجدد إذا كان لهما رغبة فيما بينهما يجدد من غير شرط المرأة الثانية، كل واحد يجدد من غير شرط المرأة الثانية، ولو مضى عليه سنوات، يجدد إذا كانت ترغب فيه و يرغب فيها، يجدد النكاح بحضرة شاهدين، وبمهر جديد، من دون أن يشترط عليه المرأة الأخرى، وهكذا الآخر، كل واحد يجدد، إذا كانت ترغب في زوجته، وهو يرغبها، أما إن كان لا يرغب أحدهما في الآخر فإنه يطلقها طلقة واحدة؛ لأن هذا النكاح فاسد، فلا بد فيه من طلقة واحدة، تمنع تعلق أحدهما بالآخر، وتحتج بها في تزوجها لغيره إذا اعتدت. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18342/حكم-زواج-الشغار-وكيفية-معالجته-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88608.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19142,"question":"رسالة وصلت إلى البرنامج من المستمع محمد صالح ناجي من الخبر، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول عن حكم من تزوج فتاة لا تصلي، أو يكون العكس أيضًا، وما حكم تارك الصلاة؟ وهل إذا مات يصلى عليه ويدفن في مقابر المسلمين؟","title":"حكم الزواج بامرأة لا تصلي","answer":"الجواب: إذا تزوج الرجل فتاة لا تصلي وهو يصلي، أو العكس: فتاة تصلي وهو لا يصلي، فالنكاح باطل على الصحيح، النكاح فاسد؛ لأنه لا يجوز للمسلم أن يتزوج الكافرة، وليس للمسلمة أن تتزوج الكافر، وترك الصلاة كفر على الصحيح، كفر أكبر، فإذا كان أحدهما يصلي، والآخر لا يصلي فإن النكاح لا يصح، بل يجب أن يجدد بعد توبة من لا يصلي، إذا تاب يجدد النكاح، إذا كان صاحبه يرغب فيه. أما إن كانا لا يصليان جميعًا فأصل النكاح صحيح، كنكاح الكفار، نكاح صحيح، وعليهما أن يتوبا إلى الله ويرجعا إلى طاعة الله ورسوله، ونكاحهما صحيح. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18339/حكم-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88607.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19241,"question":"أخ مستمع من جمهورية مصر العربية يقول: تزوجت فتاة، ولاحظت أنها لا تصلي، كيف توجهونني جزاكم الله خيرًا؟","title":"حكم الزواج بفتاة لا تصلي","answer":"الجواب: إذا كنت تصلي أنت وهي لا تصلي فالعقد غير صحيح في أصح قولي العلماء؛ لأنها بترك الصلاة تعتبر كافرة، والمسلم ليس له نكاح الكافرة إلا إذا كانت من أهل الكتاب.. من اليهود والنصارى المحصنات خاصة، أما الكافرة غير النساء المحصنات من أهل الكتاب فلا تجوز، فلا يجوز نكاحها، فإذا كنت أنت تصلي ومستقيم، وهي لا تصلي فالنكاح باطل، وعليك أن تعيد النكاح في الأصح من قولي العلماء. أما إن كنت لا تصلي مثلها فالنكاح صحيح؛ لأنه يجوز نكاح الكافر بالكافرة كما يجوز نكاح المسلم بالمسلمة، أما إذا كان أحد الزوجين لا يصلي فالنكاح غير صحيح إلا أن تكون كتابية فلا بأس، والكتابية هي اليهودية والنصرانية، فإنه يجوز للمسلم والكافر نكاحها، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/18436/حكم-الزواج-بفتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89106.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19360,"question":"إذا ابتليت المرأة برجل لا يصلي، فهل تمتنع عنه؟ أم كيف تتصرف؟ علمًا بأن لديها جمع من الأطفال، وهي صابرة على ذلكم الحال من أجل الأطفال؟","title":"حكم مَن ابتليت بزوج تارك للصلاة","answer":"الجواب: ترك الصلاة من أعظم الكبائر والجرائم، إذا كان يقر بوجوبها، ويعلم وجوبها، ويؤمن به، إما إن كان يجحد وجوبها، ولا يؤمن به؛ فهذا كافر عند جميع أهل العلم، ولا يجوز للمسلمة البقاء معه، ولا يحل لها تمكينه من نفسها؛ لأنه كافر مرتد عند جميع العلماء. أما إن كان يتركها تهاونًا وكسلًا، ولكنه يؤمن بأنها حق، وأنها فريضة؛ فهذا محل خلاف بين أهل العلم هل يكفر كفرًا أكبر، أم يكون كفره كفرًا أصغر؛ على قولين لأهل العلم، والراجح من القولين: أنه يكون كافرًا كفرًا أكبر؛ لأن الصلاة عمود الإسلام، وهي أعظم الأركان بعد الشهادتين. وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، عن بريدة بن الحصيب ، وفي صحيح مسلم رحمه الله عن جابر بن عبد الله الأنصاري رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فهذا يدل على أنه يكون كافرًا كفرًا أكبر، ولو لم يجحد الوجوب، ولهذا القول أدلة أخرى كلها تدل على أنه كافر كفرًا أكبر، كفرًا أكبر إذا تركها تهاونًا وهو يقر بوجوبها. ومن ذلك ما جاء في الأحاديث الصحيحة عن النبي ﷺ أنه قال لما سئل عن الأئمة الذين توجد منهم بعض المعاصي قال له السائل: أفنقاتلهم؟ قال: لا. ما أقاموا فيكم الصلاة وفي الرواية الأخرى: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان فجعل ترك الصلاة كفرًا بواحًا يحل مقاتلة ولاة الأمور. فالمقصود أن الواجب على المسلمين أن يحافظوا على الصلاة، وأن يؤدوها كما أمر الله، وأن يحذروا الكسل عنها، وأنهم متى تركوها جحدًا لوجوبها صار التارك كافرًا بالإجماع، وإن تركها كسلًا وتهاونًا صار كافرًا كفرًا أكبر في أصح قولي العلماء، تبين منه امرأته، ولا يحل له الاتصال بها، ولا يحل لها تمكينه من نفسها حتى يتوب إلى الله من ترك الصلاة. نسأل الله لجميع المسلمين الهداية والتوفيق، كما نسأله سبحانه أن يبصرهم في دينهم، وأن يعينهم على أداء الواجب، وأن يعيذهم من شرور النفس، وسيئات العمل. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18575/حكم-من-ابتليت-بزوج-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94203.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]},{"id":19371,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من جدة، وباعثها أخ لنا من هناك يقول: أنا محسن حميد علي السلاط ، من اليمن قرية الرزمة -فيما يبدو- أخونا يقول في أحد أسئلته:لقد ظهرت في بلادنا ظاهرة غريبة حيث أن بعضًا من الناس إذا أراد الزواج وعنده أخت أو بنت يتبادل مع شخص آخر بأن يزوج كل منهم الآخر بموليته، وكل منهم يقوم بتزويج تلك المولية بما تستحق وبما هي أهله في الزواج، ويسأل عن الحكم لو تكرمتم شيخ عبد العزيز ؟","title":"صورة نكاح الشغار وحكمه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فهذا النكاح الذي سأل عنه الأخ يسمى نكاح الشغار، ويسميه بعض الناس نكاح البدل، وهو نكاح لا يجوز؛ لأن الرسول عليه الصلاة والسلام نهى عن ذلك، ثبت عنه في الأحاديث الصحيحة من حديث ابن عمر ومن حديث أبي هريرة ومن حديث جابر ومن حديث معاوية النهي عن الشغار، وقال: الشغار أن يقول الرجل: زوجني ابنتك وأزوجك ابنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار وهو اشتراط نكاح امرأة في نكاح امرأة، سواء كانت المرأة بنته أو أخته أو بنت أخيه، المقصود أنها موليته، فهذا لا يجوز والواجب النهي عن ذلك والتحذير منه، ولو سموا مهرًا، ولو تراضوا على ذلك لا يجوز؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، والله يقول جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، ويقول جل وعلا: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63]. وثبت عن معاوية  أنه بلغه أن بعض المقيمين في المدينة تزوج امرأة على أن يزوج صاحبه امرأة عنده وسموا مهرًا، فكتب معاوية إلى أمير المدينة أن يفرق بينهما، وقال: «هذا هو الشغار الذي نهى عنه الرسول عليه الصلاة والسلام». ولم يلتفت إلى ما سموا من المهر. فالحاصل: أن هذا النكاح لا يجوز، سواء كان فيه مهر أم لم يكن فيه مهر، وسواء تراضى الجميع أو لم يتراضوا، كله ممنوع؛ لنهي النبي عن ذلك عليه الصلاة والسلام، ولأنه وسيلة إلى جبر النساء وإلزامهن بما لا يرضين به، وهذا واقع كثيرًا، ولأنه -أيضًا- وسيلة إلى تحجر النساء ولا يبادر إلى تزويجهن بالأكفاء ينتظر أن يأتي واحد يبادله، فيمسك ويحبس المرأة عنده بنته أو أخته حتى يجد من يبادله، وفيه ظلم للنساء وتعطيل لهن، والله جل وعلا حكيم عليم، ومن حكمته العظيمة أن نهى هذا النكاح لما يترتب عليه من أنواع الفساد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18592/صورة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93401.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19502,"question":"رسالة وصلت من الجزائر، السائل رمز لاسمه بـ (ح. ب) يقول: سماحة الشيخ هل يتم عقد الزواج إذا كان أحد الأشخاص من الزوجين لا يصلي، أو إذا كان أيضًا الزوجان لا يصليان، ما حكم الزواج في مثل هذه الحالة مأجورين؟","title":"حكم النكاح إذا كان أحد الزوجين لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذا الموضوع يراجع فيه الجهات المختصة المحكمة أو الجهات المختصة بالإذن في النكاح؛ لأن فيه تفصيلًا، فالذي يصلي لا يجوز له أن ينكح من لا تصلي الكافرة، والتي تصلي والخاطب لا يصلي ليس لها أن تتزوج عليه؛ لأن الله جل وعلا يقول: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا[البقرة:221]، ويقول: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10]، فلا يجوز أن تنكح المسلمة الكافر، ولا يجوز للكافر أن ينكح المسلمة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18748/حكم-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94601.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19620,"question":"يقول هذا السائل يا سماحة الشيخ: البعض من الناس يتزوجون بطريقة البدل، أي: أعطيك امرأة من قريباتي، وتعطيني امرأة بدلها، فما حكم هذا الزواج؟","title":"حكم زواج البدل بين الأقارب","answer":"الجواب: هذا لا يجوز، نكاح البدل هذا نكاح الشغار، الرسول ﷺ نهى عنه ولا يجوز، ولعن من فعله، وسماه التيس المستعار، فلا يجوز هذا لا بد أن ينكح عن رغبة، من دون شغار، أما أن يقول: زوجني وأزوجك هذا ما يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/18884/حكم-زواج-البدل-بين-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94816.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19663,"question":"تقول سماحة الشيخ: امرأة تصلي وتصوم وعندها أولاد والزوج لا يصلي، ونصحته عدة مرات، ولكنه لم يستجب ماذا تعمل؟ هل يجوز لها أن تبقى معه؟","title":"ماذا يجب على المرأة إذا كان زوجها لا يصلي؟","answer":"الجواب: ليس لها أن تبقى معه، بل عليها أن تفارقه، وليس لها أن تمكنه من نفسها، وعليها أن تطلب الفراق ولو من المحكمة، يجب عليها أن تفارقه، وأن تذهب إلى أهلها، وهي أولى بأولادها منه الصغار، ولا يجوز لها البقاء معه؛ لأن من ترك الصلاة كفر، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة نسأل الله العافية. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18952/ماذا-يجب-على-المراة-اذا-كان-زوجها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95017.mp3","categories":["الأنكحة المحرمة","حكم الصلاة وأهميتها"]}]
